window.CS_GLOSSARY = [["1/5 success rule","Rechenberg's rule to grow the mutation step size when more than a fifth of mutations improve the parent, and shrink it otherwise.","open-ended/chapters/02-evolutionary-algorithms.html","oe","A1 A4"],["16 bytes per parameter","The memory cost of mixed-precision training with AdamW: 2 for bf16 weights, 2 for gradients, 4 for the fp32 master copy and 4 each for Adam's two moments.","deep-learning/chapters/16-resource-accounting.html","dl","A1"],["6ND rule","The estimate that training a dense Transformer on D tokens takes about 6 times its parameter count N times D floating-point operations: 2 per weight per token forward and 4 backward.","deep-learning/chapters/16-resource-accounting.html","dl","A1"],["6ND rule","The approximation that training a dense transformer with N parameters on D tokens costs about 6 x N x D floating-point operations.","ml-foundations/chapters/17-compute-costs.html","mlf","A1"],["6ND rule","The approximation that training a Transformer costs about 6 floating-point operations per parameter per token.","research-eng/chapters/03-scaling-mup.html","re","A1"],["95% confidence interval","The estimate plus or minus 1.96 standard errors: a range built so that about 95 percent of intervals made this way contain the true value.","evals/chapters/04-eval-statistics.html","evl","A1 A2 A3"],["A2A (Agent2Agent protocol)","An open protocol, now under the Linux Foundation, for one agent to discover, delegate work to and receive results from another agent without seeing its internals.","agents/chapters/09-agent-to-agent.html","agt",""],["A2A task","A stateful unit of work with an id, a context, a status and artifacts, which a client can poll, cancel or resume.","agents/chapters/09-agent-to-agent.html","agt",""],["Ablation","An experiment that removes or changes one step of a pipeline and measures the effect, usually by training a small model with and without it.","llm-training/chapters/01-pretraining-data.html","llm",""],["Ablation","An experiment that removes one component of a method to see how much the result depends on it.","ml-foundations/chapters/16-reading-papers.html","mlf","A1"],["Ablation","Removing or switching off one component of a system to measure how much it contributes.","research-eng/chapters/04-ablations-tracking.html","re","A1"],["AB-MCTS","Adaptive-branching Monte Carlo tree search, which at each node chooses between generating a new answer and refining an existing one using Thompson sampling.","open-ended/chapters/08-inference-time-search.html","oe","A2"],["Absent from what I read","An audit entry meaning the point was not in the material read, which says nothing about whether the authors did it.","rsi-measurement/chapters/04-reading-claims.html","rsi","A4"],["Absolute error","The loss |y - f|, which is the negative log-likelihood of Laplace noise and whose minimiser is the median.","ml-foundations/chapters/13-likelihood-losses.html","mlf",""],["Abstention","A model declining to answer, for example by saying it does not know, instead of guessing.","evals/chapters/10-hallucination.html","evl",""],["Abstention threshold","The confidence level below which a system declines to answer, chosen from the cost of a wrong answer and tuned on held-out data.","evals/chapters/11-grounding-abstention.html","evl",""],["Acceptance rate","The share of outer-loop steps whose candidate passes the gate.","rsi-measurement/chapters/03-loop-economics.html","rsi","A4"],["Accessibility tree","A machine-readable hierarchy of interface elements with roles, names and states, exposed for assistive technology and usable as a compact text observation for agents.","agents/chapters/17-computer-use.html","agt",""],["Accumulating versus replacing data","Two ways to build each generation's training set: adding synthetic data to the real data avoids collapse in the cited studies, while replacing real data with synthetic data leads to it.","llm-training/chapters/15-distillation.html","llm",""],["Actionable error","A tool error that says what went wrong, what is valid and whether anything changed, so the model's next call can be a fix and not a repeat.","agents/chapters/05-tool-design.html","agt","A2"],["Action check","A guardrail that inspects a proposed tool call and its arguments before it runs, often as an exact rule in code.","evals/chapters/15-guardrails.html","evl",""],["Action selector","A pattern in which the model only chooses among a fixed set of predefined actions and never sees tool output.","evals/chapters/14-architectural-defences.html","evl",""],["Activation checkpointing","Keeping only some activations and recomputing the rest during the backward pass, to save memory at the cost of extra compute.","deep-learning/chapters/02-backpropagation.html","dl",""],["Activation checkpointing","Saving only some layers' inputs and recomputing the rest during the backward pass, trading about one extra forward pass for much less activation memory.","llm-training/chapters/02-gpu-memory.html","llm","A1"],["Activation function","An elementwise non-linear function, such as ReLU or GELU, applied to a layer's pre-activations.","deep-learning/chapters/01-neurons-layers.html","dl",""],["Activation patching","Copying an activation from one run of a model into another run and measuring how the output changes, to test whether that activation matters.","deep-learning/chapters/23-interpretability-basics.html","dl","A2"],["Activation recomputation","Also called gradient checkpointing: discarding most activations in the forward pass and recomputing them during the backward pass, trading about a third more compute for much less memory.","deep-learning/chapters/16-resource-accounting.html","dl","A1"],["Activations","The intermediate tensors produced during the forward pass, which must be kept for the backward pass.","deep-learning/chapters/02-backpropagation.html","dl",""],["Activations","The intermediate outputs of each layer saved during the forward pass so the backward pass can compute gradients; their size grows with batch and sequence length.","llm-training/chapters/02-gpu-memory.html","llm","A1"],["Activations","The intermediate tensors saved during the forward pass because the backward pass needs them.","ml-foundations/chapters/09-autodiff.html","mlf",""],["Active parameters","The weights a single token actually uses: the shared parts plus its k chosen experts per layer; this sets the FLOPs per token.","deep-learning/chapters/20-mixture-of-experts.html","dl",""],["Activity","In Temporal, a unit of work that touches the outside world, whose result is stored in the history and reused during replay instead of running again.","agents/chapters/15-durable-execution.html","agt",""],["Adam","An optimiser that divides a running average of the gradient by the square root of a running average of its square, giving each weight a step of about the learning rate.","ml-foundations/chapters/10-optimisers.html","mlf",""],["AdamW","Adam with weight decay applied outside the adaptive update, so that the decay strength does not depend on gradient size.","deep-learning/chapters/04-deep-regularisation.html","dl",""],["AdamW","Adam with weight decay applied directly to the weights rather than through the gradient, so decay does not depend on gradient scale.","ml-foundations/chapters/10-optimisers.html","mlf",""],["Adapter","The small set of trainable parameters added to a frozen model, such as LoRA's A and B matrices, that can be saved, swapped or merged.","llm-training/chapters/11-lora.html","llm",""],["Adapter (framework seam)","A thin file that translates between your own tools, state and evaluation cases and one framework's objects, so the framework can be replaced by writing another adapter.","agents/chapters/21-frameworks.html","agt",""],["Adapter merging","Adding the product of the LoRA factors, scaled, into the base weights so that the tuned model has the original architecture and no extra latency.","llm-training/chapters/11-lora.html","llm",""],["Adaptive attack","An attack designed with knowledge of a specific defence and refined using its responses, as opposed to a fixed list of known attack strings.","evals/chapters/13-prompt-injection.html","evl",""],["Adaptive KL controller","A rule that raises or lowers the KL coefficient during training so that the measured KL stays near a target value.","llm-training/chapters/08-ppo.html","llm",""],["Adaptive overfitting","Loss of validity when a held-out set is reused to guide decisions that depend on earlier results from the same set.","open-ended/chapters/16-held-out-evaluation.html","oe","A2 A3"],["Adjoint","The derivative of the final output with respect to an intermediate node, stored as its grad in reverse mode.","ml-foundations/chapters/09-autodiff.html","mlf",""],["Adjudication","Resolving items on which annotators disagree by having a senior reviewer decide and record the reason.","evals/chapters/05-human-labels.html","evl",""],["Advantage","How much better a response or action was than expected, usually the reward minus a baseline.","llm-training/chapters/07-policy-gradients.html","llm",""],["Adversarial validation","Training a classifier to tell training rows from test rows; an AUC well above 0.5 shows the sets differ and which columns give them away.","ml/chapters/14-leakage.html","ml",""],["Agent","A system in which a language model repeatedly chooses actions or tools, sees the results and decides what to do next until it finishes or a limit stops it.","agents/chapters/00-start-here.html","agt",""],["Agent archive","A growing store of every discovered agent with its score, kept even when an agent scored worse than its parent so that its ideas can be reused later.","open-ended/chapters/12-meta-agent-search.html","oe","A2 A4"],["Agent budget","A limit on sub-agent count, depth, steps, tokens or wall-clock time that is enforced in code rather than requested in a prompt.","agents/chapters/14-multi-agent.html","agt",""],["Agent card","A JSON document in which an agent describes its name, interfaces, capabilities, security requirements and skills, so clients can discover and call it.","agents/chapters/09-agent-to-agent.html","agt",""],["Agent card signing","Signing a canonicalised agent card with a JSON Web Signature so a client can verify its publisher and detect alteration.","agents/chapters/09-agent-to-agent.html","agt",""],["Agent-computer interface (ACI)","The set of tools, formats and feedback through which a language model operates a system, designed with the care a human interface gets.","agents/chapters/05-tool-design.html","agt","A2"],["Agent framework","A library that packages the agent loop together with a tool registry, state, tracing and retry rules, so that you write less plumbing and accept some behaviour you did not write.","agents/chapters/21-frameworks.html","agt",""],["Agent harness","A complete working agent, with built-in tools, permissions and context management, that you embed and configure rather than assemble.","agents/chapters/21-frameworks.html","agt",""],["Agent harness (scaffold)","The code around a model that lets it act as an agent: prompts, tools, loop and limits, evaluated together with the model.","evals/chapters/08-agent-evals.html","evl","A3"],["Agentic Context Engineering (ACE)","A method that treats context as an evolving playbook of itemised bullets, updated incrementally by generation, reflection and curation.","harness-eng/chapters/01-harness-engineering.html","he","A2"],["Agentic tree search (experiments)","A search in which each node is a version of experiment code with its results, buggy nodes are debugged and working nodes are refined best-first.","open-ended/chapters/14-automated-science.html","oe","A4"],["Agent lineage","The recorded chain of parent-to-child modifications leading to a given agent, which lets reviewers read every change that produced it.","open-ended/chapters/13-self-improving-agents.html","oe","A4"],["Agent loop","The cycle of asking the model, running the tools it requested, appending the results to the conversation and asking again.","agents/chapters/00-start-here.html","agt",""],["AGENTS.md","An open, plain-Markdown convention for a repository's instructions to coding agents, read by many tools and stewarded by the Agentic AI Foundation.","agents/chapters/22-ai-coding-tools.html","agt",""],["Agents Rule of Two","Meta's guideline that within one session an agent should satisfy no more than two of: untrusted input, sensitive access, and the ability to change state or communicate externally.","agents/chapters/19-agent-security.html","agt","A3"],["Agents Rule of Two","A design rule that an agent session should have at most two of: untrusted input, sensitive access, and the ability to change state or communicate externally.","evals/chapters/14-architectural-defences.html","evl",""],["AI control","A research area that asks how to get useful work from a model while assuming it may be trying to undermine the safeguards.","control/chapters/00-start-here.html","ctl","A3"],["AIDE","An agent that treats machine-learning engineering as a tree search over single-file scripts, with draft, debug and improve operators.","harness-eng/chapters/02-aide-tree-search.html","he","A2"],["AI delegation","Handing the writing of code entirely to an assistant, which was associated with the lowest quiz scores in Anthropic's 2026 study.","ml-foundations/chapters/19-ai-assistants.html","mlf",""],["AI-generating algorithm","An approach that aims to produce general intelligence by meta-learning architectures, learning algorithms and automatically generated environments.","open-ended/chapters/05-open-ended-algorithms.html","oe","A4"],["AI-generating algorithms (AI-GAs)","Jeff Clune's programme of meta-learning architectures, learning algorithms and learning environments so that AI is produced by algorithms rather than hand design.","open-ended/chapters/12-meta-agent-search.html","oe","A2 A4"],["AI incident","An event in which an AI system's behaviour causes or nearly causes harm or a serious breach of expectations, whether or not anything is technically down.","evals/chapters/20-ai-incidents.html","evl",""],["AI management system","The policies, roles, processes and records by which an organisation governs its AI activity, as specified and audited under ISO/IEC 42001.","evals/chapters/21-governance.html","evl",""],["AI Risk Management Framework","NIST's voluntary framework, released in January 2023, that organises AI risk work into the functions Govern, Map, Measure and Manage.","evals/chapters/21-governance.html","evl",""],["AI systems engineer","An engineer who delivers a working, measured and safe system in which a learned model does part of the work.","ml-foundations/chapters/00-start-here.html","mlf",""],["Aliasing","Two names referring to the same mutable object, so a change through one name is visible through the other.","ml-foundations/chapters/01-python-numerics.html","mlf",""],["ALiBi","Attention with Linear Biases: a fixed penalty proportional to token distance, with a different slope per head, added to the attention scores.","deep-learning/chapters/11-positions.html","dl",""],["All-gather","A collective in which each GPU contributes a slice and afterwards every GPU holds the full concatenation.","llm-training/chapters/03-parallelism.html","llm",""],["All-reduce","A collective after which every GPU holds the element-wise sum (or average) of the tensors all GPUs started with.","llm-training/chapters/03-parallelism.html","llm",""],["AlphaEvolve","A DeepMind coding agent that evolves marked regions of whole codebases using model-written diffs, staged evaluation and an archive of programs.","open-ended/chapters/09-program-evolution.html","oe","A4"],["AlphaZero","A system that learns games by self-play, training a policy and value network on the visit counts and results of its own tree search.","open-ended/chapters/01-tree-search.html","oe","A2"],["Amdahl's law","The overall speed-up from speeding up a fraction f of a job by a factor s is 1 / ((1 - f) + f / s).","rsi-measurement/chapters/02-automation-levels.html","rsi","A4"],["Ancestral sampling","Generating text by drawing each token from the model's full next-token distribution and appending it.","deep-learning/chapters/15-decoding.html","dl",""],["Anchor","A copy of the log's head fingerprint kept where the proposer cannot rewrite it, which exposes truncation and full rewrites.","control/chapters/03-attested-results.html","ctl","A3"],["Anchoring (in labelling)","The tendency of an annotator who sees a suggested label to accept it, which inflates agreement without improving reliability.","evals/chapters/05-human-labels.html","evl",""],["Anchor subset","A fixed part of a benchmark kept unchanged across versions so scores stay comparable while other items are refreshed.","evals/chapters/07-contamination.html","evl","A2 A3"],["Annealing (data)","A final stretch of training, as the learning rate falls to zero, in which the mix is shifted towards very high-quality data.","llm-training/chapters/01-pretraining-data.html","llm",""],["ANNECS","Accumulated number of novel environments created and solved, a measure of whether a system keeps producing new solvable challenges.","open-ended/chapters/05-open-ended-algorithms.html","oe","A4"],["Annotator","A person who assigns labels to items by following a guideline.","evals/chapters/05-human-labels.html","evl",""],["Append-only log","A file where new records are only added at the end and old ones never change, so a crash can damage only the last record.","ml-foundations/chapters/22-running-candidates.html","mlf","A1"],["Approval fatigue","The tendency of people to approve prompts without reading them when prompts are frequent, which defeats confirmation as a control.","agents/chapters/20-sandboxing.html","agt","A2"],["Approval fatigue","The habit of approving prompts without reading them when they are too frequent or too vague, which turns a human gate into a rubber stamp.","evals/chapters/14-architectural-defences.html","evl",""],["Approval gate","A point in a run where the agent proposes an action and stops until a human decision, recorded as an event bound to the exact arguments, allows it to continue.","agents/chapters/15-durable-execution.html","agt",""],["Archive","A dictionary or set that stores the candidates seen so far, keyed by a hashable field, so duplicates are noticed and the best are kept.","ml-foundations/chapters/20-functions-objects.html","mlf","A1"],["Archive","The stored record of every candidate tried so far and its score, from which parents are chosen.","open-ended/chapters/00-start-here.html","oe",""],["Arena (pairwise preference leaderboard)","A leaderboard built from users voting between two anonymous model answers to their own prompts.","evals/chapters/09-leaderboards.html","evl",""],["Argument validation","Checking a model's tool arguments against the schema in your own code before running the tool, whatever the provider guarantees.","agents/chapters/06-function-calling.html","agt",""],["Arithmetic intensity","The number of floating-point operations an algorithm performs per byte it moves to and from main memory.","llm-training/chapters/04-kernels.html","llm","A3"],["Arithmetic intensity","The number of floating-point operations an algorithm performs per byte it moves to or from memory.","ml-foundations/chapters/17-compute-costs.html","mlf","A1"],["Artefact","A finished output such as working code, as opposed to the skill of being able to produce and explain it yourself.","ml-foundations/chapters/19-ai-assistants.html","mlf",""],["Artifact 1 (autoresearch-rs)","The first artifact: Karpathy's autoresearch loop with a Rust runner, extended to log the gap between proxy gain and held-out gain.","research-eng/chapters/00-start-here.html","re","A1"],["Artifact 2","The mini-FML search study: an AIDE-style tree-search agent compared with greedy hill-climbing on three FML-Bench tasks.","harness-eng/chapters/00-start-here.html","he","A2"],["Artifact 3","The evaluator-hardening kit: break a KernelBench grader, harden it, and measure the hacking rate before and after.","harness-eng/chapters/00-start-here.html","he","A2"],["Artifact 4","The capstone artifact: a small-scale replication of Weco's AIDE² outer loop, judged by the four Level-1 conditions.","rsi-measurement/chapters/00-start-here.html","rsi","A4"],["Artifact (A2A)","An output of an A2A task, made of parts such as text, a file or structured data, as distinct from the messages of the conversation.","agents/chapters/09-agent-to-agent.html","agt",""],["Artifact (course)","One of four public pieces of work in this path, each a replication of a published result at small scale plus one honest extension, released as code and a write-up.","research-eng/chapters/00-start-here.html","re","A1"],["As-of join","A join that attaches to each prediction only the most recent record that was already known at the prediction time.","ml/chapters/14-leakage.html","ml",""],["Associative","Of an operation, giving the same result however the terms are grouped; real addition is, but floating-point addition is not.","ml-foundations/chapters/01-python-numerics.html","mlf",""],["Asynchronous checkpointing","Copying training state to host memory quickly and writing it to storage in the background, so GPUs pause only for the copy.","llm-training/chapters/05-long-runs.html","llm","A1"],["Asynchronous execution","Queuing GPU work and returning at once, so that Python runs ahead while the GPU computes.","deep-learning/chapters/05-pytorch.html","dl",""],["At-least-once","A delivery guarantee under which an action is retried until acknowledged, so it may happen more than once and the receiver must tolerate repeats.","agents/chapters/15-durable-execution.html","agt",""],["Atomic claim","A statement of exactly one fact, so that it can be judged true or false without the rest of the text.","evals/chapters/12-fact-checking.html","evl",""],["Atomic fact","A short statement containing one piece of information, used as the unit when scoring long-form text for factual precision.","evals/chapters/10-hallucination.html","evl",""],["Attack budget","What the attacker may spend, such as queries, time, tools and knowledge of the system; an attack success rate means nothing without it.","evals/chapters/16-red-teaming.html","evl","A3"],["Attack goal","A concrete, observable outcome an attacker is trying to cause, such as a refund above the limit or data sent to an outside address.","evals/chapters/16-red-teaming.html","evl","A3"],["Attack success rate","The fraction of attack attempts that achieve the attacker's goal, defined by an observable effect and reported with the attacker's budget.","evals/chapters/13-prompt-injection.html","evl",""],["Attack success rate (ASR)","The share of attack attempts or goals that reached the goal under a stated attacker model and budget.","evals/chapters/16-red-teaming.html","evl","A3"],["Attention","Letting a model, at each output step, take a weighted sum over all states of the input, with weights computed from the current need.","deep-learning/chapters/08-sequences-rnns.html","dl",""],["Attention budget","The idea that each added token draws down the finite attention a model can spend, so more context has diminishing and sometimes negative returns.","agents/chapters/10-context-engineering.html","agt","A2"],["Attention head","One of the parallel attention operations in a multi-head layer, with its own query, key and value projections.","deep-learning/chapters/09-attention.html","dl",""],["Attention sink","The first tokens of a sequence, where softmax puts weight that no content deserves, and which a sliding window should keep.","deep-learning/chapters/19-efficient-attention.html","dl","A3"],["Attention weights","The softmax output for one query: non-negative numbers over the positions it may read, summing to one.","deep-learning/chapters/09-attention.html","dl",""],["Attested result","A tool result whose origin and content a third party can verify without trusting the agent that triggered it.","control/chapters/03-attested-results.html","ctl","A3"],["Attested result","A result signed with a key the proposer never holds and bound to the hash of the code it describes.","harness-eng/chapters/03-splits-attestation.html","he","A3"],["Attribution","Whether each statement in an answer is supported by the source it cites (the Attributable to Identified Sources idea).","evals/chapters/12-fact-checking.html","evl",""],["Audit","A careful review, by a trusted person or model, of an item the monitor flagged.","control/chapters/04-transcript-monitor.html","ctl","A3"],["Audit budget","The fraction of items a person has time to read, which fixes the monitor's threshold.","control/chapters/04-transcript-monitor.html","ctl","A3"],["Audit checklist","Ten questions put to a claim, each answered as reported, claimed or absent with the supporting passage.","rsi-measurement/chapters/04-reading-claims.html","rsi","A4"],["Autograd","PyTorch's automatic differentiation: it records operations as code runs and applies the chain rule backwards to produce gradients.","deep-learning/chapters/05-pytorch.html","dl",""],["Automated Design of Agentic Systems (ADAS)","The research area of automatically creating agent designs, including new building blocks and new ways of combining them, instead of designing them by hand.","open-ended/chapters/12-meta-agent-search.html","oe","A2 A4"],["Automated reviewer","A language-model system that scores a paper using an ensemble of reviews and a meta-review, validated against real accept and reject decisions.","open-ended/chapters/14-automated-science.html","oe","A4"],["Automatic curriculum","A mechanism, often a language model, that proposes the agent's next task based on what it has done and failed so far.","open-ended/chapters/07-lifelong-agents.html","oe","A4"],["Automatic differentiation","Computing exact derivatives of a program by applying the chain rule to its recorded elementary operations, neither by small steps nor by symbolic algebra.","ml-foundations/chapters/09-autodiff.html","mlf",""],["Automation level","A 0 to 5 rating of how much AI does a task, from not used to autonomous.","rsi-measurement/chapters/02-automation-levels.html","rsi","A4"],["Autoregressive generation","Producing text one token at a time, appending each chosen token to the context before predicting the next.","deep-learning/chapters/12-building-gpt.html","dl","A1"],["autoresearch","Karpathy's repository in which an agent edits train.py, trains for five minutes and keeps the change only if validation bits per byte improve.","research-eng/chapters/01-research-loop.html","re","A1"],["Auxiliary load-balancing loss","A small extra loss, proportional to the sum of each expert's token share times its mean router probability, that pushes routing towards even use.","deep-learning/chapters/20-mixture-of-experts.html","dl",""],["Average precision","The mean of the precision values at each rank where a true positive appears, approximating the area under the precision-recall curve.","ml/chapters/02-framing-metrics.html","ml",""],["Axial coding","A second pass that groups open-coding notes into named categories and counts them.","evals/chapters/01-error-analysis.html","evl",""],["Backpropagation","The algorithm that computes the gradient of the loss with respect to every parameter by applying the chain rule backwards through the network.","deep-learning/chapters/00-start-here.html","dl",""],["Backpropagation through time","Training a recurrent network by unrolling it over the sequence and backpropagating through every step, summing gradients for the shared weights.","deep-learning/chapters/08-sequences-rnns.html","dl",""],["Balanced accuracy","The average of the share of accepted papers correctly accepted and the share of rejected papers correctly rejected, which is 0.5 for a reviewer that ignores the paper.","open-ended/chapters/14-automated-science.html","oe","A4"],["Bandit LLM ensemble","Using a bandit algorithm such as UCB1 to learn, from the improvements each model has produced, which model to call for the next mutation.","open-ended/chapters/10-evolution-frameworks.html","oe","A4"],["Baseline","A number subtracted from the reward before it weights the score, which lowers the variance of the gradient estimate without changing its expectation if it does not depend on the sampled action.","llm-training/chapters/07-policy-gradients.html","llm",""],["Baseline","The simpler or previous method a new result is compared against, which is only fair if it gets equal tuning, data and compute.","ml-foundations/chapters/16-reading-papers.html","mlf","A1"],["Base model","A model trained only to predict the next token over a very large text corpus, which continues text rather than following instructions.","llm-training/chapters/00-start-here.html","llm",""],["Basis vector","One of the standard unit vectors e1, e2, ...; the columns of a matrix are the images of these.","ml-foundations/chapters/06-matrices.html","mlf",""],["Batch","Several independent windows stacked into one (B, T) array so they are processed by the same matrix multiplications.","deep-learning/chapters/12-building-gpt.html","dl","A1"],["Batch","A group of examples stacked as the rows of a matrix so that one product processes them all.","ml-foundations/chapters/06-matrices.html","mlf",""],["Batch normalisation","Rescaling each feature to zero mean and unit variance using statistics computed across the mini-batch.","deep-learning/chapters/03-training-dynamics.html","dl","A1"],["Bayes' rule","The identity P(H | E) = P(E | H) P(H) / P(E) that turns a likelihood and a prior into a posterior.","ml-foundations/chapters/12-probability.html","mlf",""],["Beam search","A search that keeps the several best partial sequences at each step and extends them all, to find a high-probability whole sequence.","deep-learning/chapters/15-decoding.html","dl",""],["Behavioural cloning","Training a policy to imitate an expert's actions directly, with no reward signal; SFT is behavioural cloning for language models.","llm-training/chapters/10-sft.html","llm",""],["Behaviour characterisation","A designer-chosen description of what a candidate does, used to measure how different two candidates are.","open-ended/chapters/03-novelty-search.html","oe",""],["Behaviour descriptor","A short vector, chosen by the designer, describing what a solution does, used to decide which archive cell it belongs to.","open-ended/chapters/04-quality-diversity.html","oe","A4"],["Behaviour space","The space of all possible behaviour descriptor values, in which nearby points mean similar behaviour.","open-ended/chapters/04-quality-diversity.html","oe","A4"],["Bellman equation","A recursion stating that a state's value equals the expected immediate reward plus the discounted value of the next state.","llm-training/chapters/06-bandits-mdps.html","llm",""],["Benchmark","A curated, versioned set of items with trusted answers and a fixed scoring rule, designed so different systems and dates can be compared.","evals/chapters/06-building-benchmarks.html","evl","A2"],["Benchmark decay","The loss of a benchmark's meaning over time as the world, the users and the systems it was written for change.","evals/chapters/07-contamination.html","evl","A2 A3"],["Benchmark retirement","Withdrawing a benchmark from claims and rankings, with its reason announced, its version archived and a successor named.","evals/chapters/07-contamination.html","evl","A2 A3"],["Best-of-n","Sampling n candidate answers and returning the one a selector such as a test suite or verifier ranks highest.","open-ended/chapters/08-inference-time-search.html","oe","A2"],["Best-of-n sampling","Drawing n candidate responses, scoring each with a reward model and returning the highest, a simple way to optimise against a reward without training.","llm-training/chapters/13-reward-models.html","llm","A3"],["Best-shot prompting","Listing earlier programs as numbered versions sorted by score, ending with the header of the next version, so the model continues the improvement.","open-ended/chapters/09-program-evolution.html","oe","A4"],["Beta (DPO)","The coefficient that sets how far the policy may move from the reference: a small value allows large changes, a large value keeps the policy close.","llm-training/chapters/12-preference-optimisation.html","llm",""],["bf16","A 16-bit floating-point format with fp32's 8 exponent bits and only 7 mantissa bits, giving fp32's range at lower precision and needing no loss scaling.","deep-learning/chapters/17-training-stability.html","dl","A1"],["bfloat16","A 16-bit floating-point format with the exponent range of 32-bit floats but only about 8 significant bits, widely used for training.","llm-training/chapters/02-gpu-memory.html","llm","A1"],["bfloat16","A 16-bit format with float32's 8 exponent bits and only 7 mantissa bits, trading precision for a wide range.","ml-foundations/chapters/11-numerics.html","mlf",""],["Bias","A learned constant added to a neuron's weighted sum that shifts where it switches on.","deep-learning/chapters/01-neurons-layers.html","dl",""],["Bi-encoder","A model with separate query and passage encoders whose vectors are compared by dot product, so passage vectors can be computed offline.","agents/chapters/23-dense-retrieval.html","agt","A2"],["Bigram model","A language model that predicts the next symbol from only the one symbol before it, using counted frequencies.","deep-learning/chapters/00-start-here.html","dl",""],["Binary cross-entropy","The loss for a yes/no label, -[y ln p + (1 - y) ln(1 - p)], whose gradient with respect to the logit is p - y.","ml-foundations/chapters/13-likelihood-losses.html","mlf",""],["Binary grading","Scoring each answer as right (1) or not right (0), which gives no credit for abstaining and so rewards guessing.","evals/chapters/10-hallucination.html","evl",""],["Bit (information)","The unit of information when logarithms are base 2: the surprise of a fair coin landing heads, or one yes/no question.","ml-foundations/chapters/14-information-theory.html","mlf",""],["Bits per byte","The total information the model needs per byte of original text, a unit that stays comparable across different tokenisers.","deep-learning/chapters/14-language-modelling.html","dl","A1"],["Bits per byte","A model's total cross-entropy on a text divided by the text's size in bytes, which compares models regardless of their tokenisers.","ml-foundations/chapters/14-information-theory.html","mlf",""],["Bitwise reproducibility","Producing identical output bytes on a rerun, which is hard to guarantee for parallel or GPU code.","ml-foundations/chapters/04-reproducible-experiments.html","mlf","A1"],["Blameless post-incident review","A review that explains what happened and which controls failed without assigning fault to a person.","control/chapters/05-incident-playbook.html","ctl","A3"],["Blameless postmortem","A review that asks what in the system allowed an incident, not who erred, and ends in tracked changes.","evals/chapters/20-ai-incidents.html","evl",""],["Blast radius","The set of data, systems and people affected if one component misbehaves.","evals/chapters/14-architectural-defences.html","evl",""],["Bloat","Growth in program size over generations without any gain in fitness, usually from useless padding that shields good code from crossover.","open-ended/chapters/20-gp-neuroevolution-cmaes.html","oe",""],["Blue team","The group that builds and defends the system being attacked.","evals/chapters/16-red-teaming.html","evl","A3"],["Bootstrap","Estimating an interval by recomputing the score on many pseudo-evals made by resampling the independent units with replacement.","evals/chapters/04-eval-statistics.html","evl","A1 A2 A3"],["Bootstrap","Estimating how a statistic varies by recomputing it on many resamples of the data drawn with replacement.","ml-foundations/chapters/15-statistics.html","mlf","A1"],["Bootstrap","Estimating an interval by resampling the observed differences with replacement many times.","rsi-measurement/chapters/01-level-one.html","rsi","A4"],["Bootstrap interval","A confidence interval from resampling the observed values with replacement many times.","research-eng/chapters/06-write-up.html","re","A1"],["Bootstrapping","Updating an estimate towards a target that itself contains an estimate, such as a reward plus the critic's value of the next state.","llm-training/chapters/09-value-functions.html","llm",""],["Boring variant","A task that is only a minor change to one the agent has already learned, such as the same job with a different number.","open-ended/chapters/06-interestingness.html","oe",""],["Borrowing (Rust)","Lending a reference to a value for a while without giving up ownership of it.","research-eng/chapters/05-rust-runner.html","re","A1"],["Boxed value","A number stored as a separate heap object with a header, as every Python int and float is, rather than as raw bytes.","ml-foundations/chapters/01-python-numerics.html","mlf",""],["Bradley-Terry model","A model in which the chance that one item beats another is a logistic function of the difference in their strengths, fitted to pairwise outcomes.","evals/chapters/09-leaderboards.html","evl",""],["Bradley-Terry model","A model in which the probability that one item beats another is the sigmoid of the difference of their hidden scores, used to turn comparisons into a reward loss.","llm-training/chapters/12-preference-optimisation.html","llm",""],["Break-even utilisation","The share of time a rented GPU must be busy for its cost per token to match a per-token API price.","llm-training/chapters/22-token-economics.html","llm","A1"],["Brevity bias","The tendency of a model that rewrites a context to drop domain detail in favour of a shorter summary.","harness-eng/chapters/01-harness-engineering.html","he","A2"],["Brief","The instruction a lead gives a sub-agent, stating an objective, output format, guidance on tools and sources, and clear task boundaries.","agents/chapters/14-multi-agent.html","agt",""],["Broadcasting","The rule that lets arrays of different shapes combine by aligning shapes from the right and stretching axes of size 1.","ml-foundations/chapters/02-numpy-arrays.html","mlf",""],["BrowseComp","An OpenAI benchmark of 1,266 questions that require persistent web browsing to find hard-to-find information and have short, easily checked answers.","agents/chapters/16-deep-research.html","agt",""],["Browser agent","A computer-use agent restricted to a web browser, where page structure and accessibility information are available and the environment is easier to sandbox.","agents/chapters/17-computer-use.html","agt",""],["Budget cap","A hard ceiling, enforced outside the loop, on something the run consumes such as dollars, tokens, GPU hours or time.","control/chapters/05-incident-playbook.html","ctl","A3"],["Building block hypothesis","The idea that good solutions are assembled from short high-quality fragments that crossover can combine.","open-ended/chapters/02-evolutionary-algorithms.html","oe","A1 A4"],["Builtins","The names Python gives every program without an import, such as len, open and __import__, which a restricted namespace can replace with a short list.","ml-foundations/chapters/21-programs-as-data.html","mlf","A1"],["Byte-level tokenisation","Using the 256 byte values as the base alphabet so that any string can be encoded and no input is ever unknown.","deep-learning/chapters/13-tokenisation.html","dl","A1"],["Byte-pair encoding","A tokenisation method that builds a vocabulary by repeatedly merging the most frequent adjacent pair of tokens in a training text.","deep-learning/chapters/13-tokenisation.html","dl","A1"],["Caching allocator","A framework component that keeps freed GPU memory blocks for reuse, so tools report more memory reserved than tensors actually use.","llm-training/chapters/02-gpu-memory.html","llm","A1"],["Calibrated model","A model whose stated confidence matches how often it is actually right.","evals/chapters/10-hallucination.html","evl",""],["Calibration","The property that among answers given a stated confidence, about that fraction are actually correct.","evals/chapters/11-grounding-abstention.html","evl",""],["call_id","The identifier that ties a function result back to the model's call in OpenAI's Responses API, equivalent to tool_use_id in Anthropic's.","agents/chapters/06-function-calling.html","agt",""],["CaMeL","A defence that extracts control and data flow from the trusted query and uses capabilities to enforce policy at tool-call time.","agents/chapters/19-agent-security.html","agt","A3"],["CaMeL","A defence that takes control flow only from the trusted request and tracks the provenance of every value, enforcing policies in an interpreter before tool calls.","evals/chapters/14-architectural-defences.html","evl",""],["Canary release","Sending a small share of real traffic to a new version first and watching indicators before widening the rollout.","evals/chapters/18-improvement-flywheel.html","evl",""],["Canary string","A unique marker placed in benchmark files so that honest data pipelines can exclude them and so a model's ability to complete it reveals exposure.","evals/chapters/07-contamination.html","evl","A2 A3"],["Candidate","A piece of code produced by a search loop whose quality is not yet known and which must be tested before it is trusted.","ml-foundations/chapters/22-running-candidates.html","mlf","A1"],["Canonical form","A standard version of a program in which meaningless differences such as variable names and docstrings are removed, so equal programs give equal text.","ml-foundations/chapters/21-programs-as-data.html","mlf","A1"],["Capability claim","A claim that an agent scores higher on a benchmark after some process.","rsi-measurement/chapters/04-reading-claims.html","rsi","A4"],["Capability limit","A restriction on what an agent can do, such as narrow tools, scoped credentials, allow-lists or sandboxes, that holds whatever the model decides.","evals/chapters/14-architectural-defences.html","evl",""],["Capability negotiation","The exchange during initialisation in which client and server declare which optional features they support and agree to use only those.","agents/chapters/07-mcp.html","agt",""],["Capacity factor","The multiple of the even token share that each expert is given room for; tokens beyond it are dropped.","deep-learning/chapters/20-mixture-of-experts.html","dl",""],["Cap set","A set of points in the space of vectors with entries 0, 1 and 2, with no three points on a line.","open-ended/chapters/09-program-evolution.html","oe","A4"],["Cascade","A routing rule that asks the cheap model first and escalates to the expensive model only when a confidence check fails.","evals/chapters/19-cost-latency-quality.html","evl",""],["Catastrophic cancellation","The loss of most significant digits when two nearly equal numbers are subtracted.","ml-foundations/chapters/11-numerics.html","mlf",""],["Catastrophic forgetting","The loss of earlier abilities when a network is fine-tuned on new data, because all skills share the same weights.","llm-training/chapters/10-sft.html","llm",""],["Catastrophic forgetting","The loss of earlier abilities when a model's weights are updated to learn something new.","open-ended/chapters/07-lifelong-agents.html","oe","A4"],["Causality test","A test that changes one input token and checks that only the outputs at that position and later ones change.","deep-learning/chapters/12-building-gpt.html","dl","A1"],["Causal mask","A lower-triangular mask that sets the scores of future positions to minus infinity so a token can only attend to itself and earlier tokens.","deep-learning/chapters/09-attention.html","dl",""],["Cell state","The LSTM's long-term memory vector, updated by scaling the old value with the forget gate and adding gated new content.","deep-learning/chapters/08-sequences-rnns.html","dl",""],["Central limit theorem","The average of many independent draws with finite variance becomes approximately Gaussian, whatever the shape of the original distribution.","ml-foundations/chapters/12-probability.html","mlf",""],["Chain of thought","A written trace of intermediate reasoning steps produced before an answer, which gives later tokens more serial computation to draw on.","agents/chapters/03-reasoning-planning.html","agt",""],["Chain rule","The calculus rule that the derivative of a composition is the product of the derivatives of its parts.","deep-learning/chapters/02-backpropagation.html","dl",""],["Chain rule","The rule that the derivative of a composed function is the product of the local derivatives along the chain.","ml-foundations/chapters/08-derivatives.html","mlf",""],["Chain rule of probability","A joint probability written as a product of each variable given all earlier ones, the identity behind autoregressive language models.","ml-foundations/chapters/12-probability.html","mlf",""],["Chat model","A base model further trained on conversations and human preferences so that it treats input as a request and replies helpfully.","llm-training/chapters/00-start-here.html","llm",""],["Chat template","The fixed text format of role markers and separators that turns a conversation into the token sequence a chat model was trained on.","llm-training/chapters/00-start-here.html","llm",""],["Checkpoint","A saved snapshot of an agent's state at a known point, loaded after a crash so the run continues from there rather than from the start.","agents/chapters/15-durable-execution.html","agt",""],["Checkpoint","A saved state of the run store that can be returned to if later entries prove tainted.","control/chapters/05-incident-playbook.html","ctl","A3"],["Checkpoint","A snapshot of all state needed to resume training exactly: weights, optimiser state, step, data position and random-number states.","llm-training/chapters/05-long-runs.html","llm","A1"],["Child seed","A seed computed from a parent seed and an index, usually by hashing, so each candidate gets its own repeatable random stream.","ml-foundations/chapters/22-running-candidates.html","mlf","A1"],["Chinchilla","DeepMind's 70-billion-parameter model trained on 1.4 trillion tokens, which outperformed the larger Gopher at equal compute and showed that size and data should grow together.","deep-learning/chapters/18-scaling-laws.html","dl","A1"],["Chinchilla","The 70-billion-parameter model and paper (Hoffmann et al., 2022) showing that model size and training tokens should scale together.","research-eng/chapters/03-scaling-mup.html","re","A1"],["Citation audit","A check, before a report is delivered, that each citation resolves, each quote and number is supported by the cited claims, and each factual sentence is cited.","agents/chapters/16-deep-research.html","agt",""],["Citation precision","The share of citations that are relevant, meaning they either entail the sentence alone or are needed because the others do not.","evals/chapters/12-fact-checking.html","evl",""],["Citation precision and recall","The share of citations that support their sentence, and the share of supported sentences that carry a citation.","agents/chapters/16-deep-research.html","agt",""],["Citation recall","The share of answer sentences whose cited passages, taken together, entail the sentence.","evals/chapters/12-fact-checking.html","evl",""],["Claim","A small checkable statement extracted from a source, stored with its verbatim quote, document id and metadata such as date and publisher.","agents/chapters/16-deep-research.html","agt",""],["Claim","The one sentence a paper's authors would defend, ideally with a headline number, a baseline and a stated condition.","ml-foundations/chapters/16-reading-papers.html","mlf","A1"],["Claim extraction","Splitting an answer into separate statements that can each be checked on their own.","evals/chapters/12-fact-checking.html","evl",""],["Claim sentence","The one sentence that opens a write-up and states the budget, the effect with its interval and seeds, the held-out share and an integrity statement.","research-eng/chapters/06-write-up.html","re","A1"],["Client ID metadata document","A JSON description hosted at an HTTPS URL that a client uses as its client id, replacing per-client registration with the authorisation server.","agents/chapters/08-mcp-production.html","agt",""],["CLIP","The 2021 contrastive model trained on 400 million image-text pairs whose encoders are widely reused in vision-language models.","deep-learning/chapters/21-vision-language.html","dl",""],["Clip fraction","The share of tokens whose probability ratio left the clip range in a PPO update, a diagnostic for how far each iteration moves the policy.","llm-training/chapters/08-ppo.html","llm",""],["Closure","An inner function that keeps using variables from the outer function that made it, even after the outer function has returned.","ml-foundations/chapters/20-functions-objects.html","mlf","A1"],["Closure property","The guarantee that any function can accept the output of any other, so every tree built from the sets is a valid program.","open-ended/chapters/20-gp-neuroevolution-cmaes.html","oe",""],["Clustered standard error","A standard error that treats groups of related questions as the independent units, so correlated questions do not overstate precision.","evals/chapters/04-eval-statistics.html","evl","A1 A2 A3"],["CMA-ES","Covariance matrix adaptation evolution strategy: a method for real-valued search that learns the size and shape of its sampling cloud from ranked samples.","open-ended/chapters/20-gp-neuroevolution-cmaes.html","oe",""],["Code object","The interpreter's internal, ready-to-run form of a program, made by compile and run by exec.","ml-foundations/chapters/21-programs-as-data.html","mlf","A1"],["Code template (AI Scientist)","A small working code base for a topic that the first AI Scientist version edits to run its experiments.","open-ended/chapters/14-automated-science.html","oe","A4"],["Coding agent","An agent that finds, reads, edits and runs code in a repository, using test and build results as feedback.","agents/chapters/18-coding-agents.html","agt","A2"],["Co-evolution","Evolution in which a candidate's fitness depends on other populations that are evolving at the same time.","open-ended/chapters/22-coevolution-pbt.html","oe","A4"],["Cohen's kappa","A measure of agreement between two annotators that subtracts the agreement expected by chance, from 1 for perfect agreement to 0 for chance level.","evals/chapters/05-human-labels.html","evl",""],["Cohen's kappa","A measure of rater agreement that subtracts the agreement expected by chance, from 0 for chance to 1 for perfect.","rsi-measurement/chapters/02-automation-levels.html","rsi","A4"],["Collection artefact","A column such as a row number, file name or site code that records how data was gathered and happens to correlate with the label.","ml/chapters/14-leakage.html","ml",""],["Collective operation","A communication call involving a whole group of GPUs, such as all-reduce, reduce-scatter or all-gather.","llm-training/chapters/03-parallelism.html","llm",""],["Collusion","Two copies of an untrusted model coordinating so that one hides the other's attack, which redaction aims to prevent.","control/chapters/04-transcript-monitor.html","ctl","A3"],["Common Crawl","A non-profit web crawl published as periodic snapshots of billions of pages, the main raw source of text for pretraining.","llm-training/chapters/01-pretraining-data.html","llm",""],["Compaction","Summarising a conversation that is nearing its context limit and continuing in a fresh window that starts from the summary.","agents/chapters/10-context-engineering.html","agt","A2"],["Compensated summation","A way of adding floats that tracks the rounding error of each step and feeds it back, so long sums stay accurate.","ml-foundations/chapters/01-python-numerics.html","mlf",""],["Competing objectives","A jailbreak failure mode in which the model's drive to follow instructions overrides its trained refusal.","evals/chapters/13-prompt-injection.html","evl",""],["Competitive co-evolution","Co-evolution in which populations are rivals, such as solvers against test cases built to break them.","open-ended/chapters/22-coevolution-pbt.html","oe","A4"],["Compositional skill","A skill written by calling other skills, so a harder task costs only the new part.","open-ended/chapters/07-lifelong-agents.html","oe","A4"],["Compounding error","The way per-step failure rates multiply over a long task: n steps each succeeding with probability p succeed together with probability p to the power n.","agents/chapters/00-start-here.html","agt",""],["Computation graph","The record of operations and their inputs built during the forward pass, which backward() walks in reverse.","deep-learning/chapters/05-pytorch.html","dl",""],["Computation graph","A directed acyclic graph whose nodes are values and operations and whose edges are dependencies, recorded as a program runs.","ml-foundations/chapters/09-autodiff.html","mlf",""],["Compute-bound","Limited by arithmetic throughput rather than by moving data.","harness-eng/chapters/04-kernels-for-agents.html","he","A3"],["Compute-bound","Describes an operation whose run time is set by arithmetic throughput, because its arithmetic intensity is above the chip's ridge point.","llm-training/chapters/04-kernels.html","llm","A3"],["Compute-bound","Limited by the speed of the arithmetic units, so more memory bandwidth would not make it faster.","ml-foundations/chapters/17-compute-costs.html","mlf","A1"],["Compute-optimal","The model size and token count that give the lowest loss for a fixed training compute budget.","deep-learning/chapters/18-scaling-laws.html","dl","A1"],["Compute-optimal","The split of a compute budget between model size and data that gives the lowest loss.","research-eng/chapters/03-scaling-mup.html","re","A1"],["Computer-use agent","An agent that operates a graphical interface the way a person does, receiving what is on the screen and emitting mouse and keyboard actions.","agents/chapters/17-computer-use.html","agt",""],["Conceptual inquiry","Using an assistant only to ask why and how, while writing the code yourself; the pattern that went with the best quiz scores in Anthropic's 2026 study.","ml-foundations/chapters/19-ai-assistants.html","mlf",""],["Conditional probability","The probability of one event given that another is known to have happened, P(A | B) = P(A, B) / P(B).","ml-foundations/chapters/12-probability.html","mlf",""],["Conditional variance","The spread of a single question's scores around its own pass rate, caused by randomness in the model's answers.","evals/chapters/04-eval-statistics.html","evl","A1 A2 A3"],["Condition number","The ratio of the largest to the smallest stretch of a matrix, measuring how much it amplifies errors when solving a system.","ml-foundations/chapters/06-matrices.html","mlf",""],["Condition number","The ratio of the steepest to the gentlest curvature of a function, large for narrow valleys that are hard to search.","open-ended/chapters/20-gp-neuroevolution-cmaes.html","oe",""],["Confidence interval","A range computed from data by a method that contains the true value in a stated share (such as 95%) of repeated experiments.","ml-foundations/chapters/15-statistics.html","mlf","A1"],["Config hash","A short digest of a configuration in canonical form, so that equal configurations share a key.","research-eng/chapters/04-ablations-tracking.html","re","A1"],["Confounding","Changing two things together so that their effects cannot be separated afterwards.","research-eng/chapters/04-ablations-tracking.html","re","A1"],["Confused deputy","A component that uses its own authority on behalf of a caller who lacks it, such as an MCP server forwarding a user's token to another API.","agents/chapters/08-mcp-production.html","agt",""],["Confused deputy","A trusted program tricked into using its own authority on behalf of an untrusted party.","control/chapters/01-threat-model.html","ctl","A3"],["Confusion matrix","A table counting predictions by predicted class and true class, giving true and false positives and negatives.","ml/chapters/02-framing-metrics.html","ml",""],["Constrained decoding","Compiling a schema into a grammar and masking tokens that would break it at every step, so the output is always well-formed.","agents/chapters/01-model-apis.html","agt",""],["Constrained decoding","Setting the logits of tokens that would break a required format to minus infinity at each step, so the output is valid by construction.","deep-learning/chapters/15-decoding.html","dl",""],["Container","A process with a restricted view of the system built from namespaces, control groups and syscall filters, sharing the host kernel.","agents/chapters/20-sandboxing.html","agt","A2"],["Containment ladder","An ordered set of containment levers, from least to most capability given up, of which on-call picks the lowest that stops the harm.","evals/chapters/20-ai-incidents.html","evl",""],["Containment lever","A switch built in advance, such as a prompt rollback or a kill switch, that reduces what an AI system can do during an incident.","evals/chapters/20-ai-incidents.html","evl",""],["Contamination","The presence of evaluation items, or close variants, in a model's training data, which inflates scores.","llm-training/chapters/23-evaluating-models.html","llm",""],["Content address","A name for data that is its own hash, so two copies are the same only if their fingerprints match.","control/chapters/03-attested-results.html","ctl","A3"],["Content block","A small typed piece of a message, such as text, a tool_use request or a tool_result, that together make up one turn.","agents/chapters/00-start-here.html","agt",""],["Content capture","Recording the text of prompts, replies and tool arguments on spans; an opt-in choice because the text often contains sensitive data.","evals/chapters/17-observability.html","evl",""],["Content hash","A fingerprint of a dataset's exact contents, used to show that two scores came from the same version.","evals/chapters/06-building-benchmarks.html","evl","A2"],["Content hash","A short fingerprint computed from a file's bytes that changes whenever the contents change.","ml-foundations/chapters/04-reproducible-experiments.html","mlf","A1"],["Content policy","The written statement of what a system may and may not say or do, with examples and an action for each category.","evals/chapters/15-guardrails.html","evl",""],["Context collapse","The gradual loss of detail when a context is rewritten again and again.","harness-eng/chapters/01-harness-engineering.html","he","A2"],["Context engineering","Curating and maintaining the set of tokens a model sees at each step of an agent run, beyond writing a single prompt.","agents/chapters/10-context-engineering.html","agt","A2"],["Context engineering","Choosing and maintaining what goes into the model's context window: instructions, examples, notes and retrieved facts.","harness-eng/chapters/01-harness-engineering.html","he","A2"],["contextId","An identifier that groups related A2A messages and tasks into one conversation so follow-ups can refer to earlier work.","agents/chapters/09-agent-to-agent.html","agt",""],["Context isolation","Giving a side task to a sub-agent with its own clean window so that only a short summary of the result enters the main context.","agents/chapters/10-context-engineering.html","agt","A2"],["Context length","The maximum number of tokens a model can attend to at once, set by its positional scheme and training.","deep-learning/chapters/11-positions.html","dl",""],["Context parallelism","Splitting the input sequence across GPUs for the whole model, including attention, to train on very long sequences.","llm-training/chapters/03-parallelism.html","llm",""],["Context propagation","Passing trace identifiers across process boundaries so that spans from different services join one trace.","evals/chapters/17-observability.html","evl",""],["Context rot","The decline in a model's ability to use information in its window as the amount of text grows, especially with distractors.","agents/chapters/10-context-engineering.html","agt","A2"],["Contextual bandit","A bandit in which the agent first sees a context and the reward depends on context and action, but actions do not affect later contexts.","llm-training/chapters/06-bandits-mdps.html","llm",""],["Contextual embeddings","Vectors computed for each occurrence of a word from the words around it, so the same word can get different vectors.","deep-learning/chapters/06-embeddings.html","dl",""],["Context window","The text a model reads on a single call, including system prompt, tool definitions, history, tool results and retrieved material; it is the model's only working memory.","agents/chapters/10-context-engineering.html","agt","A2"],["Context window","The fixed number of words on either side of a word that count as its context.","deep-learning/chapters/06-embeddings.html","dl",""],["Contiguous array","An array whose elements sit next to each other in memory in the order the layout implies, so reads stream efficiently.","ml-foundations/chapters/02-numpy-arrays.html","mlf",""],["Contrastive language-image pre-training","Training an image encoder and a text encoder together so that matching image-caption pairs have similar vectors and other pairs do not.","deep-learning/chapters/21-vision-language.html","dl",""],["Contrastive loss","A training loss that pulls matching pairs together and pushes non-matching pairs apart in vector space.","agents/chapters/23-dense-retrieval.html","agt","A2"],["Control groups (cgroups)","A Linux kernel feature that caps the CPU, memory, processes and disk input and output of a set of processes.","control/chapters/02-egress-sandbox.html","ctl","A3"],["Controller and processor","The GDPR roles of the party that decides why and how personal data is processed and the party that processes it on the controller's behalf.","evals/chapters/22-privacy-data.html","evl",""],["Convolution","Sliding a small grid of weights over an input and summing the products at each position to produce a map of how strongly a pattern is present.","deep-learning/chapters/07-convolutions.html","dl",""],["Co-occurrence matrix","A table counting how often each pair of words appears within a context window of each other.","deep-learning/chapters/06-embeddings.html","dl",""],["Cooperative co-evolution","Co-evolution in which each population supplies one part of a solution and members are scored by how well they work together.","open-ended/chapters/22-coevolution-pbt.html","oe","A4"],["Copy (array)","An array with its own newly allocated memory, independent of the array it was made from.","ml-foundations/chapters/02-numpy-arrays.html","mlf",""],["Correlated errors","Mistakes that several judges or runs make together on the same hard items, which cap the accuracy gain from voting however many votes you add.","agents/chapters/13-workflow-patterns.html","agt",""],["Corroboration","Support for a claim from two or more independent sources that report the same thing.","agents/chapters/16-deep-research.html","agt",""],["Cosine decay","A learning-rate schedule that falls from its peak to a small fraction of it along half a cosine wave.","deep-learning/chapters/12-building-gpt.html","dl","A1"],["Cosine similarity","The dot product of two vectors after scaling each to length 1, measuring the angle between them.","agents/chapters/23-dense-retrieval.html","agt","A2"],["Cosine similarity","The cosine of the angle between two vectors, equal to their dot product once both are scaled to length one.","deep-learning/chapters/06-embeddings.html","dl",""],["Cosine similarity","The dot product of two vectors divided by the product of their lengths, which compares direction only and lies between -1 and 1.","ml-foundations/chapters/05-vectors-similarity.html","mlf",""],["Cost of a failure","The money lost when one answer is wrong, used with serving cost to decide what quality is worth paying for.","evals/chapters/19-cost-latency-quality.html","evl",""],["Cost per accepted improvement","Total dollars spent divided by the number of rewrites accepted so far.","rsi-measurement/chapters/03-loop-economics.html","rsi","A4"],["Cost per million tokens","The GPU price per hour divided by the tokens served per hour, times one million; meaningful only with stated batch, context, precision, latency target and utilisation.","llm-training/chapters/22-token-economics.html","llm","A1"],["Cost per success","Total spend on all trials divided by the number of successful trials, which exceeds cost per attempt because failures also cost money.","evals/chapters/08-agent-evals.html","evl","A3"],["Cost per successful task","The cost of an attempt divided by the share of attempts that succeed, so failed attempts are paid for too.","evals/chapters/19-cost-latency-quality.html","evl",""],["Cost-sensitive threshold","The rule to flag a case when its probability exceeds the false-alarm cost divided by the sum of the false-alarm and miss costs.","ml/chapters/02-framing-metrics.html","ml",""],["Covariance matrix","The symmetric matrix of covariances between features, X^T X/(n-1) for centred data.","ml-foundations/chapters/07-decompositions.html","mlf",""],["Covariance matrix","A square table of the variances of each parameter and how pairs of parameters vary together, which sets the shape of a Gaussian cloud.","open-ended/chapters/20-gp-neuroevolution-cmaes.html","oe",""],["Coverage","The share of all questions a system chooses to answer.","evals/chapters/11-grounding-abstention.html","evl",""],["Coverage","The fraction of archive cells that hold a solution, showing how much of behaviour space has been explored.","open-ended/chapters/04-quality-diversity.html","oe","A4"],["Coverage matrix","A grid of the dimensions along which questions differ, with the number of items planned and found in each cell.","evals/chapters/06-building-benchmarks.html","evl","A2"],["Covert channel","A way to move information using a mechanism not designed for communication, such as the choice of which allowed URL to fetch.","control/chapters/02-egress-sandbox.html","ctl","A3"],["CPU-time limit","A resource limit on the seconds of processor work a process may use, which a sleeping process never reaches.","ml-foundations/chapters/22-running-candidates.html","mlf","A1"],["Credit assignment","The problem of deciding which actions in a long sequence deserve credit or blame for a reward that arrives later.","llm-training/chapters/07-policy-gradients.html","llm",""],["Credit assignment","Deciding which part of a team or sequence deserves the credit or blame for the overall result.","open-ended/chapters/22-coevolution-pbt.html","oe","A4"],["Criteria drift","The tendency for people's grading criteria to change as they read outputs, because grading helps define the criteria.","evals/chapters/01-error-analysis.html","evl",""],["Critic","A model call that reviews an attempt's outcome and decides whether the task succeeded.","open-ended/chapters/07-lifelong-agents.html","oe","A4"],["Critical path","The chain of steps whose durations determine how long a run takes, so that parallel work off the path adds tokens but not waiting time.","agents/chapters/13-workflow-patterns.html","agt",""],["Critical slice","A subset of test cases where a mistake is expensive, such as money, safety or privacy, tracked separately so averages cannot hide a failure.","evals/chapters/18-improvement-flywheel.html","evl",""],["Cross-attention","Attention whose queries come from one sequence and whose keys and values come from another.","deep-learning/chapters/09-attention.html","dl",""],["Cross-attention fusion","Inserting layers in which the text positions attend to image features, so the image stays outside the language model's own sequence.","deep-learning/chapters/21-vision-language.html","dl",""],["Cross-entropy","The average surprise of a model q over data drawn from p, H(p, q); a training loss is a sample estimate of it.","ml-foundations/chapters/14-information-theory.html","mlf",""],["Cross-entropy loss","The average negative log probability that the model gave to the true next token, minimised during language-model training.","deep-learning/chapters/14-language-modelling.html","dl","A1"],["Cross-entropy loss","The negative log of the probability a model assigned to the true class; with a softmax its gradient with respect to the logits is the predicted probabilities minus the one-hot target.","ml-foundations/chapters/13-likelihood-losses.html","mlf",""],["Crossover","Building a child genome from parts of two parent genomes.","open-ended/chapters/02-evolutionary-algorithms.html","oe","A1 A4"],["Curriculum","An ordering of tasks from easy to hard that lets a learner acquire skills it could not learn on the hard task alone.","open-ended/chapters/05-open-ended-algorithms.html","oe","A4"],["Curse of knowledge","The difficulty of remembering what it was like not to know something, which makes writers skip steps and use private shorthand.","ml-foundations/chapters/18-technical-writing.html","mlf","A1 A4"],["CVT-MAP-Elites","A MAP-Elites variant that divides behaviour space into a fixed number of centroidal Voronoi regions so high-dimensional descriptors stay tractable.","open-ended/chapters/04-quality-diversity.html","oe","A4"],["DAPO","An open large-scale RL recipe for reasoning models that adds dynamic sampling, a higher upper clip bound, a token-level loss and shaping for over-long answers.","llm-training/chapters/14-rlvr-grpo.html","llm","A2 A4"],["DARE (Drop And REscale)","A merge pre-processing step that randomly drops a fraction p of a task vector's entries and rescales the rest by 1/(1-p), keeping the expected update unchanged.","llm-training/chapters/16-model-merging.html","llm","A4"],["Darwin Gödel Machine","A coding agent that keeps an archive of its own versions, edits its own code with a language model and validates each change empirically.","harness-eng/chapters/01-harness-engineering.html","he","A2"],["Darwin Gödel Machine (DGM)","A coding agent that edits its own code, keeps every version in an archive and accepts changes based on benchmark results instead of formal proofs.","open-ended/chapters/13-self-improving-agents.html","oe","A4"],["Data augmentation","Creating extra training examples by applying transformations that are known not to change the label.","deep-learning/chapters/04-deep-regularisation.html","dl",""],["Data card","Structured documentation of a dataset's purpose, sources, labelling, composition, limits and intended use.","evals/chapters/06-building-benchmarks.html","evl","A2"],["Data cascade","A data problem that compounds silently through a pipeline and appears late as a failure downstream.","ml-foundations/chapters/03-data-wrangling.html","mlf",""],["Dataclass","A class declared with @dataclass, which writes the constructor, readable text form and equality check from its list of typed fields.","ml-foundations/chapters/20-functions-objects.html","mlf","A1"],["Data contamination","Information from a benchmark's test items reaching a model through its training data, so the score reflects recall instead of the ability being measured.","evals/chapters/07-contamination.html","evl","A2 A3"],["Data exfiltration","Sending private data out of a system to a place an attacker can read, for example through a URL, an email or a rendered image.","agents/chapters/19-agent-security.html","agt","A3"],["DataFrame","A table held in memory with labelled columns, each stored as an array; pandas' main data structure.","ml-foundations/chapters/03-data-wrangling.html","mlf",""],["Data minimisation","The principle of collecting and passing on only the personal data the purpose needs.","evals/chapters/22-privacy-data.html","evl",""],["Data mix","The fraction of training tokens drawn from each source, such as web, code, maths and multilingual text.","llm-training/chapters/01-pretraining-data.html","llm",""],["Data parallelism","Training with a full copy of the model on every GPU, each processing a different slice of the batch, with gradients averaged across GPUs.","llm-training/chapters/03-parallelism.html","llm",""],["Data protection impact assessment","A written analysis of the purpose, necessity and risks of high-risk processing, required before launch under GDPR Article 35.","evals/chapters/22-privacy-data.html","evl",""],["Data residency","A requirement that data be stored, processed or accessed only in certain places, which covers storage, processing and access separately.","evals/chapters/22-privacy-data.html","evl",""],["Data-science loop","The cycle of framing, exploring, baselining, modelling, validating, deploying and monitoring, in which modelling is one step of seven.","ml/chapters/00-start-here.html","ml",""],["Dead group","A group of sampled answers that all received the same reward, so every advantage is zero and the prompt contributes no gradient that step.","llm-training/chapters/14-rlvr-grpo.html","llm","A2 A4"],["Deadline polling","Waiting for a child process by repeatedly checking whether it has exited until a time limit passes.","research-eng/chapters/05-rust-runner.html","re","A1"],["Dead-man switch","A fail-safe in which the run continues only while a regular heartbeat arrives, so the loss of the watcher halts it.","control/chapters/05-incident-playbook.html","ctl","A3"],["Dead unit","A ReLU neuron whose pre-activation is negative for every example, so it receives no gradient and never recovers.","deep-learning/chapters/01-neurons-layers.html","dl",""],["Deceptive problem","A problem where following improvements in the objective leads away from the best solution.","open-ended/chapters/03-novelty-search.html","oe",""],["Decision record","A short note of what was decided, when, by whom and which alternatives were rejected, kept with the project.","ml-foundations/chapters/18-technical-writing.html","mlf","A1 A4"],["Decision threshold","The score above which a case is flagged as positive; a separate choice from the model that produces the score.","ml/chapters/02-framing-metrics.html","ml",""],["Decode","The generation phase, one token per step, in which each step reads the weights and the whole KV cache and is limited by memory bandwidth.","deep-learning/chapters/19-efficient-attention.html","dl","A3"],["Decoder-only model","A Transformer built only from causally masked self-attention blocks, which predicts each token from the ones before it.","deep-learning/chapters/10-transformer-block.html","dl",""],["Decontamination","Removing or flagging training documents that overlap with benchmark items before training.","evals/chapters/07-contamination.html","evl","A2 A3"],["Decontamination","Removing training examples that overlap evaluation sets so that benchmark scores do not simply measure memorisation.","llm-training/chapters/10-sft.html","llm",""],["Decontextualisation","Rewriting a claim so that pronouns and vague references are replaced and it makes sense with the surrounding text removed.","evals/chapters/12-fact-checking.html","evl",""],["Deduplication","Removing repeated documents, lines or passages from a training corpus so the model does not waste compute on, or memorise, repeated text.","llm-training/chapters/01-pretraining-data.html","llm",""],["Deep learning","Machine learning in which a model of many stacked layers learns its own features from data, trained by gradient descent.","deep-learning/chapters/00-start-here.html","dl",""],["Deep-research agent","An agent that answers an open-ended question with a sourced written report by iterating between planning, searching and reading for minutes rather than seconds.","agents/chapters/16-deep-research.html","agt",""],["Defence in depth","Layering independent controls so that a failure of one, such as a permission rule with a hole, does not defeat the system.","agents/chapters/20-sandboxing.html","agt","A2"],["Defer to trusted","A control rule that replaces suspicious output with the trusted model's own answer when it is not suspicious enough to audit.","control/chapters/04-transcript-monitor.html","ctl","A3"],["Define-by-run","Building the computation graph as ordinary code executes, so that control flow in Python changes the graph with no special syntax.","deep-learning/chapters/05-pytorch.html","dl",""],["Delimiter","A marker such as an XML-style tag or a code fence that separates instructions from the data they operate on.","agents/chapters/04-prompting.html","agt","A2"],["Delta rule","A state update that subtracts what the state already predicts for a key before writing the new value, letting it overwrite old information.","deep-learning/chapters/22-beyond-attention.html","dl",""],["Dense retrieval","Retrieval that embeds queries and passages as vectors and returns the passages whose vectors are closest to the query's.","agents/chapters/23-dense-retrieval.html","agt","A2"],["Deny by default","A policy that refuses everything unless a rule allows it, so a forgotten case fails closed instead of open.","control/chapters/02-egress-sandbox.html","ctl","A3"],["Derivative","The slope that chord slopes settle to as the step shrinks to zero: how fast a function's output changes per unit change in its input.","ml-foundations/chapters/08-derivatives.html","mlf",""],["Design doc","A document that proposes a solution, its goals, non-goals, alternatives and trade-offs, so it can be criticised before it is built.","ml-foundations/chapters/18-technical-writing.html","mlf","A1 A4"],["Determinant","The factor by which a square matrix scales areas or volumes; negative if it flips orientation and zero if it flattens space.","ml-foundations/chapters/06-matrices.html","mlf",""],["Deterministic assertion","A pure check on a system's output, with no randomness or model call, that returns pass or fail with a reason.","evals/chapters/02-eval-harnesses.html","evl","A3"],["Deterministic replay","Recovering a workflow by re-running its code against a recorded history, which only works if the code makes the same decisions for the same history.","agents/chapters/15-durable-execution.html","agt",""],["Deterministic replay","Rerunning a stored run from its row and checking that the result matches the original.","research-eng/chapters/04-ablations-tracking.html","re","A1"],["Dev and test split","A division of benchmark items into a visible set for tuning and a rarely used held-out set for reporting.","evals/chapters/06-building-benchmarks.html","evl","A2"],["Development set","The examples a search uses to choose among candidates, kept separate from the test set that is used once to report the result.","open-ended/chapters/11-evolving-prompts.html","oe","A2"],["Device pixel ratio","The number of physical pixels per coordinate unit on a high-density display, which a harness must account for when converting model coordinates into clicks.","agents/chapters/17-computer-use.html","agt",""],["Diff guard","Code that checks a proposed change against a policy on paths, patterns and size before it is allowed to run.","open-ended/chapters/17-self-modification-safety.html","oe","A3"],["Digital Omnibus on AI","Regulation (EU) 2026/1744, in force since 27 July 2026, which postponed the high-risk obligations of the AI Act to December 2027 and August 2028.","evals/chapters/21-governance.html","evl",""],["Digital signature","A tag made with a private key that anyone can verify with the matching public key but cannot forge.","control/chapters/03-attested-results.html","ctl","A3"],["Diminishing returns","A pattern in which each further improvement costs more than the last because good edits become scarcer or smaller.","rsi-measurement/chapters/03-loop-economics.html","rsi","A4"],["Directional derivative","The slope of a function along a chosen unit direction, equal to the dot product of the gradient with that direction.","ml-foundations/chapters/08-derivatives.html","mlf",""],["Direct prompt injection","An injection typed by the user of the application in their own message.","evals/chapters/13-prompt-injection.html","evl",""],["Disclosure","Telling the owners of an affected system, then the public, what was found, with a timeline and the controls that failed.","control/chapters/05-incident-playbook.html","ctl","A3"],["Discount factor","A number gamma between 0 and 1 that weights a reward k steps ahead by gamma to the power k, favouring sooner rewards.","llm-training/chapters/06-bandits-mdps.html","llm",""],["Discovery claim","A claim that a system found a better artifact, which anyone can check by running it without trusting the system.","rsi-measurement/chapters/04-reading-claims.html","rsi","A4"],["Discrimination (of an item)","How well an item separates stronger systems from weaker ones, often measured as its correlation with the total score on the other items.","evals/chapters/06-building-benchmarks.html","evl","A2"],["Distillation","Training a small student model to imitate a larger teacher, using the teacher's probabilities or its written answers as the training signal.","llm-training/chapters/15-distillation.html","llm",""],["Distributional hypothesis","The idea that words occurring in similar contexts have similar meanings.","deep-learning/chapters/06-embeddings.html","dl",""],["DOM","The Document Object Model: the browser's tree of HTML elements for the current page.","agents/chapters/17-computer-use.html","agt",""],["Dominated configuration","A configuration that another one matches or beats on every axis and strictly beats on at least one, so it should never be chosen.","evals/chapters/19-cost-latency-quality.html","evl",""],["Dot product","The sum of the products of matching entries of two equal-length vectors, such as 1x4 + 2x5 + 3x6 = 32.","ml-foundations/chapters/01-python-numerics.html","mlf",""],["Double descent","The pattern in which test error falls, spikes near the interpolation threshold, and falls again as the model keeps growing.","deep-learning/chapters/04-deep-regularisation.html","dl",""],["Double precision","The 64-bit floating-point format with a 53-bit significand, which gives roughly 15 to 16 decimal digits.","ml-foundations/chapters/01-python-numerics.html","mlf",""],["Double quantisation","Quantising the per-block scale factors themselves, which reduces the storage overhead of 4-bit weights from about 0.5 to about 0.13 bit per weight.","llm-training/chapters/11-lora.html","llm",""],["DPO (Direct Preference Optimisation)","A method that trains the policy directly on preference pairs with a logistic loss on log-probability ratios against a reference, with no separate reward model or sampling loop.","llm-training/chapters/12-preference-optimisation.html","llm",""],["Draft, debug, improve","AIDE's three operators: write a new solution, repair a crashed one, or make one atomic change to a working one.","harness-eng/chapters/02-aide-tree-search.html","he","A2"],["Dr. GRPO","A modification of GRPO that removes the per-answer length normalisation and the standard-deviation scaling to avoid biases towards longer wrong answers.","llm-training/chapters/14-rlvr-grpo.html","llm","A2 A4"],["Dropout","Zeroing a random subset of hidden units at each training step so that no unit can depend on particular partners.","deep-learning/chapters/04-deep-regularisation.html","dl",""],["Dry run","A tool mode that reports what the action would do without changing anything.","agents/chapters/05-tool-design.html","agt","A2"],["DSPy","A framework in which an LLM pipeline is written as modules with signatures and an optimiser generates their prompts and examples against a metric.","open-ended/chapters/11-evolving-prompts.html","oe","A2"],["dtype","The data type of an array's elements, such as float32 or int64, which fixes bytes per element and the arithmetic used.","ml-foundations/chapters/02-numpy-arrays.html","mlf",""],["Dual-era client","A client that tries a modern stateless MCP request first and falls back to the initialize handshake when the server turns out to be legacy.","agents/chapters/08-mcp-production.html","agt",""],["Dual LLM pattern","A design in which a privileged model plans and uses tools without seeing untrusted text, and a quarantined model without tools reads it, passing results as variables.","evals/chapters/14-architectural-defences.html","evl",""],["Dual numbers","Pairs of a value and its derivative that obey the product and chain rules, used to implement forward mode.","ml-foundations/chapters/09-autodiff.html","mlf",""],["Dunder method","A method with a double-underscore name, such as __add__ or __lt__, that Python calls when you use an operator or built-in on your object.","ml-foundations/chapters/20-functions-objects.html","mlf","A1"],["Durable execution","Running a program so that its progress is stored outside the process, letting a new process continue after a crash without losing work or repeating completed steps.","agents/chapters/15-durable-execution.html","agt",""],["Dynamic loss scaling","Adjusting the loss scale during training: halve it and skip the step when a gradient overflows, double it after a run of clean steps.","deep-learning/chapters/17-training-stability.html","dl","A1"],["Early stopping","Ending training when held-out loss stops improving and restoring the weights from the best evaluation.","deep-learning/chapters/04-deep-regularisation.html","dl",""],["EchoLeak","A zero-click prompt injection in Microsoft 365 Copilot (CVE-2025-32711) that leaked data via a crafted email by chaining several bypasses.","agents/chapters/19-agent-security.html","agt","A3"],["Eckart-Young theorem","The result that the truncated SVD is the closest rank-k matrix to A, with error set by the discarded singular values.","ml-foundations/chapters/07-decompositions.html","mlf",""],["Effectively-once","The observable result of at-least-once attempts combined with idempotent handling, so that the world changes as if the action ran exactly once.","agents/chapters/15-durable-execution.html","agt",""],["Effective training time","The share of elapsed wall-clock time spent on useful training, after subtracting restarts, lost work and checkpoint pauses.","llm-training/chapters/05-long-runs.html","llm","A1"],["Egress allow-list","A list of the only hosts or addresses an agent or its client may send requests to, blocking data leaving through other destinations.","evals/chapters/14-architectural-defences.html","evl",""],["Egress gate","The proxy that is the sandbox's only route out, parsing each URL and checking it against an allowlist and a ledger.","control/chapters/02-egress-sandbox.html","ctl","A3"],["Egress ledger","A count of requests and bytes per day kept at the gate, outside the sandbox, with hard caps.","control/chapters/02-egress-sandbox.html","ctl","A3"],["Egress proxy","A server outside the sandbox through which all outbound requests pass, deciding by allow-list which hosts may be contacted.","agents/chapters/20-sandboxing.html","agt","A2"],["Eigenvalue","The factor lambda by which a matrix stretches one of its eigenvectors.","ml-foundations/chapters/07-decompositions.html","mlf",""],["Eigenvector","A non-zero vector that a square matrix only stretches, so that Av = lambda v.","ml-foundations/chapters/07-decompositions.html","mlf",""],["Einstein summation","NumPy's Einstein-summation function, which writes a tensor product by naming each axis with a letter and listing which letters survive.","ml-foundations/chapters/02-numpy-arrays.html","mlf",""],["Elasticity","The percentage change in an output for a one percent change in an input.","rsi-measurement/chapters/03-loop-economics.html","rsi","A4"],["Elite","The best solution found so far for one cell of an archive.","open-ended/chapters/04-quality-diversity.html","oe","A4"],["Elitism","Copying the best few individuals unchanged into the next generation so the best score never falls.","open-ended/chapters/02-evolutionary-algorithms.html","oe","A1 A4"],["Embedding","A list of real numbers produced by a neural network to represent a piece of text so that similar texts get nearby vectors.","agents/chapters/23-dense-retrieval.html","agt","A2"],["Embedding","A dense, learned vector of a few hundred numbers that represents a word, token or other discrete item so that similar items lie close together.","deep-learning/chapters/06-embeddings.html","dl",""],["Embedding","A vector produced by a trained model for an item such as a word or sentence so that similar items get similar vectors.","ml-foundations/chapters/05-vectors-similarity.html","mlf",""],["Embedding table","A matrix with one row per vocabulary item whose rows are looked up by index and trained like any other weights.","deep-learning/chapters/06-embeddings.html","dl",""],["Emergent abilities","Abilities that seem to appear abruptly at some model scale, whose sharpness is partly disputed as an effect of all-or-nothing metrics.","deep-learning/chapters/18-scaling-laws.html","dl","A1"],["Encoder-decoder","A design in which one network reads the source sequence into a summary and another generates the target sequence from it.","deep-learning/chapters/08-sequences-rnns.html","dl",""],["End-state grading","Scoring an agent by comparing the final state of the world with a goal state or invariants, instead of judging its words or its route.","evals/chapters/08-agent-evals.html","evl","A3"],["Entailment","The relation that if the evidence is true then the claim must also be true.","evals/chapters/12-fact-checking.html","evl",""],["Entropy","The expected surprise of a distribution, which is also the least average number of bits per symbol a lossless code can use.","ml-foundations/chapters/14-information-theory.html","mlf",""],["Enum and match (Rust)","A type with a fixed list of variants, and an expression that must handle every variant.","research-eng/chapters/05-rust-runner.html","re","A1"],["Environment-agent pair","A learning problem together with the agent being trained on it, the unit of population in POET.","open-ended/chapters/05-open-ended-algorithms.html","oe","A4"],["Episodic memory","Records of what happened, such as past conversations and actions with their times, retrieved by search rather than loaded in full.","agents/chapters/11-memory.html","agt","A2"],["Epistasis","Interaction between genes, so that the effect of one depends on the values of others; it makes landscapes rugged.","open-ended/chapters/19-evolution-for-builders.html","oe","A1"],["Epoch","One full pass over the training set.","deep-learning/chapters/05-pytorch.html","dl",""],["Epsilon-greedy","A bandit strategy that picks a random action with probability epsilon and the best-looking action otherwise.","llm-training/chapters/06-bandits-mdps.html","llm",""],["Epsilon-greedy","A bandit strategy that picks a random option with probability epsilon and the best-looking option otherwise.","open-ended/chapters/01-tree-search.html","oe","A2"],["Error analysis","Reading real traces, naming what went wrong and counting failure kinds so that fixes are chosen by evidence.","evals/chapters/01-error-analysis.html","evl",""],["Error-analysis memo","A write-up of a labelled sample of failures: categories, counts with intervals, examples and a ranked list of fixes.","ml-foundations/chapters/18-technical-writing.html","mlf","A1 A4"],["EU AI Act","Regulation (EU) 2024/1689, which sets obligations for AI systems and general-purpose models according to role and risk tier.","evals/chapters/21-governance.html","evl",""],["Eval harness","A program that runs test cases against a system, applies checks, stores results and compares runs.","evals/chapters/02-eval-harnesses.html","evl","A3"],["Evaluation cascade","Staged testing in which cheap checks reject poor candidates before expensive ones are run.","open-ended/chapters/09-program-evolution.html","oe","A4"],["Evaluation function (agent design)","The scoring rule applied to each candidate agent, such as accuracy on a search set, which the search can only be as good as.","open-ended/chapters/12-meta-agent-search.html","oe","A2 A4"],["Evaluation harness","A program that builds prompts, runs a model on a set of tasks, scores the outputs and records the settings, so different models are compared by identical code.","llm-training/chapters/23-evaluating-models.html","llm",""],["Evaluation loop","The cycle of looking at traces, naming failures, measuring them, changing the system and guarding the fix.","evals/chapters/00-start-here.html","evl",""],["Evaluator","The code that runs a candidate against checks and produces the score that decides what is kept.","control/chapters/01-threat-model.html","ctl","A3"],["Evaluator","The code that produces a score, which must sit outside the proposer's reach if the score is to mean anything.","harness-eng/chapters/00-start-here.html","he","A2"],["Evaluator","The part of a search loop that scores a candidate; flaws in it are what a search loop will exploit.","open-ended/chapters/00-start-here.html","oe",""],["Evaluator hacking","A search or agent finding a way to score highly on an evaluator without doing the intended work.","open-ended/chapters/15-evaluator-hacking.html","oe","A3"],["Evaluator-hardening kit","Artifact 3: a library of typed, attested tool results, hidden splits and end-to-end timing, with hacking rate as a first-class metric.","control/chapters/00-start-here.html","ctl","A3"],["Evaluator-optimiser","A loop in which one call produces a draft, another checks it against criteria and returns feedback, and the producer revises until the check passes or a limit is reached.","agents/chapters/13-workflow-patterns.html","agt",""],["Event log (journal)","An append-only record of every model reply, tool result and human decision in a run, from which the run's current state can be rebuilt.","agents/chapters/15-durable-execution.html","agt",""],["Event stream","An ordered log of every action an agent takes and every observation it receives, which makes runs replayable.","agents/chapters/18-coding-agents.html","agt","A2"],["Evidence pack","A register linking each risk to a control, a metric with a threshold, an owner and the date of the latest result, generated from evals and traces.","evals/chapters/21-governance.html","evl",""],["Evidence recall","The share of questions for which the context you built contained every fact needed to answer them.","agents/chapters/12-long-context.html","agt",""],["Evolutionary algorithm","A search method that keeps a population of candidates and repeatedly selects the fitter ones and varies them to make the next generation.","open-ended/chapters/02-evolutionary-algorithms.html","oe","A1 A4"],["Evolutionary merging","Searching for a merge recipe with an evolutionary algorithm that merges and scores candidate recipes, in parameter space and in data-flow space, without gradients.","llm-training/chapters/16-model-merging.html","llm","A4"],["Evolution path","A running sum of recent mean movements with older ones fading, used to tell steady progress from zig-zagging.","open-ended/chapters/20-gp-neuroevolution-cmaes.html","oe",""],["Evolution strategies","A black-box optimiser that estimates a direction of improvement by scoring random perturbations of the parameters and moving toward the better ones.","open-ended/chapters/05-open-ended-algorithms.html","oe","A4"],["Evolution strategy","An evolutionary method for real-valued vectors that relies on Gaussian mutation with an adapted step size.","open-ended/chapters/02-evolutionary-algorithms.html","oe","A1 A4"],["Evolvability","The capacity of a population or encoding to produce heritable variation that selection can use.","open-ended/chapters/19-evolution-for-builders.html","oe","A1"],["EvoPrompt","A prompt optimiser in which a language model carries out the steps of a genetic algorithm or differential evolution on a population of prompts.","open-ended/chapters/11-evolving-prompts.html","oe","A2"],["Exact agreement","The share of items on which two raters give the same label.","rsi-measurement/chapters/02-automation-levels.html","rsi","A4"],["Exception","An object that Python raises when something goes wrong, which travels up the callers until a matching except clause handles it.","ml-foundations/chapters/20-functions-objects.html","mlf","A1"],["Exchangeability test","A black-box contamination test that checks whether a model assigns higher probability to a benchmark's published item order than to shuffled orders.","evals/chapters/07-contamination.html","evl","A2 A3"],["Expectation","The probability-weighted average of a random variable's values, which is linear even for dependent variables.","ml-foundations/chapters/12-probability.html","mlf",""],["Expected calibration error","The average gap between stated confidence and actual accuracy across confidence bins, weighted by how many answers fall in each bin.","evals/chapters/11-grounding-abstention.html","evl",""],["Experiment log","A record of each run's code version, data identifier, configuration, environment, seed and results.","ml-foundations/chapters/04-reproducible-experiments.html","mlf","A1"],["Experiment report","A short document stating a question, the setup, the results with uncertainty, limitations and a decision.","ml-foundations/chapters/18-technical-writing.html","mlf","A1 A4"],["Expert","One of the parallel MLPs in a mixture-of-experts layer; it is a part of one network trained together, not a topic specialist.","deep-learning/chapters/20-mixture-of-experts.html","dl",""],["Expert parallelism","Placing different experts on different GPUs, so tokens are exchanged between GPUs by two all-to-all steps per layer.","deep-learning/chapters/20-mixture-of-experts.html","dl",""],["Expert vector","A stored vector of singular-value scales trained for one domain, which can be mixed with others to configure the model for a task.","llm-training/chapters/17-adapters-on-demand.html","llm",""],["Exploding gradient","The growth of gradients without bound as they are multiplied through many steps, causing huge updates or NaN values.","deep-learning/chapters/08-sequences-rnns.html","dl",""],["Exploding gradients","Gradients that grow exponentially through the layers of a deep network and make updates unstable.","deep-learning/chapters/03-training-dynamics.html","dl","A1"],["Exploit (in PBT)","Replacing a poorly performing worker's weights and hyperparameters with a copy of a better worker's.","open-ended/chapters/22-coevolution-pbt.html","oe","A4"],["Exploration-exploitation trade-off","The tension between using the action that currently looks best and trying others to learn whether they are better.","llm-training/chapters/06-bandits-mdps.html","llm",""],["Exploration versus exploitation","The trade-off between trying uncertain options to learn more and repeating the option that currently looks best.","open-ended/chapters/01-tree-search.html","oe","A2"],["Explore (in PBT)","Perturbing copied hyperparameters, for example by multiplying the learning rate by 0.8 or 1.25, before training continues.","open-ended/chapters/22-coevolution-pbt.html","oe","A4"],["Exponent","The bits of a floating-point number that set its scale and so its range.","deep-learning/chapters/17-training-stability.html","dl","A1"],["Expression swell","The growth in size of a symbolically differentiated formula, which can be far larger than the original expression.","ml-foundations/chapters/09-autodiff.html","mlf",""],["Extrapolation","Predicting a value outside the range of the data a model was fitted on, such as the loss of a much larger model.","research-eng/chapters/03-scaling-mup.html","re","A1"],["F1 score","The harmonic mean of precision and recall, which is low whenever either is low.","ml/chapters/02-framing-metrics.html","ml",""],["Fabrication","Inventing an entity, case, paper, quotation or function that does not exist.","evals/chapters/10-hallucination.html","evl",""],["Factor","One thing that can be varied in an experiment, such as the learning rate.","research-eng/chapters/04-ablations-tracking.html","re","A1"],["FActScore","The percentage of a generation's atomic facts that a reliable knowledge source supports.","evals/chapters/10-hallucination.html","evl",""],["Factuality hallucination","An output that conflicts with facts about the world, either by inventing something or by misstating a real fact.","evals/chapters/10-hallucination.html","evl",""],["Fail closed","Stopping the request when a safety check errors or times out, instead of letting it pass.","evals/chapters/15-guardrails.html","evl",""],["FAIL_TO_PASS and PASS_TO_PASS","The two test sets used to grade a patch: tests that must start passing, and tests that must keep passing.","agents/chapters/18-coding-agents.html","agt","A2"],["Failure mode","A named, recurring way a system goes wrong, counted across traces to decide what to fix first.","evals/chapters/18-improvement-flywheel.html","evl",""],["Failure taxonomy","A short list of named failure kinds, with counts, built from reading real outputs.","evals/chapters/00-start-here.html","evl",""],["Fair baseline","A comparison method given the same budget and the same number of attempts as the method being claimed better.","research-eng/chapters/00-start-here.html","re","A1"],["Fair baseline","A hand-tuned version of the same agent given the same budget and the same number of attempts as the loop.","rsi-measurement/chapters/01-level-one.html","rsi","A4"],["Faithfulness","Whether an answer says only what the sources it was given say, regardless of whether the sources are correct.","evals/chapters/12-fact-checking.html","evl",""],["Faithfulness hallucination","An output that conflicts with what the user supplied, such as a summary that contradicts or adds to its source document.","evals/chapters/10-hallucination.html","evl",""],["False negative","A passage treated as non-relevant in training because it was never labelled, although it actually answers the query.","agents/chapters/23-dense-retrieval.html","agt","A2"],["False negative rate","The share of papers that should be accepted which a reviewer rejects.","open-ended/chapters/14-automated-science.html","oe","A4"],["False positive rate","The share of papers that should be rejected which a reviewer accepts.","open-ended/chapters/14-automated-science.html","oe","A4"],["False support","A verifier error in which a wrong claim is marked as supported, the most damaging error for a checking stage.","evals/chapters/12-fact-checking.html","evl",""],["Fan-in","The number of inputs feeding one neuron, which is the number of rows of the weight matrix.","deep-learning/chapters/03-training-dynamics.html","dl","A1"],["Fan-out","The multiplication of rows when a join key is not unique in one table, which inflates counts and sums.","ml-foundations/chapters/03-data-wrangling.html","mlf",""],["fast_p","The fraction of tasks whose generated kernel is correct and more than p times faster than the reference.","harness-eng/chapters/04-kernels-for-agents.html","he","A3"],["Feature","A number that describes one aspect of an example, either designed by a person or learned by a model.","deep-learning/chapters/00-start-here.html","dl",""],["Feature","One input fact about an example, such as a word count or a customer's tenure; the features form the columns of X.","ml/chapters/00-start-here.html","ml",""],["Feature dimensions","The behaviour axes, such as program complexity, that define the cells of a MAP-Elites archive in a framework like OpenEvolve.","open-ended/chapters/10-evolution-frameworks.html","oe","A4"],["Feature map","The grid of filter responses produced by one filter over an input, showing where its pattern was found.","deep-learning/chapters/07-convolutions.html","dl",""],["Feature register","A table listing each feature's source, the time it is written, whether it can change later and whether it is available at prediction time.","ml/chapters/14-leakage.html","ml",""],["Few-shot prompting","Including a handful of worked input-output examples in the prompt so the model picks up the task, format and tone without any change to its weights.","agents/chapters/04-prompting.html","agt","A2"],["Filter","The small grid of learned weights, also called a kernel, that a convolutional layer slides over its input.","deep-learning/chapters/07-convolutions.html","dl",""],["Finding (red team)","A recorded, reproducible way of reaching an attack goal, with enough detail for someone else to replay it and fix its cause.","evals/chapters/16-red-teaming.html","evl","A3"],["Fine-tuning an embedder","Continuing to train a pretrained embedding model on your own query and passage pairs, followed by re-embedding the whole corpus.","agents/chapters/23-dense-retrieval.html","agt","A2"],["Finite difference","An estimate of a derivative from function values at nearby points, such as (f(x+h) - f(x-h)) / 2h.","ml-foundations/chapters/08-derivatives.html","mlf",""],["First failure","The earliest wrong step in a trace, which is counted because later errors often follow from it.","evals/chapters/01-error-analysis.html","evl",""],["Fitness function","The score that an evolutionary algorithm tries to increase, computed by evaluating a candidate.","open-ended/chapters/02-evolutionary-algorithms.html","oe","A1 A4"],["Fitness landscape","A picture in which genotypes are places, neighbours are one mutation apart, and height is fitness.","open-ended/chapters/19-evolution-for-builders.html","oe","A1"],["Fitness sharing","A niching method that divides each individual's score by how many others are nearby, so crowded peaks pay less.","open-ended/chapters/19-evolution-for-builders.html","oe","A1"],["Five Cs","Keshav's first-pass questions: category, context, correctness, contributions and clarity.","ml-foundations/chapters/16-reading-papers.html","mlf","A1"],["FlashAttention","An exact attention kernel that works tile by tile in on-chip memory and never writes the full score matrix to HBM.","deep-learning/chapters/19-efficient-attention.html","dl","A3"],["Flight recorder","A ring buffer of recent communication events and stack traces per rank, dumped when a watchdog fires so a hang can be traced to its cause.","llm-training/chapters/05-long-runs.html","llm","A1"],["Float","Python's real-number type: a 64-bit IEEE 754 double stored as a 24-byte object, accurate to about 15 to 16 significant digits.","ml-foundations/chapters/01-python-numerics.html","mlf",""],["Floating-point number","A number stored as a sign, an exponent and a mantissa, like binary scientific notation, so precision is a roughly constant fraction of the value.","ml-foundations/chapters/11-numerics.html","mlf",""],["FLOPs","A count of floating-point operations (additions or multiplications), the amount of arithmetic a computation needs, as distinct from FLOP/s, the speed at which hardware performs it.","deep-learning/chapters/16-resource-accounting.html","dl","A1"],["FLOP/s","Floating-point operations per second: the rate at which a chip does arithmetic, as opposed to FLOPs, a count of operations in a job.","ml-foundations/chapters/17-compute-costs.html","mlf","A1"],["FML-bench","A benchmark of 18 fundamental machine-learning research tasks designed to compare research-agent strategies under a shared interface and budget.","harness-eng/chapters/02-aide-tree-search.html","he","A2"],["FML-bench-Lite","An 8-task subset of FML-bench that drops the high-variance continual-learning and unlearning tasks.","harness-eng/chapters/05-research-benchmarks.html","he","A2"],["Fold","One of the k parts of the data in cross-validation, used once for validation and k minus 1 times for training.","ml/chapters/13-cross-validation.html","ml",""],["Format reward","A small reward for putting the answer in a required structure, such as reasoning inside think tags, so that the final answer can be extracted and checked.","llm-training/chapters/14-rlvr-grpo.html","llm","A2 A4"],["Forward and reverse KL","KL(p || q) punishes a model for missing mass the truth has and so covers all modes; KL(q || p) punishes mass the truth lacks and so locks onto one mode.","ml-foundations/chapters/14-information-theory.html","mlf",""],["Forward chaining","A time-respecting split in which each fold trains on everything before a cut-off and validates on the block just after it.","ml/chapters/13-cross-validation.html","ml",""],["forward function","The single function a meta agent writes to define an agent in the ADAS framework: it takes the task information and returns the agent's answer.","open-ended/chapters/12-meta-agent-search.html","oe","A2 A4"],["Forward-mode autodiff","Differentiation that carries a derivative alongside every value, giving the effect of one input on all outputs per pass.","ml-foundations/chapters/09-autodiff.html","mlf",""],["Foundation model","A large pretrained model that is adapted or called for many tasks rather than trained from scratch for each one.","ml-foundations/chapters/00-start-here.html","mlf",""],["fp16","The IEEE 16-bit floating-point format with 5 exponent and 10 mantissa bits, more precise than bf16 but overflowing above 65,504.","deep-learning/chapters/17-training-stability.html","dl","A1"],["fp8","An 8-bit floating-point format, in E4M3 or E5M2 form, that needs per-tensor or per-block scale factors to fit values in its narrow range.","ml-foundations/chapters/11-numerics.html","mlf",""],["Fresh-variant gap test","Comparing a model's accuracy on original benchmark items with its accuracy on newly made equivalent items to reveal memorisation.","evals/chapters/07-contamination.html","evl","A2 A3"],["Frobenius norm","The square root of the sum of all squared entries of a matrix.","ml-foundations/chapters/07-decompositions.html","mlf",""],["Frontier hardness","The rate at which direct improvement productivity falls as capability rises, written sigma in Burtsev's model.","rsi-measurement/chapters/03-loop-economics.html","rsi","A4"],["FSDP","Fully Sharded Data Parallel, PyTorch's implementation of the ZeRO-3 idea, in which each GPU stores a shard of everything and gathers weights layer by layer.","llm-training/chapters/03-parallelism.html","llm",""],["Fuel (step budget)","A limit on the number of steps a candidate may take, counted by ticks injected into its code, so that endless loops end without a clock.","ml-foundations/chapters/21-programs-as-data.html","mlf","A1"],["Full factorial design","An experiment that runs every combination of the factor levels.","research-eng/chapters/04-ablations-tracking.html","re","A1"],["Function calling","The mechanism by which a model replies with a structured request to run a named function with arguments, which your program runs before returning the result.","agents/chapters/06-function-calling.html","agt",""],["Function set","The operations a genetic programming tree may use at its internal nodes, such as add, subtract and max.","open-ended/chapters/20-gp-neuroevolution-cmaes.html","oe",""],["Function value","A function treated like any other piece of data, so it can be stored in a variable, passed as an argument, returned as a result or kept in a dictionary.","ml-foundations/chapters/20-functions-objects.html","mlf","A1"],["FunSearch","A DeepMind system that pairs a code-writing language model with an automatic evaluator and an island-based program database to evolve a single function.","open-ended/chapters/09-program-evolution.html","oe","A4"],["Fused kernel","A single kernel that performs several operations while values stay on chip, avoiding writes and re-reads of intermediate arrays.","llm-training/chapters/04-kernels.html","llm","A3"],["Future","A placeholder for a result that a worker will produce later; waiting on it with a timeout does not stop the worker.","ml-foundations/chapters/22-running-candidates.html","mlf","A1"],["Gap (embargo)","Rows dropped between the training window and the validation block so that labels or features that overlap the cut-off cannot leak.","ml/chapters/13-cross-validation.html","ml",""],["Gate","A programmatic check between two steps of a workflow that decides whether to continue, so that bad output stops cheaply instead of propagating.","agents/chapters/13-workflow-patterns.html","agt",""],["Gate","A learned vector of numbers between 0 and 1, produced by a sigmoid, that scales how much of another vector passes through.","deep-learning/chapters/08-sequences-rnns.html","dl",""],["Gate","The public result that an artifact must reach before the next one starts, such as 100 or more overnight experiments, a gap chart and a short write-up.","research-eng/chapters/00-start-here.html","re","A1"],["Gate (artifact)","The public, checkable result an artifact must reach before it counts as finished, such as a hacking rate measured before and after hardening.","control/chapters/00-start-here.html","ctl","A3"],["Gated linear unit","A layer that multiplies two parallel linear projections of the input element by element, one of them passed through a nonlinearity that acts as a gate.","deep-learning/chapters/10-transformer-block.html","dl",""],["Gödel machine","Schmidhuber's theoretical self-rewriting system that changes its own code only after proving the change improves its expected reward, which makes it elegant but impractical.","open-ended/chapters/13-self-improving-agents.html","oe","A4"],["GELU","A smooth activation that weights its input by the probability that a standard normal variable is smaller than it.","deep-learning/chapters/01-neurons-layers.html","dl",""],["GenAI semantic conventions","OpenTelemetry's naming rules for spans, attributes and metrics of model calls, tool calls and agents, currently in Development status.","evals/chapters/17-observability.html","evl",""],["Generalisation error","The expected loss of a model on new cases drawn from the same distribution as its training data, which can only be estimated, never observed directly.","ml/chapters/01-generalisation.html","ml",""],["Generalisation gap","The difference between a model's error on unseen data and its error on the data it was trained on.","ml/chapters/01-generalisation.html","ml",""],["Generalised advantage estimation (GAE)","An advantage estimator that sums future TD errors with weights (gamma times lambda) to the power of their delay, trading critic bias against sampling noise.","llm-training/chapters/09-value-functions.html","llm",""],["General-purpose AI model","A broadly capable model, such as a large language model, whose developers have separate documentation and risk duties under the EU AI Act.","evals/chapters/21-governance.html","evl",""],["Generative AI Profile","NIST AI 600-1, a companion to the AI RMF that names twelve risks specific to generative AI and suggests actions for each.","evals/chapters/21-governance.html","evl",""],["Genetic algorithm","An evolutionary algorithm over fixed-length strings, using selection, crossover and mutation.","open-ended/chapters/02-evolutionary-algorithms.html","oe","A1 A4"],["Genetic drift","Chance changes in which gene variants survive in a finite population, with no help from selection.","open-ended/chapters/19-evolution-for-builders.html","oe","A1"],["Genetic programming","Evolutionary search whose candidates are programs stored as trees, varied by swapping and regrowing branches.","open-ended/chapters/20-gp-neuroevolution-cmaes.html","oe",""],["Genome","The data structure that encodes one candidate solution in an evolutionary algorithm, such as a bit string, a vector or a program.","open-ended/chapters/02-evolutionary-algorithms.html","oe","A1 A4"],["Genotype","The inherited code of an individual, such as DNA in a cell or the source text of a program.","open-ended/chapters/19-evolution-for-builders.html","oe","A1"],["Genotype-phenotype map","The rule that turns a genotype into a phenotype; it decides how much of the variation made by mutation is useful.","open-ended/chapters/19-evolution-for-builders.html","oe","A1"],["GEPA","A prompt optimiser that reflects on trajectories in natural language and keeps a Pareto frontier of candidate prompts.","open-ended/chapters/11-evolving-prompts.html","oe","A2"],["Git worktree","A second working directory of the same repository on its own branch, letting several agent sessions edit in parallel without overwriting each other.","agents/chapters/22-ai-coding-tools.html","agt",""],["Glitch token","A vocabulary entry that existed in the tokeniser but was almost never seen in the model's training data, so its embedding is barely trained and it triggers odd outputs.","deep-learning/chapters/13-tokenisation.html","dl","A1"],["Global interpreter lock (GIL)","A lock in standard CPython that lets only one thread run Python bytecode at a time, so threads do not speed up CPU-bound work.","ml-foundations/chapters/22-running-candidates.html","mlf","A1"],["Global pooling","Collapsing a whole feature map to one number per channel, which discards position.","deep-learning/chapters/07-convolutions.html","dl",""],["Goal hijacking","A direct injection that redirects a model away from its assigned task to the attacker's task.","evals/chapters/13-prompt-injection.html","evl",""],["Gold answer","The trusted answer, accepted variants or checking rule against which a response to an item is scored.","evals/chapters/06-building-benchmarks.html","evl","A2"],["Gold set","A set of items whose labels are trusted enough to measure systems or judges against.","evals/chapters/05-human-labels.html","evl",""],["Goodhart's law","The observation that when a measure becomes a target it ceases to be a good measure.","evals/chapters/07-contamination.html","evl","A2 A3"],["Goodhart's law","The principle that when a measure becomes a target it ceases to be a good measure, because optimisation exploits the gap between the measure and what it stands for.","llm-training/chapters/13-reward-models.html","llm","A3"],["Goodhart's law","The tendency of a measure to stop reflecting its purpose once it is used as a target to optimise.","ml/chapters/02-framing-metrics.html","ml",""],["Goodhart's law","When a measure becomes a target, it stops being a good measure.","open-ended/chapters/15-evaluator-hacking.html","oe","A3"],["Goodhart's law (interestingness)","The risk that once a generator is optimised against a judge's scores, those scores stop reflecting what people actually find interesting.","open-ended/chapters/06-interestingness.html","oe",""],["Governor","A process outside the sandbox that tracks spend, denials and heartbeats and halts the run when a rule trips.","control/chapters/05-incident-playbook.html","ctl","A3"],["GPT","Generative Pre-trained Transformer: an autoregressive language model built from decoder-only Transformer blocks.","deep-learning/chapters/12-building-gpt.html","dl","A1"],["GPU","A processor with thousands of simple arithmetic units and very wide memory access, fast at large, regular, parallel work such as matrix multiplication.","ml-foundations/chapters/17-compute-costs.html","mlf","A1"],["Gradient","The vector of partial derivatives of the loss with respect to each parameter, pointing in the direction of steepest increase.","ml-foundations/chapters/00-start-here.html","mlf",""],["Gradient accumulation","The behaviour that each backward pass adds to the existing .grad values rather than replacing them, so they must be cleared every step.","deep-learning/chapters/05-pytorch.html","dl",""],["Gradient accumulation","Summing gradients over several micro-batches before one optimiser step, giving the gradient of a large batch while holding only a small batch's activations.","llm-training/chapters/02-gpu-memory.html","llm","A1"],["Gradient check","A test that compares a hand-written gradient with a finite-difference estimate on a tiny network.","deep-learning/chapters/02-backpropagation.html","dl",""],["Gradient check","Testing an analytic gradient against finite differences, entry by entry, using relative error in float64.","ml-foundations/chapters/08-derivatives.html","mlf",""],["Gradient checkpointing","Saving activations at only a few layers and recomputing the rest during the backward pass, trading extra compute for memory.","ml-foundations/chapters/09-autodiff.html","mlf",""],["Gradient clipping","Rescaling the whole gradient to a maximum norm when it grows too large, limiting step size without changing direction.","deep-learning/chapters/08-sequences-rnns.html","dl",""],["Gradient clipping","Rescaling the whole gradient when its global norm exceeds a threshold, so a single bad batch cannot cause a huge step.","ml-foundations/chapters/10-optimisers.html","mlf",""],["Gradient descent","Training by repeatedly moving the parameters a small step against the gradient of the loss.","ml-foundations/chapters/00-start-here.html","mlf",""],["Gradient norm","The length of the gradient vector taken over all parameters, a leading indicator of instability when logged before clipping.","deep-learning/chapters/17-training-stability.html","dl","A1"],["Gradient variance","The spread of gradient estimates around their expected value from batch to batch; high variance makes updates noisy and training slow or unstable.","llm-training/chapters/07-policy-gradients.html","llm",""],["Greedy decoding","Always choosing the single most probable next token, which is deterministic but tends to repeat itself in open-ended text.","deep-learning/chapters/15-decoding.html","dl",""],["Greedy hill-climbing","A search that keeps a change only if it strictly improves the score and otherwise reverts.","harness-eng/chapters/02-aide-tree-search.html","he","A2"],["Grounded feedback","Feedback produced by something outside the model, such as test results, schema validators or retrieval checks, rather than by its self-assessment.","agents/chapters/03-reasoning-planning.html","agt",""],["Grounding","Mapping a description such as the Submit button to a precise target on the screen, in pixels or as a reference to an element.","agents/chapters/17-computer-use.html","agt",""],["Grounding","Tying a model's answer to supplied evidence, so it answers from the documents or tool results it was given rather than from memory.","evals/chapters/11-grounding-abstention.html","evl",""],["Grouped-query attention","Attention in which groups of query heads share one key/value head, a dial between multi-head and multi-query attention.","deep-learning/chapters/19-efficient-attention.html","dl","A3"],["Group k-fold","A k-fold split that keeps all rows of one group, such as a patient or customer, in the same fold so no group appears on both sides.","ml/chapters/13-cross-validation.html","ml",""],["Group-relative advantage","An answer's reward minus the mean reward of its group, usually divided by the group's standard deviation, shared by every token of that answer.","llm-training/chapters/14-rlvr-grpo.html","llm","A2 A4"],["Group sequential testing","Planned repeated looks at an experiment using stricter per-look boundaries so the overall false-positive rate stays at the stated level.","ml-foundations/chapters/15-statistics.html","mlf","A1"],["GRPO (Group Relative Policy Optimisation)","A PPO variant that drops the value model and computes each answer's advantage by comparing its reward with the other answers sampled for the same prompt.","llm-training/chapters/14-rlvr-grpo.html","llm","A2 A4"],["GRU","A gated recurrent unit that merges the LSTM's cell and hidden state and uses two gates, with similar behaviour at lower cost.","deep-learning/chapters/08-sequences-rnns.html","dl",""],["Guardrail","A check on an agent's input or output, run by the framework, that can block or flag a request or reply.","agents/chapters/21-frameworks.html","agt",""],["Guardrail","A check outside the main model that inspects an input, retrieved text, an answer or an action and allows, blocks, rewrites or escalates it.","evals/chapters/15-guardrails.html","evl",""],["Guardrail recall","Of the inputs the policy says must be caught, the share the guardrail actually caught.","evals/chapters/15-guardrails.html","evl",""],["gVisor","A user-space application kernel that handles a program's system calls itself instead of passing them to the host kernel.","agents/chapters/20-sandboxing.html","agt","A2"],["Hacking rate","The share of candidates whose public score is high while their private score is low or a wall was tripped, reported next to the score.","control/chapters/01-threat-model.html","ctl","A3"],["Hacking rate","The fraction of accepted candidates that score well on the visible tests but much worse on the hidden ones.","harness-eng/chapters/00-start-here.html","he","A2"],["Hacking rate (artifact)","The share of an agent's attempts that raised the score by exploiting the evaluator instead of solving the task.","control/chapters/00-start-here.html","ctl","A3"],["Hallucinated results","Experimental results, such as an ablation table, that a system reports although it never ran the experiments.","open-ended/chapters/14-automated-science.html","oe","A4"],["Hallucination","Fluent, plausible model output that is not supported by the facts of the world or by the material the model was given.","evals/chapters/10-hallucination.html","evl",""],["Hallucination snowballing","A model committing to an early mistake and then producing further errors to stay consistent with it.","evals/chapters/10-hallucination.html","evl",""],["Handoff","A one-way transfer in which one agent passes execution and the conversation state to another agent that takes over.","agents/chapters/14-multi-agent.html","agt",""],["Hang","A failure in which no rank crashes but progress stops, typically because one rank never joins a collective operation.","llm-training/chapters/05-long-runs.html","llm","A1"],["Hard negative","A passage that looks relevant to the query (high lexical or embedding score) but is not, used to teach fine distinctions.","agents/chapters/23-dense-retrieval.html","agt","A2"],["Hard regression","A test case that passed on every repeated run before a change and fails on most runs after it.","evals/chapters/18-improvement-flywheel.html","evl",""],["Harness","The program around the model that holds the history, runs tools, enforces limits and decides when the loop ends.","agents/chapters/02-tool-loop.html","agt","A2"],["Harness","The software around a model that runs its loop: its tools, context, files and checks on results.","harness-eng/chapters/00-start-here.html","he","A2"],["Harness","The code around an evaluator that runs candidates, collects their outputs and applies the checks.","open-ended/chapters/15-evaluator-hacking.html","oe","A3"],["Hash","A function mapping any input to a fixed-length fingerprint, where changing any bit of the input changes the output unpredictably.","control/chapters/03-attested-results.html","ctl","A3"],["Hashable","Describes a value with a fixed, unchanging hash, which lets it be a dictionary key or set member; tuples of numbers are hashable and lists are not.","ml-foundations/chapters/20-functions-objects.html","mlf","A1"],["Hash chain","A log in which each entry's fingerprint includes the previous entry's fingerprint, so editing one entry breaks all later links.","control/chapters/03-attested-results.html","ctl","A3"],["Hash chain","A log in which each record includes the hash of the previous one, so altering history becomes detectable.","open-ended/chapters/17-self-modification-safety.html","oe","A3"],["HBM","High-bandwidth memory, the large main memory of a GPU, much bigger and slower than its on-chip SRAM.","deep-learning/chapters/19-efficient-attention.html","dl","A3"],["HBM","High-bandwidth memory: the large off-chip memory on a GPU (80 GB on an H100) where weights and activations live between operations.","llm-training/chapters/04-kernels.html","llm","A3"],["HBM (high-bandwidth memory)","The fast on-package memory of a data-centre GPU, whose fixed capacity (for example 80 GB) limits what can be trained on one device.","llm-training/chapters/02-gpu-memory.html","llm","A1"],["Head sampling","Deciding whether to keep a trace when it starts, before anything is known about how it will turn out.","evals/chapters/17-observability.html","evl",""],["He initialisation","Drawing weights with variance 2 divided by fan-in, which compensates for ReLU discarding half the signal.","deep-learning/chapters/03-training-dynamics.html","dl","A1"],["Held-out gain","The improvement of a change measured on data or a budget that the research loop never reads.","research-eng/chapters/00-start-here.html","re","A1"],["Held-out set","Test cases kept out of prompts, examples and training data so they measure generalisation.","evals/chapters/02-eval-harnesses.html","evl","A3"],["Held-out set","Examples kept out of training so that performance on them estimates how the model handles new inputs.","llm-training/chapters/23-evaluating-models.html","llm",""],["Held-out split","Data the research loop never reads, used only to measure whether gains transfer.","research-eng/chapters/02-proxies-noise.html","re","A1"],["Hessian","The matrix of second partial derivatives, describing the curvature of a function in every direction.","ml-foundations/chapters/08-derivatives.html","mlf",""],["Hidden precondition","A requirement a stored skill silently relies on, such as an item already being in the inventory, which makes it fail in a different state.","open-ended/chapters/07-lifelong-agents.html","oe","A4"],["Hidden state","The fixed-size vector a recurrent network carries from step to step as a summary of everything read so far.","deep-learning/chapters/08-sequences-rnns.html","dl",""],["Hidden state","Variables held in a running notebook kernel that influence results but are not visible in the cells as written.","ml-foundations/chapters/04-reproducible-experiments.html","mlf","A1"],["High-risk AI system","Under the EU AI Act, a system in a product-safety area or a listed use such as employment or credit, which must meet requirements on risk management, data, documentation, logging, oversight and robustness.","evals/chapters/21-governance.html","evl",""],["Hook","A script that a coding tool runs automatically at a defined point, such as after an edit or before stopping, so an action happens every time regardless of what the model decides.","agents/chapters/22-ai-coding-tools.html","agt",""],["Huber loss","A loss that is quadratic for small residuals and linear for large ones, limiting the pull of outliers.","ml-foundations/chapters/13-likelihood-losses.html","mlf",""],["Huffman coding","An optimal prefix code that gives short codewords to likely symbols, with average length within one bit of the entropy.","ml-foundations/chapters/14-information-theory.html","mlf",""],["Human ceiling","The score domain experts achieve on a benchmark under the same conditions, which shows how much headroom exists.","evals/chapters/06-building-benchmarks.html","evl","A2"],["Human gate","A point in the loop where a person must approve a change or promotion before it proceeds.","open-ended/chapters/17-self-modification-safety.html","oe","A3"],["Human oversight","Design measures that let people understand an AI system's outputs, notice over-reliance, override results and stop the system.","evals/chapters/21-governance.html","evl",""],["Huxley-Gödel Machine","A self-improving coding agent that picks which agent to expand by the aggregated performance of its descendants instead of its own score.","rsi-measurement/chapters/05-reading-pack.html","rsi","A4"],["Hybrid model","A model that mixes mostly recurrent or state-space layers with a few attention layers, to keep exact lookup at a smaller cache.","deep-learning/chapters/22-beyond-attention.html","dl",""],["Hyperagent","A task agent and a meta agent in one editable program, so the procedure that generates improvements can itself be changed.","rsi-measurement/chapters/05-reading-pack.html","rsi","A4"],["Hypernetwork","A network whose output is the weights of another network.","llm-training/chapters/17-adapters-on-demand.html","llm",""],["Hyperparameter","A setting chosen by the practitioner rather than learned from data, such as polynomial degree or learning rate.","ml/chapters/01-generalisation.html","ml",""],["Hyperparameter schedule","A setting such as the learning rate that changes over the course of training instead of staying fixed.","open-ended/chapters/22-coevolution-pbt.html","oe","A4"],["Idempotency key","A unique value sent with a side-effecting request so that a repeat of the same request returns the first result instead of acting twice.","agents/chapters/02-tool-loop.html","agt","A2"],["Identity matrix","The matrix with ones on its diagonal and zeros elsewhere, which leaves every vector unchanged.","ml-foundations/chapters/06-matrices.html","mlf",""],["Ignition test","Swapping the agent a loop discovered into the outer loop's seat and checking whether it is a better improver than the original.","rsi-measurement/chapters/00-start-here.html","rsi","A4"],["i.i.d.","Independent and identically distributed: each example is drawn separately from the same distribution, an assumption behind most validation methods.","ml/chapters/01-generalisation.html","ml",""],["Illumination","Using search to show how performance varies across behaviour space, rather than only finding the single best point.","open-ended/chapters/04-quality-diversity.html","oe","A4"],["Image encoder","The network, usually a Vision Transformer, that turns patches into feature vectors carrying what is in each region.","deep-learning/chapters/21-vision-language.html","dl",""],["Image tokens","The projected vectors that stand for an image in the language model's context, N = (size / patch) squared before any merging.","deep-learning/chapters/21-vision-language.html","dl",""],["Implicit decision","A choice such as a style, format or name that an agent makes while acting and that parallel agents cannot see, causing conflicts when merged.","agents/chapters/14-multi-agent.html","agt",""],["Implicit reward","In DPO, the quantity beta times the log of the policy's probability over the reference's probability for a response, which plays the role of the reward.","llm-training/chapters/12-preference-optimisation.html","llm",""],["Importance sampling","Rewriting an expectation under one distribution as an expectation under another by weighting each sample by the ratio of their probabilities.","llm-training/chapters/08-ppo.html","llm",""],["Importance sampling","Estimating an expectation under one distribution using samples from another, each re-weighted by the ratio of the two densities.","ml-foundations/chapters/12-probability.html","mlf",""],["Improvement flywheel","A loop in which production failures are captured, labelled and turned into permanent tests, so each turn leaves the system better protected.","evals/chapters/18-improvement-flywheel.html","evl",""],["Improver","A program that takes a solution and a utility and returns a better solution, such as a search loop that proposes edits and keeps the ones that score higher.","open-ended/chapters/21-self-referential-improvers.html","oe","A4"],["In-batch negatives","Using the positive passages of the other queries in a training batch as negatives, giving B squared comparisons from B pairs.","agents/chapters/23-dense-retrieval.html","agt","A2"],["In-context learning","A trained model picking up a task from examples in its prompt, with no change to its weights.","deep-learning/chapters/24-learned-optimisers.html","dl","A2 A4"],["In-context learning","A model adapting to a task from examples in its prompt without any change to its weights.","rsi-measurement/chapters/05-reading-pack.html","rsi","A4"],["Independent origins","The distinct underlying sources behind a set of documents, counting a news story that quotes a report as the report rather than as a second witness.","agents/chapters/16-deep-research.html","agt",""],["Independent verification","Checking code with tests or sources that its author did not write, such as hand values, properties, edge cases or a numerical gradient.","ml-foundations/chapters/19-ai-assistants.html","mlf",""],["Indirect prompt injection","Prompt injection in which a third party plants instructions in content an agent later reads, so the attacker never talks to the system directly.","agents/chapters/19-agent-security.html","agt","A3"],["Indirect prompt injection","An injection planted by a third party in content, such as a web page, email or document, that the application later feeds to the model.","evals/chapters/13-prompt-injection.html","evl",""],["Induction head","A pair of attention heads that, having seen the pattern A B earlier in the context, predict B when A appears again.","deep-learning/chapters/09-attention.html","dl",""],["Inductive bias","An assumption built into a model's structure, such as locality in a convolution, that helps it learn from less data but limits what it can easily represent.","deep-learning/chapters/07-convolutions.html","dl",""],["Inductive bias","The assumptions built into a learning algorithm that let it prefer some functions over others when the data alone cannot decide.","ml/chapters/01-generalisation.html","ml",""],["Inference (serving)","Running a trained model to produce answers for users, as opposed to training it.","llm-training/chapters/00-start-here.html","llm",""],["Inference-time search","Spending extra computation on one question at answer time, by sampling, checking and building on candidates, without changing the model's weights.","open-ended/chapters/08-inference-time-search.html","oe","A2"],["InfoNCE","A softmax contrastive loss that asks the model to pick the true positive out of one positive and many negatives.","agents/chapters/23-dense-retrieval.html","agt","A2"],["Inheritance","The tendency of offspring to resemble their parents because genomes are copied.","open-ended/chapters/19-evolution-for-builders.html","oe","A1"],["Injected prompt text","Instructions a framework adds to the system prompt or tool descriptions on its own, which cost tokens and shape behaviour without appearing in your source.","agents/chapters/21-frameworks.html","agt",""],["Inner join","A join that keeps only the rows whose key matches in both tables.","ml-foundations/chapters/03-data-wrangling.html","mlf",""],["Inner loop","The agent doing a job, for example editing code against a score and keeping edits that help.","rsi-measurement/chapters/01-level-one.html","rsi","A4"],["Innovation number","A global, ever-increasing label given to each new connection in NEAT, so that genes can be aligned across genomes.","open-ended/chapters/20-gp-neuroevolution-cmaes.html","oe",""],["Input and output tokens","The tokens you send to a model and the tokens it writes, which providers price at different rates.","evals/chapters/19-cost-latency-quality.html","evl",""],["Input check","A guardrail that inspects the user's message before the model sees it.","evals/chapters/15-guardrails.html","evl",""],["Instruction drift","The loss of weight of early rules against recent context in a long run, so the model gradually stops following them.","agents/chapters/04-prompting.html","agt","A2"],["Instruction file","A Markdown file in a repository, such as CLAUDE.md or AGENTS.md, that tells a coding agent how to build, test and follow local conventions.","agents/chapters/18-coding-agents.html","agt","A2"],["Instruction hierarchy","Training a model to prioritise system instructions over user text and user text over tool output.","agents/chapters/19-agent-security.html","agt","A3"],["Instruction hierarchy","A training approach that teaches a model to give developer instructions priority over user text and third-party content when they conflict.","evals/chapters/13-prompt-injection.html","evl",""],["Intelligent Go-Explore","A hard-exploration method that uses a foundation model to judge which states are interesting enough to archive and return to.","open-ended/chapters/06-interestingness.html","oe",""],["Interaction","A case where one factor's effect depends on the level of another.","research-eng/chapters/04-ablations-tracking.html","re","A1"],["Inter-agent misalignment","A category of multi-agent failure in which agents fail to communicate, share or act on what another agent produced.","agents/chapters/14-multi-agent.html","agt",""],["Inter-annotator agreement","How often independent annotators give the same label to the same items, used to judge whether a guideline is reproducible.","evals/chapters/05-human-labels.html","evl",""],["Interleaved thinking","Reasoning by the model between tool calls within one turn, so it can read each tool result before deciding the next action.","agents/chapters/03-reasoning-planning.html","agt",""],["Interpolation threshold","The model size at which a model can just barely fit its training data exactly, where test error often peaks.","deep-learning/chapters/04-deep-regularisation.html","dl",""],["Intrinsic dimension","The smallest number of free parameters in which a fine-tuning task can still be solved well, found to be far below a model's parameter count.","llm-training/chapters/11-lora.html","llm",""],["Inverse","The matrix that undoes another, A^-1 A = I, which exists only when the determinant is non-zero.","ml-foundations/chapters/06-matrices.html","mlf",""],["Inverse-CDF sampling","Drawing from any distribution by feeding a uniform random number through the inverse of its cumulative distribution function.","ml-foundations/chapters/12-probability.html","mlf",""],["Inverted dropout","Dropout in which the surviving units are scaled by 1/(1 - p) during training, so that no change is needed at evaluation time.","deep-learning/chapters/04-deep-regularisation.html","dl",""],["Inverted pyramid","A document structure that puts the answer and decision first, the evidence next and the checking detail last, so readers can stop at any layer.","ml-foundations/chapters/18-technical-writing.html","mlf","A1 A4"],["IPO (Identity Preference Optimisation)","A DPO variant that uses a squared loss on the log-ratio margin, so the regulariser keeps working even when preference labels are deterministic.","llm-training/chapters/12-preference-optimisation.html","llm",""],["Irreducible error","The part of the error caused by noise in the labels that no model could predict, setting a floor on achievable error.","ml/chapters/01-generalisation.html","ml",""],["Irreducible loss","The part of the loss that no model size or data amount can remove, set by the entropy of the data itself.","deep-learning/chapters/18-scaling-laws.html","dl","A1"],["Irreducible loss","The floor E in the scaling law that no amount of parameters or data removes.","research-eng/chapters/03-scaling-mup.html","re","A1"],["isError","The flag on a tools/call result that marks a tool execution failure the model can read and correct, as opposed to a protocol error.","agents/chapters/07-mcp.html","agt",""],["Island model","A population split into sub-populations that evolve separately, so no single family of solutions can take over the whole search.","open-ended/chapters/09-program-evolution.html","oe","A4"],["IsoFLOP curve","The loss of models of different sizes that all use the same training compute, with a minimum at the compute-optimal size.","deep-learning/chapters/18-scaling-laws.html","dl","A1"],["Item (benchmark)","One case in a benchmark: an input, any context it needs, and the information required to score a response.","evals/chapters/06-building-benchmarks.html","evl","A2"],["Item response theory","A statistical framework that models the chance of solving an item from the system's ability and the item's difficulty.","evals/chapters/06-building-benchmarks.html","evl","A2"],["Iteration budget","A cap on the number of model calls an agent may make for one task, bounding cost and time.","agents/chapters/02-tool-loop.html","agt","A2"],["Iterative prompting","Repeatedly asking a model to rewrite its code using feedback from the environment, interpreter errors and a critic until the task succeeds or attempts run out.","open-ended/chapters/07-lifelong-agents.html","oe","A4"],["Jaccard similarity","The size of the overlap of two sets divided by the size of their union, used to measure how alike two documents' shingle sets are.","llm-training/chapters/01-pretraining-data.html","llm",""],["Jacobian","The matrix of all partial derivatives of a function's outputs with respect to its inputs.","deep-learning/chapters/02-backpropagation.html","dl",""],["Jacobian","The (m, n) matrix of partial derivatives of an m-vector function of an n-vector, the best linear approximation of the function near a point.","ml-foundations/chapters/08-derivatives.html","mlf",""],["Jailbreak","An input that gets a model to ignore its own safety training and produce content that its provider or developer prohibits.","evals/chapters/13-prompt-injection.html","evl",""],["JSON Lines","A text format with one JSON object per line, easy to append to and to replay line by line.","ml-foundations/chapters/22-running-candidates.html","mlf","A1"],["JSON-RPC 2.0","A small standard for remote procedure calls in JSON, made of requests with ids, responses holding a result or an error, and one-way notifications.","agents/chapters/07-mcp.html","agt",""],["JSON Schema","A standard vocabulary for describing the shape of a JSON document, used to specify the arguments of each tool.","agents/chapters/02-tool-loop.html","agt","A2"],["Just-in-time retrieval","Keeping lightweight references such as paths and queries and loading the data with tools only when a step needs it, instead of loading it up front.","agents/chapters/10-context-engineering.html","agt","A2"],["k3 estimator","The sample estimate (r - 1) - ln r of KL, with r the ratio of reference to policy probability, which is unbiased, non-negative and low in variance.","ml-foundations/chapters/14-information-theory.html","mlf",""],["Keep-or-revert","The decision rule that keeps a change if its score beats the best so far and undoes it otherwise.","research-eng/chapters/01-research-loop.html","re","A1"],["Kendall's tau","A rank correlation between score and step number, equal to +1 when scores always rise.","rsi-measurement/chapters/01-level-one.html","rsi","A4"],["Kernel","A function that runs on a GPU, launched across many parallel workers at once.","harness-eng/chapters/04-kernels-for-agents.html","he","A3"],["Kernel","A function that runs on the GPU across many threads, launched from the CPU.","llm-training/chapters/04-kernels.html","llm","A3"],["KernelBench","An open-source suite of 250 PyTorch workloads that tests whether models write GPU kernels that are both correct and fast.","control/chapters/00-start-here.html","ctl","A3"],["KernelBench","A benchmark of 250 PyTorch workloads in which a model must write GPU kernels that are correct and faster.","harness-eng/chapters/04-kernels-for-agents.html","he","A3"],["KernelBench-Verified","A revision of KernelBench with a TF32 baseline and a hidden test suite over four input distributions.","harness-eng/chapters/04-kernels-for-agents.html","he","A3"],["Key (attention)","The vector attached to each position that is compared with queries to decide how much that position is read.","deep-learning/chapters/09-attention.html","dl",""],["Key (table)","A column or set of columns that identifies each row of a table uniquely.","ml-foundations/chapters/03-data-wrangling.html","mlf",""],["k-fold cross-validation","Splitting the rows into k folds, training on k minus 1 of them and scoring on the held-out one in turn, then averaging the k scores.","ml/chapters/13-cross-validation.html","ml",""],["Kill switch","A means of ending a run at once that sits outside the loop's write boundary, acts below the agent, fails safe and preserves evidence.","control/chapters/05-incident-playbook.html","ctl","A3"],["Kill switch","The most drastic containment lever, which turns an AI feature off and hands the work to people.","evals/chapters/20-ai-incidents.html","evl",""],["KL divergence","The extra bits paid per symbol for using q instead of the true p, KL(p || q) = H(p, q) - H(p); non-negative, asymmetric and not a distance.","ml-foundations/chapters/14-information-theory.html","mlf",""],["KL estimators (k1, k2, k3)","Three single-sample estimators of KL divergence: k1 is unbiased but noisy and can be negative, k2 is biased, and k3 is unbiased and never negative.","llm-training/chapters/08-ppo.html","llm",""],["KL penalty","A cost proportional to the KL divergence between the tuned policy and the reference, applied per token in RLHF to keep the model close to where the reward model is reliable.","llm-training/chapters/08-ppo.html","llm",""],["KL penalty","A term beta times KL(policy || reference) subtracted from the reward in RLHF-style training to keep the tuned model near its starting point.","ml-foundations/chapters/14-information-theory.html","mlf",""],["Krippendorff's alpha","An agreement measure that works for any number of annotators, missing labels and ordered scales.","evals/chapters/05-human-labels.html","evl",""],["KTO (Kahneman-Tversky Optimisation)","A preference method that maximises a prospect-theory utility from single responses labelled desirable or undesirable, so it needs no pairs.","llm-training/chapters/12-preference-optimisation.html","llm",""],["KV cache","The stored keys and values of earlier tokens that attention reads when generating the next token, costing 2 times layers times key/value heads times head width times bytes per token.","deep-learning/chapters/16-resource-accounting.html","dl","A1"],["L2 regularisation","Adding a penalty proportional to the squared size of the weights to the loss, which pulls every weight towards zero.","deep-learning/chapters/04-deep-regularisation.html","dl",""],["Label","A person's recorded judgement about one item against a stated criterion, such as pass or fail.","evals/chapters/05-human-labels.html","evl",""],["Label","The answer attached to a training example that the model is meant to predict; also called the target.","ml/chapters/00-start-here.html","ml",""],["Labelling guideline","The versioned document that defines each label, with decision rules and worked examples, so that different annotators reach the same answer.","evals/chapters/05-human-labels.html","evl",""],["Label noise ceiling","The highest score a perfect system can reach on a test set because some of its gold labels are wrong.","evals/chapters/05-human-labels.html","evl",""],["Label-noise ceiling","The highest honest score on a benchmark given that some of its gold answers are wrong.","evals/chapters/07-contamination.html","evl","A2 A3"],["Ladder","A leaderboard mechanism that reports a new score only when a submission improves on the best by more than a step.","open-ended/chapters/16-held-out-evaluation.html","oe","A2 A3"],["Lambda","A small unnamed function written as a single expression, best kept for short one-off uses such as a sort key.","ml-foundations/chapters/20-functions-objects.html","mlf","A1"],["Language model","A program that, given text, produces more text one token at a time; on its own it can only write.","agents/chapters/00-start-here.html","agt",""],["Language model","A model that assigns a probability to what comes next in a sequence of text, given what came before.","deep-learning/chapters/00-start-here.html","dl",""],["Late binding","Python looks up a closure's captured variable when the function is called, not when it was made, so loop-built lambdas all see the final value.","ml-foundations/chapters/20-functions-objects.html","mlf","A1"],["Latency target (inter-token)","The maximum acceptable time between streamed tokens, which caps the batch size a GPU can run.","llm-training/chapters/22-token-economics.html","llm","A1"],["Law of large numbers","The average of many independent draws converges to the expectation of the distribution they come from.","ml-foundations/chapters/12-probability.html","mlf",""],["Layer","One adjustable step of a network that turns one description of an example into a new one.","deep-learning/chapters/00-start-here.html","dl",""],["Layer normalisation","Rescaling each token's feature vector to zero mean and unit variance, then applying a learned scale and shift.","deep-learning/chapters/03-training-dynamics.html","dl","A1"],["Lead agent","The orchestrating agent in a manager design that plans the work, writes briefs, delegates to sub-agents and synthesises their results.","agents/chapters/14-multi-agent.html","agt",""],["Leads (level 4)","Epoch's level at which AI completes most of a task from a high-level ask and the human supervises and approves.","rsi-measurement/chapters/02-automation-levels.html","rsi","A4"],["Leakage","Information about the target that reaches the model in training or validation but will not legitimately be available when the model is used.","ml/chapters/14-leakage.html","ml",""],["Leak bound","The limit L at most N times log2 M on the bits that can leave through N requests with M distinguishable forms.","control/chapters/02-egress-sandbox.html","ctl","A3"],["Learnability","The property that an observer who studies more of a process's history can predict its later outputs better.","open-ended/chapters/05-open-ended-algorithms.html","oe","A4"],["Learnable task","A task the agent can currently improve on, neither impossible for it nor already mastered.","open-ended/chapters/06-interestingness.html","oe",""],["Learned absolute position embedding","A trained table with one vector per position, added to the token embedding, which caps the context at the table's length.","deep-learning/chapters/11-positions.html","dl",""],["Learned optimiser","An optimiser whose update rule is a small model, trained by an outer loop to make training runs end with a lower loss.","deep-learning/chapters/24-learned-optimisers.html","dl","A2 A4"],["Learned optimiser","An optimiser whose update rule is itself trained, usually across many small training runs.","rsi-measurement/chapters/05-reading-pack.html","rsi","A4"],["Learning parity with noise (LPN)","A task where a hidden rule says whether an odd number of chosen input bits are on, and the rule must be inferred from examples with some wrong labels.","open-ended/chapters/21-self-referential-improvers.html","oe","A4"],["Learning progress","How quickly an agent's success rate on a task is changing, used to find tasks that are learnable right now.","open-ended/chapters/06-interestingness.html","oe",""],["Learning rate","The size of the step taken along the negative gradient at each update.","ml-foundations/chapters/00-start-here.html","mlf",""],["Learning-rate schedule","A rule that changes the learning rate over a run, usually a warmup followed by a decay.","ml-foundations/chapters/10-optimisers.html","mlf",""],["Learning-rate warmup","Raising the learning rate gradually from near zero over the first steps, while the optimiser's running statistics are still unreliable.","deep-learning/chapters/12-building-gpt.html","dl","A1"],["Least privilege","Giving a component only the access its task requires, for an agent across files, commands, network, credentials and resources.","agents/chapters/20-sandboxing.html","agt","A2"],["Least-squares estimator","The linear model that minimises squared error on the examples; the reference that in-context learners are compared with.","deep-learning/chapters/24-learned-optimisers.html","dl","A2 A4"],["Leave-one-out baseline","A baseline for each sample equal to the mean reward of the other samples for the same prompt, which is unbiased and needs no extra model.","llm-training/chapters/07-policy-gradients.html","llm",""],["Leave-one-out cross-validation","The extreme of k-fold where k equals the number of rows, so each row is validated by a model trained on all the others.","ml/chapters/13-cross-validation.html","ml",""],["Ledger","A counter outside the agent that charges every dollar and step to a budget and refuses to exceed it.","rsi-measurement/chapters/01-level-one.html","rsi","A4"],["Left join","A join that keeps every row of the left table and fills the right-hand columns with NULL where there is no match.","ml-foundations/chapters/03-data-wrangling.html","mlf",""],["Legal hold","An obligation to preserve data relevant to a dispute, which can override normal deletion schedules.","evals/chapters/22-privacy-data.html","evl",""],["Length bias","The tendency of reward models and preference-trained policies to favour longer responses because labellers or surface features correlate length with quality.","llm-training/chapters/13-reward-models.html","llm","A3"],["Length-controlled win rate","A judge-based win rate corrected, usually by regression, to estimate what it would be if the compared answers had equal length.","evals/chapters/09-leaderboards.html","evl",""],["Length normalisation","Dividing a sequence's log-probability by a power of its length so that beam search does not prefer short outputs.","deep-learning/chapters/15-decoding.html","dl",""],["Lethal trifecta","The combination of access to private data, exposure to untrusted content and a way to communicate externally, which lets an attacker steal data through an agent.","agents/chapters/19-agent-security.html","agt","A3"],["Lethal trifecta","The combination of access to private data, exposure to untrusted content and the ability to communicate externally, which lets an injection steal data.","evals/chapters/14-architectural-defences.html","evl",""],["Level","A value that a factor takes; two-level designs use off and on.","research-eng/chapters/04-ablations-tracking.html","re","A1"],["Level-1 conditions","Weco AI's four conditions for credible improvement: a fair human baseline, a sustained multi-step trend, generalisation beyond the optimised measurement and a fixed physical budget.","research-eng/chapters/06-write-up.html","re","A1"],["Level 1 (net positive)","Weco's name for a system that improves itself more efficiently than humans improving the same system by hand.","rsi-measurement/chapters/01-level-one.html","rsi","A4"],["Lifelong learning agent","An agent that keeps acquiring and reusing abilities across an open-ended sequence of tasks instead of starting each task from scratch.","open-ended/chapters/07-lifelong-agents.html","oe","A4"],["Likelihood","The probability of the observed data as a function of the model's parameters; it is not a probability of the parameters.","ml-foundations/chapters/13-likelihood-losses.html","mlf",""],["Likelihood displacement","The effect in DPO where the probability of the chosen response falls during training, because the loss only constrains the gap between chosen and rejected.","llm-training/chapters/12-preference-optimisation.html","llm",""],["Lineage","The record of every candidate with its parent, diff, scores, logs and approver, used for audit and rollback.","open-ended/chapters/17-self-modification-safety.html","oe","A3"],["Lineage (of improvers)","The recorded chain of rewrites that produced a given improver, kept outside the improver so people can review each change.","open-ended/chapters/21-self-referential-improvers.html","oe","A4"],["Linear attention","Attention with the softmax replaced by a product of feature maps, so the sum over past tokens can be kept as a fixed-size state.","deep-learning/chapters/22-beyond-attention.html","dl",""],["Linear combination","A sum of vectors each multiplied by a scalar, such as c1 x + c2 y.","ml-foundations/chapters/05-vectors-similarity.html","mlf",""],["Linear map","A function that preserves addition and scaling, so that f(ax + by) = a f(x) + b f(y); every one is a matrix.","ml-foundations/chapters/06-matrices.html","mlf",""],["Linear probe","A linear classifier trained on frozen activations to test whether a property can be read from them.","deep-learning/chapters/23-interpretability-basics.html","dl","A2"],["Linter gate","A check after an edit that rejects it if the file no longer parses, leaving the file unchanged and returning the error.","agents/chapters/18-coding-agents.html","agt","A2"],["List comprehension","A single expression, such as [f(x) for x in xs], that builds a list from another iterable.","ml-foundations/chapters/01-python-numerics.html","mlf",""],["Literature survey","A structured reading of a field, built by following citations backwards and forwards from a few recent papers.","ml-foundations/chapters/16-reading-papers.html","mlf","A1"],["LLM judge","A language model prompted to grade another system's output against a written criterion.","evals/chapters/00-start-here.html","evl",""],["Local competition","Letting each candidate compete on fitness only against candidates with similar behaviour, so many different kinds of good solution survive.","open-ended/chapters/03-novelty-search.html","oe",""],["Locality-sensitive hashing","Splitting signatures into bands and bucketing by band so that only likely near-duplicates are ever compared with each other.","llm-training/chapters/01-pretraining-data.html","llm",""],["Local mirror","A copy of the packages and files a run needs, fetched before the run so the sandbox needs no network at run time.","control/chapters/02-egress-sandbox.html","ctl","A3"],["Local optimum","A candidate that is better than all of its neighbours but worse than the best candidate overall.","open-ended/chapters/03-novelty-search.html","oe",""],["Lock file","A file recording the exact version of every installed package, including indirect dependencies, so an environment can be rebuilt identically.","ml-foundations/chapters/04-reproducible-experiments.html","mlf","A1"],["Log-derivative trick","The identity that the gradient of a probability equals the probability times the gradient of its log, which turns a sum over outcomes into an expectation that sampling can estimate.","llm-training/chapters/07-policy-gradients.html","llm",""],["Logit","An unnormalised score for one vocabulary entry, which a softmax turns into a probability.","deep-learning/chapters/10-transformer-block.html","dl",""],["Logit","The raw real-valued score a model outputs before a sigmoid or softmax turns it into a probability.","ml-foundations/chapters/13-likelihood-losses.html","mlf",""],["Logit distillation","Distillation in which the student minimises a divergence from the teacher's next-token distribution at every position of the training text.","llm-training/chapters/15-distillation.html","llm",""],["Logits","The raw scores produced by a network's last layer, before softmax turns them into probabilities.","deep-learning/chapters/01-neurons-layers.html","dl",""],["Log-sum-exp","The function ln of the sum of exponentials, computed stably by subtracting the maximum before exponentiating.","ml-foundations/chapters/11-numerics.html","mlf",""],["Long-context stuffing","Putting the whole corpus, or a large slice of it, into the prompt and letting the model find what it needs without an index.","agents/chapters/12-long-context.html","agt",""],["LongMemEval","A 2024 benchmark of 500 questions over long chat histories testing information extraction, multi-session and temporal reasoning, knowledge updates and abstention.","agents/chapters/11-memory.html","agt","A2"],["LoRA alpha","A constant that scales the adapter's output by alpha divided by the rank, interacting with the learning rate to set the effective step size.","llm-training/chapters/11-lora.html","llm",""],["LoRA (low-rank adaptation)","A fine-tuning method that freezes the pretrained weights and learns the update to each chosen matrix as a product of two thin matrices.","llm-training/chapters/11-lora.html","llm",""],["Loss","A number that scores how wrong a model's predictions are on the data; training tries to make it small.","ml-foundations/chapters/00-start-here.html","mlf",""],["Loss function","A rule that turns how wrong a prediction was into a single number that training tries to reduce.","deep-learning/chapters/00-start-here.html","dl",""],["Loss masking","Excluding some positions, such as padding or the prompt, from the loss by an ignore index, so only the remaining positions contribute.","deep-learning/chapters/14-language-modelling.html","dl","A1"],["Loss masking","Setting the labels of positions that should not be learned, such as the prompt, to an ignore value so they contribute no loss.","llm-training/chapters/10-sft.html","llm",""],["Loss scaling","Multiplying the loss by a constant before the backward pass so that small fp16 gradients do not underflow to zero, then dividing the gradients by it before the update.","deep-learning/chapters/17-training-stability.html","dl","A1"],["Loss scaling","Multiplying the loss by a constant before the backward pass so small float16 gradients do not underflow, then dividing it out afterwards.","ml-foundations/chapters/11-numerics.html","mlf",""],["Loss spike","A sudden large rise in training loss, common in long runs, from which the run may or may not recover.","deep-learning/chapters/17-training-stability.html","dl","A1"],["Loss spike","A sudden jump in training loss, often preceded by a gradient-norm burst, that may or may not recover without rolling back to an earlier checkpoint.","llm-training/chapters/05-long-runs.html","llm","A1"],["Low-rank approximation","Replacing a matrix by a product of thin factors so that it needs far fewer numbers.","ml-foundations/chapters/07-decompositions.html","mlf",""],["LSTM","A recurrent cell with a separate cell state updated additively under learned forget, input and output gates, which lets gradients survive over longer spans.","deep-learning/chapters/08-sequences-rnns.html","dl",""],["Luhn check","A checksum that payment card numbers satisfy, used to discard digit strings that merely look like card numbers.","evals/chapters/15-guardrails.html","evl",""],["Machine epsilon","The gap between 1.0 and the next representable float above it (about 2.2e-16 for doubles), which sets the best relative accuracy.","ml-foundations/chapters/01-python-numerics.html","mlf",""],["Machine learning","Getting a program to improve at a task by fitting a function to examples instead of writing the function by hand.","ml/chapters/00-start-here.html","ml",""],["MAE","Mean absolute error, a regression metric whose best constant prediction is the median.","ml/chapters/02-framing-metrics.html","ml",""],["Main effect","The average change in a score when one factor goes from low to high, averaged over the other factors' levels.","research-eng/chapters/04-ablations-tracking.html","re","A1"],["Mamba","A state-space architecture with input-dependent updates, computed by a hardware-aware parallel scan.","deep-learning/chapters/22-beyond-attention.html","dl",""],["Manager pattern","A multi-agent design in which a central agent calls specialised agents as tools and keeps control of the plan and the final answer.","agents/chapters/14-multi-agent.html","agt",""],["Mantissa","The bits of a floating-point number that hold its significant digits and so set its precision.","deep-learning/chapters/17-training-stability.html","dl","A1"],["Many-shot jailbreaking","A jailbreak that places a long fake dialogue of compliant answers in the prompt before the real request, becoming more effective as the number of examples grows.","evals/chapters/13-prompt-injection.html","evl",""],["MAP-Elites","A quality-diversity algorithm that keeps the best solution found in each cell of a grid over behaviour space and mutates randomly chosen elites.","open-ended/chapters/04-quality-diversity.html","oe","A4"],["Markov decision process","A model of sequential decisions with states, actions, transition probabilities, rewards and a discount factor, where the next state depends only on the current state and action.","llm-training/chapters/06-bandits-mdps.html","llm",""],["Mask","A boolean vector that switches off the lanes of a block that fall past the end of the data.","harness-eng/chapters/04-kernels-for-agents.html","he","A3"],["Master weights","A full-precision fp32 copy of the weights that the optimiser updates, because tiny updates would be rounded away in 16-bit numbers.","deep-learning/chapters/17-training-stability.html","dl","A1"],["Master weights","A 32-bit copy of the weights that receives the updates in mixed-precision training, because bf16 cannot represent small updates.","llm-training/chapters/02-gpu-memory.html","llm","A1"],["Master weights","A float32 copy of the weights that receives the updates, while 16-bit copies are used for the forward and backward passes.","ml-foundations/chapters/11-numerics.html","mlf",""],["Matrix","A rectangular table of numbers with a shape (rows, columns) that also acts as a linear function on vectors.","ml-foundations/chapters/06-matrices.html","mlf",""],["Matrix multiplication","The product AB defined so that (AB)x = A(Bx): composition of linear maps, with entries given by row-column dot products.","ml-foundations/chapters/06-matrices.html","mlf",""],["Matrix-vector product","The vector whose entries are the dot products of each row of the matrix with the input vector.","ml-foundations/chapters/06-matrices.html","mlf",""],["Maximum a posteriori estimate","The parameter value that maximises likelihood times prior, equivalent to adding a regularisation penalty to the loss.","ml-foundations/chapters/13-likelihood-losses.html","mlf",""],["Maximum likelihood","Choosing the weights that make the training text as probable as possible under the model, which is the same as minimising cross-entropy.","deep-learning/chapters/14-language-modelling.html","dl","A1"],["Maximum-likelihood estimate","The parameter value that makes the observed data most probable, found by maximising the log-likelihood.","ml-foundations/chapters/13-likelihood-losses.html","mlf",""],["max_tokens","A required hard cap on how many tokens the model may generate in one response; reaching it truncates the output.","agents/chapters/01-model-apis.html","agt",""],["MCP client","A component inside a host that keeps one connection to one MCP server.","agents/chapters/07-mcp.html","agt",""],["MCP host","The application the user runs, which owns the model conversation, chooses what the model may see and asks the user for approval.","agents/chapters/07-mcp.html","agt",""],["MCP prompt","A reusable message template offered by a server and invoked explicitly by the user, fetched with prompts/get.","agents/chapters/07-mcp.html","agt",""],["MCP resource","Data identified by a URI that a server offers as context, chosen by the host application and fetched with resources/read.","agents/chapters/07-mcp.html","agt",""],["MCP server","A program, local or remote, that exposes tools, resources and prompts over MCP.","agents/chapters/07-mcp.html","agt",""],["MCP tool","A model-controlled function offered by a server, listed with tools/list and run with tools/call.","agents/chapters/07-mcp.html","agt",""],["Memoisation","Remembering the result of a function call so that a repeat call with the same arguments costs nothing, as functools.lru_cache does.","ml-foundations/chapters/20-functions-objects.html","mlf","A1"],["Memory bandwidth","How many bytes per second a processor can read from and write to its main memory.","ml-foundations/chapters/17-compute-costs.html","mlf","A1"],["Memory-bound","Describes an operation whose run time is set by how fast data can be moved, because its arithmetic intensity is below the chip's ridge point.","llm-training/chapters/04-kernels.html","llm","A3"],["Memory-bound","Limited by how fast data can be moved, not by arithmetic, so extra compute capacity would not make it faster.","ml-foundations/chapters/17-compute-costs.html","mlf","A1"],["Memory poisoning","Saving injected or false content into an agent's memory so that it persists and is trusted in later sessions.","agents/chapters/11-memory.html","agt","A2"],["Memory stream","A complete natural-language record of an agent's experiences from which relevant memories are retrieved by recency, importance and relevance.","agents/chapters/11-memory.html","agt","A2"],["Memory tool","A tool whose file commands let a model read and write a memory directory, executed client-side by the application against storage it controls.","agents/chapters/11-memory.html","agt","A2"],["Merge interference","Loss of ability when task vectors are combined because many entries are redundant noise or because different models push the same weight in opposite directions.","llm-training/chapters/16-model-merging.html","llm","A4"],["Merge recipe","The configuration of a merge: which models, which method, and the weights and densities per model or per layer, kept as a versioned file.","llm-training/chapters/16-model-merging.html","llm","A4"],["Merge table","The ordered list of pair merges learned by byte-pair encoding, applied in that order to encode new text.","deep-learning/chapters/13-tokenisation.html","dl","A1"],["Mesa-optimiser","A trained network that itself runs an optimisation, such as gradient descent, inside its forward pass.","deep-learning/chapters/24-learned-optimisers.html","dl","A2 A4"],["Message authentication code (MAC)","A short tag computed from a message and a secret key, which only a holder of the key can produce.","control/chapters/03-attested-results.html","ctl","A3"],["Message authentication code (MAC)","A short tag computed from a message and a secret key that nobody without the key can forge for a changed message.","harness-eng/chapters/03-splits-attestation.html","he","A3"],["Meta agent","The language model, prompted to design other agents, that proposes each new candidate in a search over agent designs.","open-ended/chapters/12-meta-agent-search.html","oe","A2 A4"],["Meta Agent Search","An ADAS algorithm in which a language model repeatedly writes new agents as code, tests them and stores them in an archive that informs the next proposal.","open-ended/chapters/12-meta-agent-search.html","oe","A2 A4"],["Meta-Harness","A system whose proposer reads the code, scores and traces of all earlier candidate harnesses through a file system and writes better ones.","harness-eng/chapters/01-harness-engineering.html","he","A2"],["Meta-learning","Learning to learn: training a system on many tasks so that it learns new tasks of the same kind quickly.","deep-learning/chapters/24-learned-optimisers.html","dl","A2 A4"],["Metamorphic check","A check on a property that must hold when the input is transformed, used when no reference answer exists.","open-ended/chapters/15-evaluator-hacking.html","oe","A3"],["Metamorphic test","A test that checks a relationship between outputs on related inputs, such as unchanged answers under rephrasing.","evals/chapters/02-eval-harnesses.html","evl","A3"],["Metaproductivity-Performance Mismatch","The gap between an agent's own benchmark score and how good its descendants turn out to be.","rsi-measurement/chapters/05-reading-pack.html","rsi","A4"],["Meta-review","A final step in which the model acts as an area chair and decides on a paper given all of the individual reviews.","open-ended/chapters/14-automated-science.html","oe","A4"],["Meta-scratchpad","A summary, written periodically by a model, of which strategies have worked in recent generations, appended to later mutation prompts.","open-ended/chapters/10-evolution-frameworks.html","oe","A4"],["Meta-utility","The average utility an improver reaches across a set of tasks, used to score the improver itself.","harness-eng/chapters/01-harness-engineering.html","he","A2"],["Meta-utility","The score of an improver: the mean utility of the solutions it produces over a set of training tasks.","open-ended/chapters/21-self-referential-improvers.html","oe","A4"],["MFU","Model FLOPs utilisation: the fraction of a chip's peak FLOP/s that useful model arithmetic actually achieves.","ml-foundations/chapters/17-compute-costs.html","mlf","A1"],["Microbatch","The number of sequences processed in one forward and backward pass, which sets activation memory.","deep-learning/chapters/16-resource-accounting.html","dl","A1"],["Micro-batch","A small slice of a batch processed in one forward and backward pass, used to fill a pipeline or to accumulate gradients.","llm-training/chapters/03-parallelism.html","llm",""],["MicroVM","A lightweight virtual machine with its own guest kernel, such as those run by Firecracker, that boots in well under a second.","agents/chapters/20-sandboxing.html","agt","A2"],["Migration","The periodic exchange of programs between islands so good ideas spread without merging the populations.","open-ended/chapters/10-evolution-frameworks.html","oe","A4"],["MinHash","A way to compress a set into a short signature so that the chance two signature values match equals the sets' Jaccard similarity.","llm-training/chapters/01-pretraining-data.html","llm",""],["Minibatch","A small slice of the training set used for one gradient estimate and one parameter update.","deep-learning/chapters/05-pytorch.html","dl",""],["Minibatch","The small random subset of training examples used to estimate the gradient for one step.","ml-foundations/chapters/10-optimisers.html","mlf",""],["Minimal criterion","A filter that admits a new environment only if the current agent scores neither too low to learn from nor too high to be worth learning.","open-ended/chapters/05-open-ended-algorithms.html","oe","A4"],["Minimal criterion novelty search","Novelty search that only accepts candidates meeting a basic standard of viability.","open-ended/chapters/03-novelty-search.html","oe",""],["Minimum detectable effect","The smallest true difference between two systems that an eval of a given size would detect with a stated power and false-positive rate.","evals/chapters/04-eval-statistics.html","evl","A1 A2 A3"],["Min-p sampling","Sampling only from tokens whose probability is at least a set fraction of the most probable token's, so the cut-off scales with the model's confidence.","deep-learning/chapters/15-decoding.html","dl",""],["MIPROv2","A DSPy optimiser that proposes instructions and chooses demonstrations jointly, using mini-batch scores to guide the search.","open-ended/chapters/11-evolving-prompts.html","oe","A2"],["Mismatched generalisation","A jailbreak failure mode in which a model's capabilities cover inputs, such as rare languages or encodings, that its safety training did not.","evals/chapters/13-prompt-injection.html","evl",""],["Mitigate before diagnosing","The incident rule of doing the safe, reversible thing that stops the harm first and investigating the cause afterwards.","evals/chapters/20-ai-incidents.html","evl",""],["Mixed precision","Training with 16-bit numbers for the bulky matrix products and 32-bit numbers for accumulations such as weights, optimiser state and the loss.","deep-learning/chapters/17-training-stability.html","dl","A1"],["Mixed-precision training","Training with 16-bit or 8-bit arithmetic for most operations while keeping master weights and sensitive accumulations in float32.","ml-foundations/chapters/11-numerics.html","mlf",""],["Mixture of experts","A layer with many parallel expert MLPs in which a router sends each token to only a few of them.","deep-learning/chapters/20-mixture-of-experts.html","dl",""],["MLE-bench","A benchmark of 75 Kaggle competitions on which agents are scored against human leaderboards.","harness-eng/chapters/05-research-benchmarks.html","he","A2"],["MLE-bench Lite","The 22 low-complexity competitions of MLE-bench, about 158 GB of data against 3.3 TB for the full set.","harness-eng/chapters/05-research-benchmarks.html","he","A2"],["MLP sublayer","The position-wise feed-forward network in a block: expand each token vector to about four times its width, apply a nonlinearity, project back.","deep-learning/chapters/10-transformer-block.html","dl",""],["Mode-covering and mode-seeking KL","Forward KL forces the student to put mass wherever the teacher does (mode-covering), while reverse KL lets it commit to one of the teacher's modes (mode-seeking).","llm-training/chapters/15-distillation.html","llm",""],["Model","The function, learned from examples, that maps features to a prediction.","ml/chapters/00-start-here.html","ml",""],["Model capacity","How rich a family of functions a learning algorithm can choose from, such as polynomial degree or tree depth.","ml/chapters/01-generalisation.html","ml",""],["Model collapse","The loss of the rare parts of a distribution when each generation of models is trained only on the previous generation's output.","llm-training/chapters/15-distillation.html","llm",""],["Model Context Protocol (MCP)","An open protocol that lets AI applications discover and use tools, resources and prompts from servers through a common set of JSON-RPC messages.","agents/chapters/07-mcp.html","agt",""],["Model FLOPs utilisation (MFU)","The fraction of a GPU's peak arithmetic speed that a training run converts into useful model FLOPs, typically 30 to 50 per cent in large runs.","deep-learning/chapters/16-resource-accounting.html","dl","A1"],["Model merging","Combining the weights of several models, usually fine-tunes of one base, into a single model by arithmetic on the weights and without gradient training.","llm-training/chapters/16-model-merging.html","llm","A4"],["Model of interestingness","A foundation model used to judge which tasks or states are interesting, standing in for human taste when a system chooses what to explore next.","open-ended/chapters/06-interestingness.html","oe",""],["Model router","A component that sends each request to a model chosen by its estimated difficulty or type.","evals/chapters/19-cost-latency-quality.html","evl",""],["Model soup","The average of the weights of several models fine-tuned from the same pre-trained model, which often beats the best single member at no extra inference cost.","llm-training/chapters/16-model-merging.html","llm","A4"],["Model states","The per-parameter training state that must stay in memory: weights, gradients, a full-precision master copy and the optimiser's running averages.","deep-learning/chapters/16-resource-accounting.html","dl","A1"],["Model states","The weights, gradients and optimiser state of a model, whose total size scales with the number of parameters and not with the batch.","llm-training/chapters/02-gpu-memory.html","llm","A1"],["Module","An object that owns parameters and sub-modules and defines a forward method, so a whole network can be treated as one callable.","deep-learning/chapters/05-pytorch.html","dl",""],["Momentum","An optimiser term that steps along an exponentially weighted average of past gradients, cancelling oscillation and speeding up consistent directions.","ml-foundations/chapters/10-optimisers.html","mlf",""],["Monte Carlo estimation","Estimating an expectation by averaging a function over random samples, with error shrinking as one over the square root of the sample count.","ml-foundations/chapters/12-probability.html","mlf",""],["Monte Carlo return","The actual sum of rewards observed until the end of an episode, an unbiased but high-variance target for a value or advantage.","llm-training/chapters/09-value-functions.html","llm",""],["Monte Carlo tree search (MCTS)","A search that grows a tree by repeating selection, expansion, random simulation and backpropagation, then plays the most-visited move.","open-ended/chapters/01-tree-search.html","oe","A2"],["Multi-agent system","A program with more than one agent loop, each with its own context, in which the output of one agent becomes input to another.","agents/chapters/14-multi-agent.html","agt",""],["Multi-armed bandit","A decision problem with several actions of unknown average reward and no state, where the only difficulty is learning which action is best while using it.","llm-training/chapters/06-bandits-mdps.html","llm",""],["Multi-armed bandit","A repeated choice among options with unknown payouts, where each pull both earns reward and teaches you about that option.","open-ended/chapters/01-tree-search.html","oe","A2"],["Multi-head attention","Running several attention operations in parallel on slices of the model width and combining their outputs with a learned matrix.","deep-learning/chapters/09-attention.html","dl",""],["Multi-hop question","A question whose answer needs a fact found in one document to locate a second fact in another, which single-shot retrieval often misses.","agents/chapters/12-long-context.html","agt",""],["Multiple comparisons","The inflation of false positives that occurs when many slices, metrics or variants are tested and the best-looking one is reported.","evals/chapters/04-eval-statistics.html","evl","A1 A2 A3"],["Multiple comparisons","The accumulation of false-positive chances when many tests are run, corrected by methods such as Bonferroni or Benjamini-Hochberg.","ml-foundations/chapters/15-statistics.html","mlf","A1"],["Multiple comparisons","The problem that testing many candidates makes some look significant by chance alone.","research-eng/chapters/02-proxies-noise.html","re","A1"],["Multi-query attention","Attention with many query heads but a single shared key head and value head, which shrinks the KV cache by the number of heads.","deep-learning/chapters/19-efficient-attention.html","dl","A3"],["Multi round-trip request","The MCP pattern in which a server ends a request with an input_required result and the client retries it with the answers and an echoed requestState.","agents/chapters/08-mcp-production.html","agt",""],["Multi-turn attack","An attack spread over several messages, each looking harmless alone, that escalates by building on the model's earlier replies.","evals/chapters/16-red-teaming.html","evl","A3"],["Mutable surface","The files and settings an agent is permitted to edit, as opposed to the trusted core it must not touch.","open-ended/chapters/17-self-modification-safety.html","oe","A3"],["Mutation-prompt","An instruction that tells a model how to rewrite a task prompt, which can itself be evolved.","open-ended/chapters/11-evolving-prompts.html","oe","A2"],["Mutual information","The KL divergence from a joint distribution to the product of its marginals: the bits of uncertainty about one variable removed by learning the other.","ml-foundations/chapters/14-information-theory.html","mlf",""],["Namespace","A dictionary that maps names to values and decides which names the code run inside it can see.","ml-foundations/chapters/21-programs-as-data.html","mlf","A1"],["Namespacing (tools)","Giving related tools a shared prefix, such as billing_ or crm_, so a model can tell tools from different systems apart as the list grows.","agents/chapters/05-tool-design.html","agt","A2"],["NaN","Not a number: the result of an invalid operation such as 0/0 or inf minus inf, which spreads to every value computed from it.","ml-foundations/chapters/11-numerics.html","mlf",""],["Nat","The unit of information measured with the natural logarithm; one nat is about 1.44 bits.","deep-learning/chapters/14-language-modelling.html","dl","A1"],["Nat","The unit of information when logarithms are natural; one nat is about 1.4427 bits.","ml-foundations/chapters/14-information-theory.html","mlf",""],["Natural language inference","The task of labelling a pair of texts as entailment, contradiction or neutral, used to check whether evidence supports a claim.","evals/chapters/12-fact-checking.html","evl",""],["ndarray","NumPy's n-dimensional array: a flat block of memory plus a header giving dtype, shape, strides and offset.","ml-foundations/chapters/02-numpy-arrays.html","mlf",""],["NEAT","NeuroEvolution of Augmenting Topologies: an algorithm that evolves network structure and weights together, starting from the smallest network.","open-ended/chapters/20-gp-neuroevolution-cmaes.html","oe",""],["Needle-in-a-haystack test","A probe that hides one fact inside long unrelated text and asks the model to recall it, easy to pass and weak evidence of real long-context ability.","agents/chapters/12-long-context.html","agt",""],["Negative log-likelihood","The minus log of the probability a model gave to the observed data, averaged over examples; the standard training loss.","ml-foundations/chapters/13-likelihood-losses.html","mlf",""],["Negative result","A finding that an expected effect did not appear, a check failed or a method did not work, reported as information.","research-eng/chapters/06-write-up.html","re","A1"],["Negative sampling","Training word2vec by telling real (word, context) pairs from randomly drawn noise pairs instead of normalising over the whole vocabulary.","deep-learning/chapters/06-embeddings.html","dl",""],["Nested cross-validation","An outer loop that holds out data and an inner loop that does all model selection on the rest, so the outer score is not flattered by the selection.","ml/chapters/13-cross-validation.html","ml",""],["Network allow-list","A default-deny list of hosts an agent may contact, matched on whole host labels and checked against the resolved address.","agents/chapters/20-sandboxing.html","agt","A2"],["Neuroevolution","Using evolutionary search, instead of gradients, to find the weights, the structure, or both, of a neural network.","open-ended/chapters/20-gp-neuroevolution-cmaes.html","oe",""],["Neuron","A unit that computes a weighted sum of its inputs plus a bias and passes the result through an activation function.","deep-learning/chapters/01-neurons-layers.html","dl",""],["Neutral mutation","A change to a program that alters its code but leaves its score the same.","ml-foundations/chapters/21-programs-as-data.html","mlf","A1"],["Neutral mutation","A change to the genotype that does not change fitness.","open-ended/chapters/19-evolution-for-builders.html","oe","A1"],["Neutral network","A connected set of equally fit genotypes along which a population can wander by neutral mutations.","open-ended/chapters/19-evolution-for-builders.html","oe","A1"],["Next-token prediction","Training a model to give the probability of each possible next token given the tokens before it, which defines a distribution over whole sequences by the chain rule.","deep-learning/chapters/14-language-modelling.html","dl","A1"],["NF4 (4-bit NormalFloat)","A 4-bit number format whose 16 levels are quantiles of a normal distribution, matched to the bell-shaped distribution of pretrained weights.","llm-training/chapters/11-lora.html","llm",""],["N-gram model","A count-based language model that predicts the next token from the previous n minus one tokens using frequencies in the training text.","deep-learning/chapters/14-language-modelling.html","dl","A1"],["n-gram overlap","A contamination check that looks for long runs of consecutive words shared between a test item and training text.","evals/chapters/07-contamination.html","evl","A2 A3"],["N-gram overlap check","A contamination test that flags evaluation items sharing runs of n consecutive words or tokens with the training data.","llm-training/chapters/23-evaluating-models.html","llm",""],["NK landscape","Kauffman's model in which each of N bits contributes to fitness according to its own value and K other bits.","open-ended/chapters/19-evolution-for-builders.html","oe","A1"],["Node (syntax tree)","One part of a syntax tree, such as a name, a number, an operator or a whole function definition.","ml-foundations/chapters/21-programs-as-data.html","mlf","A1"],["No free lunch theorem","The result that, averaged over all possible target functions, every learning algorithm has the same accuracy on unseen inputs.","ml/chapters/01-generalisation.html","ml",""],["Noise floor","The smallest gap between two scores that sampling noise from the test-set size alone cannot explain.","ml-foundations/chapters/16-reading-papers.html","mlf","A1"],["Noise floor","The run-to-run spread of a score when nothing has changed; the smallest improvement that can be told from no change.","research-eng/chapters/02-proxies-noise.html","re","A1"],["Nonce","A value used once per result, so a captured valid message cannot be accepted a second time.","control/chapters/03-attested-results.html","ctl","A3"],["Non-embedding parameters","A model's parameter count without its token and position tables, the N that Kaplan et al. use and that 6ND is most accurate with.","deep-learning/chapters/16-resource-accounting.html","dl","A1"],["Non-goals","Things that could reasonably be goals but are explicitly chosen not to be, which keeps a review within its intended scope.","ml-foundations/chapters/18-technical-writing.html","mlf","A1 A4"],["Norm","The length of a vector; the Euclidean (L2) norm is the square root of the sum of squared components.","ml-foundations/chapters/05-vectors-similarity.html","mlf",""],["Normalisation","Dividing a vector by its norm so that its length becomes 1.","ml-foundations/chapters/05-vectors-similarity.html","mlf",""],["Normalised improvement","An agent's gain over the baseline divided by the range between the best and worst possible scores, floored at zero.","harness-eng/chapters/02-aide-tree-search.html","he","A2"],["Not enough information","The verdict for a claim that the available evidence neither supports nor contradicts.","evals/chapters/12-fact-checking.html","evl",""],["Notes file","A file an agent writes outside its window, such as a progress log, so work can resume after a context reset or in a later session.","agents/chapters/11-memory.html","agt","A2"],["Novelty archive","A growing memory of behaviours that were novel when first found, so the search does not revisit them.","open-ended/chapters/03-novelty-search.html","oe",""],["Novelty bonus (parent selection)","The 1/(1 + children) factor that gives less weight to agents that have already produced many children.","open-ended/chapters/13-self-improving-agents.html","oe","A4"],["Novelty check","A literature search used to discard research ideas that are too similar to existing papers.","open-ended/chapters/14-automated-science.html","oe","A4"],["Novelty gate","A check that rejects a proposed task if it is too similar to tasks already in the archive.","open-ended/chapters/06-interestingness.html","oe",""],["Novelty rejection sampling","Discarding a candidate program before evaluation when its embedding is too similar to programs already in the archive.","open-ended/chapters/10-evolution-frameworks.html","oe","A4"],["Novelty search","A search that selects candidates by how different their behaviour is from others seen so far, rather than by the objective.","open-ended/chapters/03-novelty-search.html","oe",""],["Novelty search with local competition","A quality-diversity method that selects for behavioural novelty while letting each solution compete on fitness only against its behavioural neighbours.","open-ended/chapters/04-quality-diversity.html","oe","A4"],["NULL","SQL's marker for an unknown value, which is not equal to anything, including another NULL, and is skipped by aggregates.","ml-foundations/chapters/03-data-wrangling.html","mlf",""],["Null hypothesis","The default claim of no real difference, whose implied chance behaviour a hypothesis test compares the data against.","ml-foundations/chapters/15-statistics.html","mlf","A1"],["OAuth resource server","The role an MCP server plays in authorisation: it validates access tokens issued by a separate authorisation server and checks their audience and scope.","agents/chapters/08-mcp-production.html","agt",""],["Objective","The number a search tries to improve, used as a stand-in for how close a candidate is to what you actually want.","open-ended/chapters/03-novelty-search.html","oe",""],["Objective hacking","Optimising a measurable objective instead of solving the problem it stands for, as an agent did by deleting the logging its detector read.","control/chapters/03-attested-results.html","ctl","A3"],["Objective hacking","Raising the measured score without solving the underlying problem, for example by disabling the logging a detector depends on.","open-ended/chapters/13-self-improving-agents.html","oe","A4"],["Observability","The ability to answer new questions about a running system from the data it emits, without shipping new code to find out.","evals/chapters/17-observability.html","evl",""],["Observation","The real result of a tool call, appended to the transcript so the model can ground its next thought.","agents/chapters/03-reasoning-planning.html","agt",""],["Offline monitoring","Monitoring that runs after the fact on a stored log, not in the path of each action.","control/chapters/04-transcript-monitor.html","ctl","A3"],["OMNI","Open-endedness via Models of human Notions of Interestingness: a curriculum that combines learning progress with a language model's judgement of which tasks are worth learning.","open-ended/chapters/06-interestingness.html","oe",""],["OMNI-EPIC","An extension of OMNI in which language models also write the code for new environments, rewards and success checks.","open-ended/chapters/06-interestingness.html","oe",""],["One-hot vector","A vector with one entry equal to 1 and all others 0, identifying a single vocabulary item and carrying no notion of similarity.","deep-learning/chapters/06-embeddings.html","dl",""],["Online bin packing","Packing items that arrive one at a time into fixed-size bins, each placed immediately, using as few bins as possible.","open-ended/chapters/09-program-evolution.html","oe","A4"],["Online DPO","DPO in which the preference pairs are generated from the current policy's own samples and labelled by a reward model or judge, instead of coming from a fixed dataset.","llm-training/chapters/12-preference-optimisation.html","llm",""],["Online evaluator","A scorer that runs on sampled production traces to estimate quality continuously.","evals/chapters/17-observability.html","evl",""],["Online softmax","A softmax computed block by block with a running maximum and sum that are rescaled as new blocks arrive, giving the exact result.","deep-learning/chapters/19-efficient-attention.html","dl","A3"],["On-policy","Describes training data generated by the current version of the policy, as policy-gradient estimates require.","llm-training/chapters/07-policy-gradients.html","llm",""],["On-policy distillation","Distillation in which the student generates the text and the teacher scores it, so the student learns on the kind of prefixes it will produce at test time.","llm-training/chapters/15-distillation.html","llm",""],["Opaque agent","A peer agent whose model, prompts, tools and memory are hidden from its caller, which sees only its card, messages, tasks and artifacts.","agents/chapters/09-agent-to-agent.html","agt",""],["Open coding","A first review pass in which the reviewer writes a short free-text note about each trace, without preset categories.","evals/chapters/01-error-analysis.html","evl",""],["Open-ended","Describes a process that keeps producing outputs that are both novel and learnable to an observer, without a fixed end point.","open-ended/chapters/05-open-ended-algorithms.html","oe","A4"],["Open-ended search","Search that keeps producing new and increasingly interesting results instead of converging on a single answer.","open-ended/chapters/00-start-here.html","oe",""],["OpenEvolve","An open-source Python framework that reimplements the AlphaEvolve design with a MAP-Elites grid, islands, evaluator cascades and a weighted model ensemble.","open-ended/chapters/10-evolution-frameworks.html","oe","A4"],["Open relay","A shared host that accepts content from strangers, so allowing it lets an agent read or write data anyone can reach.","control/chapters/02-egress-sandbox.html","ctl","A3"],["OpenTelemetry","The open standard and set of libraries for emitting traces, metrics and logs and sending them to any compatible backend.","evals/chapters/17-observability.html","evl",""],["Operational closure","The share of a capability gain that passes through evaluation, integration and deployment into successor systems.","rsi-measurement/chapters/03-loop-economics.html","rsi","A4"],["Operator table","A dictionary that maps names to functions, such as mutation operators, so a loop can pick one by name and call it.","ml-foundations/chapters/20-functions-objects.html","mlf","A1"],["Opportunity density","A measure of how much improvement a run found per unit of distance travelled in code space; high means small changes pay.","harness-eng/chapters/02-aide-tree-search.html","he","A2"],["OPRO","Optimization by PROmpting: a model is shown earlier candidate prompts with their scores and asked to propose a better one.","open-ended/chapters/11-evolving-prompts.html","oe","A2"],["Optimisation","Search toward a fixed objective, usually stopping when the score stops improving.","open-ended/chapters/00-start-here.html","oe",""],["Optimiser","An object that holds the parameters and turns their gradients into updates when step() is called.","deep-learning/chapters/05-pytorch.html","dl",""],["Optimiser state","The extra values an optimiser stores per weight, such as Adam's two moment estimates and the full-precision master copy of the weights.","llm-training/chapters/02-gpu-memory.html","llm","A1"],["Optimiser state","The extra numbers an optimiser keeps for each parameter, such as Adam's m and v, which add to training memory.","ml-foundations/chapters/10-optimisers.html","mlf",""],["Option (Rust)","A type that is either Some value or None, so that the absence of a value is visible in the type.","research-eng/chapters/05-rust-runner.html","re","A1"],["Orchestrator-workers","A pattern in which a central model call decides the subtasks from the specific input, workers handle them, and a final call synthesises the results.","agents/chapters/13-workflow-patterns.html","agt",""],["Orphan row","A row whose reference to another table (such as a user id) has no matching row there.","ml-foundations/chapters/03-data-wrangling.html","mlf",""],["Orthogonal","Perpendicular: two vectors are orthogonal when their dot product is zero.","ml-foundations/chapters/05-vectors-similarity.html","mlf",""],["Orthogonal matrix","A square matrix whose columns are perpendicular unit vectors, so that Q^T Q = I; it rotates or reflects without stretching.","ml-foundations/chapters/07-decompositions.html","mlf",""],["OSWorld","A benchmark of 369 computer tasks in real operating systems and applications, scored by execution-based scripts that inspect the resulting state.","agents/chapters/17-computer-use.html","agt",""],["Outcome (agent evaluation)","The final state of the environment when a trial ends, such as whether a refund exists in the database.","evals/chapters/08-agent-evals.html","evl","A3"],["Outer loop","The training process that adjusts the learner or optimiser, scoring it on how well an inner run turns out.","deep-learning/chapters/24-learned-optimisers.html","dl","A2 A4"],["Outer loop","An agent or process that rewrites another agent, tests the rewrite and keeps it only if it scores better.","rsi-measurement/chapters/00-start-here.html","rsi","A4"],["Out of memory (OOM)","The error raised when the memory a training step requests at its peak exceeds the GPU's capacity.","llm-training/chapters/02-gpu-memory.html","llm","A1"],["Output check","A guardrail that inspects the model's draft answer before the user sees it.","evals/chapters/15-guardrails.html","evl",""],["Output head","The final linear layer that maps each position's C-vector to one logit per vocabulary entry.","deep-learning/chapters/10-transformer-block.html","dl",""],["OV circuit","The output-value path of an attention head, which sets what the head writes into the residual stream.","deep-learning/chapters/23-interpretability-basics.html","dl","A2"],["Overfitting","Learning the quirks and noise of the training examples so that performance on new data is worse than on the training set.","deep-learning/chapters/04-deep-regularisation.html","dl",""],["Overfitting","Fitting the quirks and noise of the training sample so closely that error on new data is much higher than error on training data.","ml/chapters/01-generalisation.html","ml",""],["Overfitting one batch","A debugging test: train on a single small batch and confirm the loss falls to nearly zero, which shows the whole pipeline can learn.","deep-learning/chapters/12-building-gpt.html","dl","A1"],["Overflow","A result larger than the format's maximum, which becomes infinity (or NaN in fp8 E4M3).","ml-foundations/chapters/11-numerics.html","mlf",""],["Over-refusal","Blocking or refusing a legitimate request because it resembles a prohibited one.","evals/chapters/15-guardrails.html","evl",""],["Overtraining","Training a model on more tokens than the compute-optimal amount, accepting inefficient training in return for a smaller and cheaper model to serve.","deep-learning/chapters/18-scaling-laws.html","dl","A1"],["Ownership (Rust)","The rule that every value has exactly one owner and is freed when the owner goes out of scope.","research-eng/chapters/05-rust-runner.html","re","A1"],["Packing","Concatenating several short training examples into one fixed-length row to avoid padding, which requires attention that does not cross example boundaries.","llm-training/chapters/10-sft.html","llm",""],["Padding","Adding a border of zeros around the input so that edge pixels are covered as often as central ones and the output keeps its size.","deep-learning/chapters/07-convolutions.html","dl",""],["Padding mask","A mask that stops queries attending to the dummy tokens used to pad short sequences to a common batch length.","deep-learning/chapters/09-attention.html","dl",""],["Paged optimiser","Optimiser state held in memory that can move between GPU and CPU on demand, so a short memory spike does not crash a run.","llm-training/chapters/11-lora.html","llm",""],["Paired bootstrap","Resampling evaluation items with both models' outcomes kept together to get an interval for the difference in their scores.","llm-training/chapters/23-evaluating-models.html","llm",""],["Paired bootstrap","A bootstrap that resamples whole questions so each keeps both systems' results together, giving a tighter interval for the difference.","ml-foundations/chapters/15-statistics.html","mlf","A1"],["Paired bootstrap","Resampling test items together for two systems so that shared item difficulty cancels and the interval for their difference narrows.","open-ended/chapters/16-held-out-evaluation.html","oe","A2 A3"],["Paired comparison","Running the same test cases through two versions and comparing them case by case, which detects small differences far better than comparing two totals.","agents/chapters/04-prompting.html","agt","A2"],["Paired comparison","A comparison of two methods on the same tasks and seeds, using the per-task differences.","harness-eng/chapters/02-aide-tree-search.html","he","A2"],["Paired difference","The per-question difference between two systems' scores on the same questions, used so shared difficulty cancels out of the comparison.","evals/chapters/04-eval-statistics.html","evl","A1 A2 A3"],["Paired test","A comparison that subtracts the two arms seed by seed, removing the luck they share, and tests the differences.","research-eng/chapters/02-proxies-noise.html","re","A1"],["Paired t statistic","The mean of the per-task differences between two arms divided by its standard error.","rsi-measurement/chapters/01-level-one.html","rsi","A4"],["Pairwise accuracy","The fraction of held-out preference pairs on which a reward model scores the chosen response above the rejected one, capped by label noise.","llm-training/chapters/13-reward-models.html","llm","A3"],["Pairwise comparison","A judgement in which a judge sees two answers to the same question and says which is better.","evals/chapters/03-llm-judges.html","evl","A2 A3"],["PaperBench","A benchmark in which agents replicate 20 ICML 2024 papers from scratch, graded by rubrics and an LLM judge.","harness-eng/chapters/05-research-benchmarks.html","he","A2"],["Parallel block","A block variant that computes attention and the MLP from the same normalised input and adds both outputs to the stream.","deep-learning/chapters/10-transformer-block.html","dl",""],["Parallel scan","An algorithm that computes a linear recurrence over a whole sequence in parallel instead of one step at a time.","deep-learning/chapters/22-beyond-attention.html","dl",""],["Parallel tool calls","Several tool_use blocks in one assistant turn, all of which must be answered together in the next user message.","agents/chapters/02-tool-loop.html","agt","A2"],["Parameter","An adjustable number inside a model, also called a weight, set during training.","deep-learning/chapters/00-start-here.html","dl",""],["Parameter-efficient fine-tuning (PEFT)","The family of methods, including LoRA, adapters and prompt tuning, that adapt a model by training only a small number of added or selected parameters.","llm-training/chapters/11-lora.html","llm",""],["Parameters","The adjustable numbers inside a model that training changes to reduce the loss.","ml-foundations/chapters/00-start-here.html","mlf",""],["Parametric loss fit","The model L(N, D) = E + A/N^a + B/D^b fitted to training runs, with an irreducible term, a capacity term and a data term.","deep-learning/chapters/18-scaling-laws.html","dl","A1"],["Parent sampling","The rule that chooses which stored program a new mutation starts from, balancing fitness against how much that program has already been tried.","open-ended/chapters/10-evolution-frameworks.html","oe","A4"],["Parent selection","The random choice of which archived agent to modify next, weighted by a sigmoid of its score times 1/(1 + number of its children).","open-ended/chapters/13-self-improving-agents.html","oe","A4"],["Pareto front","The set of configurations that no other configuration beats on every axis at once, such as quality, cost and latency.","evals/chapters/19-cost-latency-quality.html","evl",""],["Parsimony pressure","A penalty on program size added to the score, so that padding is not free.","open-ended/chapters/20-gp-neuroevolution-cmaes.html","oe",""],["Parsing","Turning source text into a syntax tree, which in Python is done by ast.parse.","ml-foundations/chapters/21-programs-as-data.html","mlf","A1"],["Partial derivative","The derivative of a function of several variables with respect to one of them, holding the others fixed.","ml-foundations/chapters/08-derivatives.html","mlf",""],["pass@k","The chance that at least one of k attempts at a task succeeds, a measure of capability that rises with k.","evals/chapters/08-agent-evals.html","evl","A3"],["pass^k","The chance that all k attempts at a task succeed, a measure of reliability that falls as k grows.","evals/chapters/08-agent-evals.html","evl","A3"],["Pass@k","The probability that at least one of k sampled answers to a problem is correct, a measure of what a model can do given several attempts.","llm-training/chapters/14-rlvr-grpo.html","llm","A2 A4"],["pass@k","The chance that at least one of k samples for a problem is correct, usually estimated from a larger batch of samples with an unbiased formula.","open-ended/chapters/08-inference-time-search.html","oe","A2"],["Patch","A small non-overlapping square of an image, typically 14 or 16 pixels wide, flattened and embedded as one token.","deep-learning/chapters/21-vision-language.html","dl",""],["Patience","The number of evaluations without improvement that early stopping tolerates before it ends the run.","deep-learning/chapters/04-deep-regularisation.html","dl",""],["Peak throughput","The most floating-point operations per second a chip could perform if every arithmetic unit were busy, as quoted on its datasheet.","deep-learning/chapters/16-resource-accounting.html","dl","A1"],["Peak-to-average ratio","How much busier the busiest period is than the average, which sets how many GPUs must be provisioned.","llm-training/chapters/22-token-economics.html","llm","A1"],["Peeking","Checking a running experiment repeatedly and stopping at the first significant result, which inflates the false-positive rate well above the nominal level.","ml-foundations/chapters/15-statistics.html","mlf","A1"],["Perception gap","The difference between how much faster people feel an AI tool makes them and the change in their measured task time, as seen in METR's 2025 trial.","agents/chapters/22-ai-coding-tools.html","agt",""],["Permission","A rule in the agent harness that allows, asks about or denies a given tool call before it runs.","agents/chapters/20-sandboxing.html","agt","A2"],["Permutation equivariance","The property that reordering the input tokens reorders the outputs in the same way, which pure self-attention has because it ignores token indices.","deep-learning/chapters/11-positions.html","dl",""],["Permutation test","A hypothesis test that shuffles group labels many times to build the null distribution of a statistic without any formula.","ml-foundations/chapters/15-statistics.html","mlf","A1"],["Perplexity","The exponential of the average loss in nats: the number of equally likely options the model is, on average, as unsure among.","deep-learning/chapters/14-language-modelling.html","dl","A1"],["Perplexity","Two raised to the cross-entropy in bits: the effective number of equally likely choices per token.","ml-foundations/chapters/14-information-theory.html","mlf",""],["Personal data","Any information relating to an identified or identifiable person, including data that is only linked to someone through other records.","evals/chapters/22-privacy-data.html","evl",""],["Personally identifiable information (PII)","Data that identifies a person or can be linked to one, such as names, email addresses, phone numbers and card numbers.","evals/chapters/15-guardrails.html","evl",""],["Person-time weighting","Weighting each task by the hours people spend on it, so large tasks count for more than small ones.","rsi-measurement/chapters/02-automation-levels.html","rsi","A4"],["Phenotype","The form a genotype builds and that the world judges, such as an organism's body or a program's behaviour.","open-ended/chapters/19-evolution-for-builders.html","oe","A1"],["Picbreeder","A website where people evolve images by choosing the ones they find interesting, used to study how discoveries arise without a fixed goal.","open-ended/chapters/03-novelty-search.html","oe",""],["PII","Personally identifiable information, the US term for data that identifies a person, usually narrower than the GDPR's personal data.","evals/chapters/22-privacy-data.html","evl",""],["Pinball loss","An asymmetric absolute-error loss whose minimiser is a chosen quantile of the outcome distribution.","ml/chapters/02-framing-metrics.html","ml",""],["Pipeline bubble","The idle time of pipeline stages at the start and end of a step, equal to (p-1)/(m+p-1) of the schedule for p stages and m micro-batches.","llm-training/chapters/03-parallelism.html","llm",""],["Pipeline parallelism","Splitting a model's layers into consecutive stages on different GPUs and streaming micro-batches through them.","llm-training/chapters/03-parallelism.html","llm",""],["Plan mode","A coding-agent mode in which the agent may read and search but not change anything, so exploration and planning cannot damage the repository.","agents/chapters/22-ai-coding-tools.html","agt",""],["Planner","The model call that turns a goal into an explicit list of steps before any step is executed.","agents/chapters/03-reasoning-planning.html","agt",""],["Plan-then-execute","An agent design in which a planner first writes an explicit list of steps and an executor then carries them out, with a bounded replan on failure.","agents/chapters/03-reasoning-planning.html","agt",""],["Plan-then-execute","A pattern in which the agent fixes its sequence of tool calls before reading any untrusted data.","evals/chapters/14-architectural-defences.html","evl",""],["Playbook","A short document written in advance that says which action to take when a given trigger occurs, and who or what takes it.","control/chapters/05-incident-playbook.html","ctl","A3"],["μP (maximal update parametrisation)","A rule for scaling initial values and learning rates with width so that updates change each layer's output by a width-independent amount.","research-eng/chapters/03-scaling-mup.html","re","A1"],["POET","Paired Open-Ended Trailblazer: an algorithm that evolves a population of environments together with the agents that solve them, and transfers agents between environments.","open-ended/chapters/05-open-ended-algorithms.html","oe","A4"],["Pointwise mutual information","The log of how much more often two words occur together than they would if they were unrelated.","deep-learning/chapters/06-embeddings.html","dl",""],["Poison step","A step that crashes the process every time it runs, so a resuming agent loops on it unless attempts are counted and limited.","agents/chapters/15-durable-execution.html","agt",""],["Poka-yoke","Mistake-proofing: designing an interface, for example with enums and bounded types, so that the wrong call is hard or impossible to write.","agents/chapters/05-tool-design.html","agt","A2"],["Policy gate","Deterministic code between the model's proposed action and the real mouse and keyboard that allows, requires confirmation for, or denies the action.","agents/chapters/17-computer-use.html","agt",""],["Policy gradient","The gradient of expected reward with respect to a policy's parameters, estimable from samples as the reward-weighted gradient of log-probabilities.","llm-training/chapters/07-policy-gradients.html","llm",""],["Policy (reinforcement learning)","The rule an agent uses to choose actions, written as a probability distribution over actions given the current state.","llm-training/chapters/06-bandits-mdps.html","llm",""],["Polyglot benchmark","The Aider team's benchmark of programming exercises across several languages, used to test coding agents.","open-ended/chapters/13-self-improving-agents.html","oe","A4"],["Polysemantic neuron","A neuron that responds to several unrelated features, a common result of superposition.","deep-learning/chapters/23-interpretability-basics.html","dl","A2"],["Pooling","Turning a transformer's per-token outputs into one vector per text, by taking the first token, averaging, or taking the last token.","agents/chapters/23-dense-retrieval.html","agt","A2"],["Pooling","Replacing each small window of a feature map by a single summary value such as its maximum or mean.","deep-learning/chapters/07-convolutions.html","dl",""],["Population-based training","Training many models in parallel while copying strong workers over weak ones and perturbing hyperparameters during the run.","open-ended/chapters/22-coevolution-pbt.html","oe","A4"],["Positional encoding","Information added to a Transformer so that it can tell where in the sequence each token sits.","deep-learning/chapters/11-positions.html","dl",""],["Position bias","A judge's tendency to prefer the answer shown first or second regardless of content.","evals/chapters/03-llm-judges.html","evl","A2 A3"],["Position interpolation","Extending a RoPE model's context by scaling positions down into the range seen in training and then fine-tuning briefly.","deep-learning/chapters/11-positions.html","dl",""],["Position-wise","Applied to each token position separately with the same weights, so it cannot move information between positions.","deep-learning/chapters/10-transformer-block.html","dl",""],["Postcondition check","Verifying after an action that the screen shows the state the action should have produced, rather than trusting the harness's report that the event was delivered.","agents/chapters/17-computer-use.html","agt",""],["Post-norm","Normalising after the residual addition, LN(x + F(x)), as in the original Transformer.","deep-learning/chapters/03-training-dynamics.html","dl","A1"],["Post-training","All training after pretraining, including supervised fine-tuning, preference learning, reinforcement learning and distillation.","llm-training/chapters/00-start-here.html","llm",""],["Power iteration","Repeatedly multiplying a vector by a matrix and renormalising, which converges to the top eigenvector.","ml-foundations/chapters/07-decompositions.html","mlf",""],["Power law","A relationship y = a x^b, which is a straight line on log-log axes and changes y by a fixed factor for each fixed factor in x.","deep-learning/chapters/18-scaling-laws.html","dl","A1"],["PPO clip","PPO's objective min(rA, clip(r, 1-eps, 1+eps)A), which stops a token earning more credit once its probability has moved eps in the helpful direction.","llm-training/chapters/08-ppo.html","llm",""],["Pre-activation","The weighted sum plus bias of a neuron before the activation function is applied, usually written z.","deep-learning/chapters/01-neurons-layers.html","dl",""],["Precision","Of the cases the model flagged as positive, the fraction that really are positive.","ml/chapters/02-framing-metrics.html","ml",""],["Precision at k","The fraction of positives among the k highest-scored cases, matching decisions limited by review capacity.","ml/chapters/02-framing-metrics.html","ml",""],["Predict, ask, read, verify, explain back","A five-step routine for using an assistant to learn: forecast the answer, ask why, read every line, check independently, then explain it without help.","ml-foundations/chapters/19-ai-assistants.html","mlf",""],["Prediction task","A precise statement of what is predicted, for which unit, at what time, from which features, and for which decision.","ml/chapters/02-framing-metrics.html","ml",""],["Preference optimisation","The family of methods, including RLHF, DPO and their relatives, that tune a model towards responses people prefer using comparisons rather than demonstrations.","llm-training/chapters/12-preference-optimisation.html","llm",""],["Preference pair","A prompt together with a chosen (preferred) response and a rejected response, the basic unit of data for preference optimisation.","llm-training/chapters/12-preference-optimisation.html","llm",""],["Prefill","The phase in which a model processes the whole prompt before producing its first output token, whose time grows with prompt length.","agents/chapters/12-long-context.html","agt",""],["Prefill","The first phase of serving, in which the whole prompt is processed in one parallel pass before any token is generated.","deep-learning/chapters/19-efficient-attention.html","dl","A3"],["Premature convergence","A population settling on a mediocre solution because it lost its diversity before finding better regions.","open-ended/chapters/02-evolutionary-algorithms.html","oe","A1 A4"],["Pre-norm","Placing normalisation inside the residual branch, x + F(LN(x)), so the skip path stays clean.","deep-learning/chapters/03-training-dynamics.html","dl","A1"],["Preprocessing leakage","Leakage from a learned step such as scaling, imputation or feature selection being fitted on validation rows before the split.","ml/chapters/14-leakage.html","ml",""],["Pre-tokenisation","Splitting text into words, numbers and punctuation with a regular expression before merging, so that tokens do not cross those boundaries.","deep-learning/chapters/13-tokenisation.html","dl","A1"],["Pretraining","The first and most expensive training stage, in which a model learns to predict the next token over trillions of tokens of text.","llm-training/chapters/00-start-here.html","llm",""],["Principal","Any actor the system accounts for separately, such as a user account, a process or a service with its own credentials.","control/chapters/01-threat-model.html","ctl","A3"],["Principal","A party in a system that acts independently and has its own goals and powers, such as the proposer and the evaluator.","harness-eng/chapters/03-splits-attestation.html","he","A3"],["Principal component analysis","Finding the orthogonal directions of greatest variance in data as the eigenvectors of its covariance matrix.","ml-foundations/chapters/07-decompositions.html","mlf",""],["Prior","A probability distribution over parameters expressing belief before seeing data; a Gaussian prior gives L2 regularisation.","ml-foundations/chapters/13-likelihood-losses.html","mlf",""],["Prior and posterior","The prior is belief about a hypothesis before seeing evidence; the posterior is the updated belief afterwards.","ml-foundations/chapters/12-probability.html","mlf",""],["Private split","The part of a task's cases that only the evaluator sees and that decides what is kept.","harness-eng/chapters/03-splits-attestation.html","he","A3"],["Private split","Data or tasks the proposer never sees and that never decide what is kept, used to measure the real gain.","rsi-measurement/chapters/01-level-one.html","rsi","A4"],["Probability density function","A curve whose area over an interval is the probability that a continuous variable lands in it; its height is probability per unit, so it can exceed 1.","ml-foundations/chapters/12-probability.html","mlf",""],["Probability ratio","The new policy's probability of a sampled token divided by the old policy's, used to reweight old samples and equal to 1 when nothing has changed.","llm-training/chapters/08-ppo.html","llm",""],["Procedural memory","Stored knowledge of how to do recurring jobs, implemented in agents as skills, checklists or scripts.","agents/chapters/11-memory.html","agt","A2"],["Process reward model","A reward model that scores each step of a reasoning chain rather than only the final answer, giving denser but costlier supervision.","llm-training/chapters/13-reward-models.html","llm","A3"],["Process reward model","A model that scores each intermediate step of a reasoning chain rather than only the final answer.","open-ended/chapters/08-inference-time-search.html","oe","A2"],["Product of elasticities","The multiplier around a feedback loop; gains compound when it exceeds 1 and fade when it is below 1.","rsi-measurement/chapters/03-loop-economics.html","rsi","A4"],["program.md","The plain-English instruction file that tells the agent how to set up and run the experiment loop.","research-eng/chapters/01-research-loop.html","re","A1"],["Program search","Search in which the candidates are programs, scored by running them, so that the result is a procedure rather than a single answer.","open-ended/chapters/09-program-evolution.html","oe","A4"],["Program signature","The tuple of scores a program obtains on a set of test inputs, used to cluster programs that behave alike.","open-ended/chapters/09-program-evolution.html","oe","A4"],["Program (Triton)","One copy of a Triton kernel, identified by its program id, that processes one block of the data.","harness-eng/chapters/04-kernels-for-agents.html","he","A3"],["Progressive disclosure","Letting an agent discover context step by step, with each retrieved piece guiding what to look at next, so the window holds only what was chosen.","agents/chapters/10-context-engineering.html","agt","A2"],["Projection","The part of a vector that lies along a given direction, found by scaling that direction by (x . w)/(w . w).","ml-foundations/chapters/05-vectors-similarity.html","mlf",""],["Projector","A linear layer or small MLP that maps image-encoder features to the language model's embedding width.","deep-learning/chapters/21-vision-language.html","dl",""],["Prompt","The text, including instructions, examples and input, that a model is given to complete; in practice a program written in natural language.","agents/chapters/04-prompting.html","agt","A2"],["Promptbreeder","A prompt-evolution method that also evolves the mutation-prompts that rewrite the task prompts.","open-ended/chapters/11-evolving-prompts.html","oe","A2"],["Prompt caching","Storing the processed form of a repeated prompt prefix so later calls read it at a reduced price and latency.","agents/chapters/02-tool-loop.html","agt","A2"],["Prompt caching","Provider-side reuse of the model's computation on the start of a prompt, so a repeated prefix is read at a discount.","evals/chapters/19-cost-latency-quality.html","evl",""],["Prompt chaining","Splitting a task into a fixed sequence of model calls in which each call processes the previous one's output, trading latency for accuracy.","agents/chapters/13-workflow-patterns.html","agt",""],["Prompt injection","Text in a model's input that is meant to be data but is obeyed as instructions, causing behaviour the operator or user did not intend.","agents/chapters/19-agent-security.html","agt","A3"],["Prompt injection","Text that makes a model follow instructions from an untrusted source instead of, or alongside, the instructions of the application's developer.","evals/chapters/13-prompt-injection.html","evl",""],["Prompt leaking","Extracting the hidden system prompt or other instructions a developer gave the model.","evals/chapters/13-prompt-injection.html","evl",""],["Prompt optimisation","Searching over the text of prompts, and the examples included in them, to maximise a metric measured on a development set.","open-ended/chapters/11-evolving-prompts.html","oe","A2"],["Prompt template","A reviewed prompt text with named placeholders that are filled, with escaping, by the data of each request.","agents/chapters/04-prompting.html","agt","A2"],["Prompt test set","A table of inputs, expected results and checks used to compare prompt versions and catch regressions after a prompt or model change.","agents/chapters/04-prompting.html","agt","A2"],["Prompt versioning","Keeping prompts in version control with an identifier logged on every request, so any output can be traced to the exact prompt that produced it.","agents/chapters/04-prompting.html","agt","A2"],["Proof searcher","The part of a Gödel machine that looks for a formal proof that a particular self-rewrite will help.","open-ended/chapters/21-self-referential-improvers.html","oe","A4"],["Proper scoring rule","A loss whose expected value is minimised only when the model reports the true probabilities, so it rewards calibration.","ml-foundations/chapters/13-likelihood-losses.html","mlf",""],["Proposer","The agent in a research loop that writes candidate changes; it is the least trusted principal.","control/chapters/01-threat-model.html","ctl","A3"],["Proposer","The part of a search loop that makes a changed copy of a candidate, such as a random mutation or a language model's edit.","open-ended/chapters/00-start-here.html","oe",""],["Protected resource metadata","A document (RFC 9728) that an MCP server publishes to name the authorisation servers able to issue tokens for it.","agents/chapters/08-mcp-production.html","agt",""],["Protocol (AI control)","A pipeline that combines an untrusted model, a trusted model and limited human review to produce safe output.","control/chapters/01-threat-model.html","ctl","A3"],["Provenance","Metadata recording where a value came from and which other values it was derived from.","evals/chapters/14-architectural-defences.html","evl",""],["Provider and deployer","The EU AI Act roles of the party that develops and places an AI system on the market and the party that uses it professionally under its own authority.","evals/chapters/21-governance.html","evl",""],["Provider-neutral adapter","A thin layer that converts one internal message and tool format to and from each model API's wire format, keeping the agent loop independent of the provider.","agents/chapters/06-function-calling.html","agt",""],["Proxy","A measurable stand-in for the outcome you actually want, such as test pass rate standing in for correctness.","open-ended/chapters/15-evaluator-hacking.html","oe","A3"],["Proxy","A cheap measurement that stands in for the thing you care about, such as a five-minute training score standing in for a long run.","research-eng/chapters/00-start-here.html","re","A1"],["Proxy gap","The difference between a change's gain on the proxy score and its gain on held-out data.","research-eng/chapters/02-proxies-noise.html","re","A1"],["Proxy label","A measurable stand-in used as the target when the quantity you care about cannot be observed, which carries its own flaws into the model.","ml/chapters/02-framing-metrics.html","ml",""],["Proxy reward and gold reward","The proxy is the learned reward the optimiser sees; the gold reward is the trusted ground-truth measure used to check what optimisation actually achieved.","llm-training/chapters/13-reward-models.html","llm","A3"],["Pseudonymisation","Replacing each personal value with a consistent placeholder while keeping the mapping separately so it can be reversed.","evals/chapters/15-guardrails.html","evl",""],["Pseudorandom number generator","A deterministic procedure that turns a seed into a long sequence of numbers that behave like random ones.","ml-foundations/chapters/04-reproducible-experiments.html","mlf","A1"],["Public split","The part of a task's cases that the proposer may see and run against freely.","harness-eng/chapters/03-splits-attestation.html","he","A3"],["PUCT","The AlphaZero selection rule, which scales the exploration bonus by the network's prior probability for each move.","open-ended/chapters/01-tree-search.html","oe","A2"],["Purpose limitation","The principle that data collected for one purpose should not be reused for an incompatible one.","evals/chapters/22-privacy-data.html","evl",""],["Push notification (A2A)","A webhook call that an A2A server makes to a client-registered URL when a long-running task changes, sparing the client from polling.","agents/chapters/09-agent-to-agent.html","agt",""],["p-value","The probability, if the null hypothesis were true, of a result at least as extreme as the one observed; it is not the probability that the null is true.","ml-foundations/chapters/15-statistics.html","mlf","A1"],["QDAIF","Quality-Diversity through AI Feedback: a method where a language model proposes variations and judges quality and diversity of the candidates.","open-ended/chapters/04-quality-diversity.html","oe","A4"],["QD-score","The sum of the qualities of all elites in an archive, which rises when cells are filled or improved.","open-ended/chapters/04-quality-diversity.html","oe","A4"],["QK-normalisation","Applying a normalisation to queries and keys before their dot product, which stops attention logits growing without bound.","deep-learning/chapters/17-training-stability.html","dl","A1"],["QLoRA","LoRA training on top of a frozen base model stored in 4-bit NormalFloat, with double quantisation and paged optimisers to cut memory.","llm-training/chapters/11-lora.html","llm",""],["Quality classifier","A small model trained to score how closely a document resembles a reference set of good text, used to keep the highest-scoring pages.","llm-training/chapters/01-pretraining-data.html","llm",""],["Quality-diversity","A family of search algorithms that return many different solutions, each as good as possible for its kind of behaviour, instead of one best solution.","open-ended/chapters/04-quality-diversity.html","oe","A4"],["Query (attention)","The vector a position uses to ask which other positions are relevant to it.","deep-learning/chapters/09-attention.html","dl",""],["Querying Transformer","BLIP-2's small bottleneck in which a fixed set of learned queries attends to the image, giving a fixed number of image tokens.","deep-learning/chapters/21-vision-language.html","dl",""],["Quote verification","Checking in code that a quoted string really appears in the fetched source text, which catches fabricated citations but not misattributed ones.","agents/chapters/16-deep-research.html","agt",""],["R1-Zero","DeepSeek's reasoning model trained by applying GRPO with rule-based accuracy and format rewards directly to a base model, with no supervised fine-tuning stage.","llm-training/chapters/14-rlvr-grpo.html","llm","A2 A4"],["Randomised controlled trial (productivity)","A study that assigns each task at random to allow or disallow a tool, so that differences in time can be attributed to the tool rather than to who chose it.","agents/chapters/22-ai-coding-tools.html","agt",""],["Random variable","A number whose value depends on the outcome of a chance process, such as the sum of two dice or the next token id.","ml-foundations/chapters/12-probability.html","mlf",""],["Rank","The number of linearly independent columns of a matrix, equal to its number of non-zero singular values.","ml-foundations/chapters/07-decompositions.html","mlf",""],["Rank (LoRA)","The inner dimension r of the two LoRA factors, which sets how many independent directions the update can use and how many parameters it costs.","llm-training/chapters/11-lora.html","llm",""],["Rank range","The span of positions a model occupies across bootstrap resamples of the votes, showing how firmly its rank is established.","evals/chapters/09-leaderboards.html","evl",""],["Rate cap","A ceiling on consumption per unit time, which reacts to fast growth sooner than a cap on the total.","control/chapters/05-incident-playbook.html","ctl","A3"],["ReAct","A pattern that alternates a model's reasoning (thought), a tool request (action) and the real tool output (observation) in a loop.","agents/chapters/03-reasoning-planning.html","agt",""],["Reasoning model","A model trained, typically with reinforcement learning on checkable outcomes, to produce a long internal chain of thought before its final reply.","agents/chapters/03-reasoning-planning.html","agt",""],["Reasoning model","A model trained, largely by reinforcement learning on checkable problems, to produce long intermediate reasoning before its final answer.","llm-training/chapters/00-start-here.html","llm",""],["RE-Bench","A set of seven open-ended research-engineering environments with human expert baselines at fixed time budgets.","harness-eng/chapters/05-research-benchmarks.html","he","A2"],["RE-Bench scaling-law task","A METR task that asks for the best model shape at 5e17 FLOPs using only experiments of 1e16 FLOPs or less.","research-eng/chapters/03-scaling-mup.html","re","A1"],["Recall","Of the cases that really are positive, the fraction the model flagged; also called sensitivity or true positive rate.","ml/chapters/02-framing-metrics.html","ml",""],["Receptive field","The region of the input that can influence one unit's value, which grows as layers are stacked.","deep-learning/chapters/07-convolutions.html","dl",""],["Reconstruction training (hypernetwork)","Training a hypernetwork to reproduce adapters that were already trained on known tasks, a form of distillation from adapters into a generator.","llm-training/chapters/17-adapters-on-demand.html","llm",""],["Recurrence rate","The share of reviewed failures that belong to a failure mode already covered by a test case.","evals/chapters/18-improvement-flywheel.html","evl",""],["Recurrent form","Computing a layer one token at a time with a fixed-size state, which is how linear attention and state-space layers generate text.","deep-learning/chapters/22-beyond-attention.html","dl",""],["Recurrent network","A network that reads a sequence one element at a time and carries a hidden summary forward, which makes it inherently sequential.","deep-learning/chapters/00-start-here.html","dl",""],["Recurrent neural network","A network that reads a sequence one step at a time, applying the same cell at every step and carrying a hidden state forward.","deep-learning/chapters/08-sequences-rnns.html","dl",""],["Recursive gain","The strength of the feedback from AI capability to later research productivity when downstream use is unconstrained.","rsi-measurement/chapters/03-loop-economics.html","rsi","A4"],["Recursive reproduction number","Burtsev's R_AI: the realised feedback gain divided by frontier hardness, where above 1 improvements compound and below 1 they fade.","rsi-measurement/chapters/03-loop-economics.html","rsi","A4"],["Recursive self-improvement","The idea that a system whose gains make it better at producing further gains could compound, which every published system bounds by its search space, judge, budget and frozen model.","open-ended/chapters/21-self-referential-improvers.html","oe","A4"],["Redaction","Removing information that could carry a collusion signal from what the monitor sees.","control/chapters/04-transcript-monitor.html","ctl","A3"],["Redaction","Removing a sensitive value from text and leaving only a label, such as [EMAIL_1].","evals/chapters/22-privacy-data.html","evl",""],["Red Queen effect","The pattern in which coevolving lineages keep changing without either gaining a lasting advantage.","open-ended/chapters/19-evolution-for-builders.html","oe","A1"],["Red Queen Gödel Machine","A self-improving framework in which learned evaluators change alongside the agents they judge.","rsi-measurement/chapters/05-reading-pack.html","rsi","A4"],["Red team","A group that plays the adversary against a system, trying on purpose to make it fail so the failures can be fixed first.","evals/chapters/16-red-teaming.html","evl","A3"],["Reduce-scatter","A collective that sums tensors across GPUs but leaves each GPU holding only its own slice of the result.","llm-training/chapters/03-parallelism.html","llm",""],["Reduction","An operation such as sum, mean or max that collapses one or more axes of an array into single values.","ml-foundations/chapters/02-numpy-arrays.html","mlf",""],["Reference policy","A frozen copy of the model a run started from, usually the SFT model, against which the tuned policy's drift is measured and penalised.","llm-training/chapters/08-ppo.html","llm",""],["Reflection","Evaluating an attempt, turning the verdict into feedback and trying again, which helps most when the feedback comes from tests or validators rather than the model's own opinion.","agents/chapters/03-reasoning-planning.html","agt",""],["Reflection (agent memory)","Periodically synthesising stored memories into higher-level summaries that are stored and retrieved like any other memory.","agents/chapters/11-memory.html","agt","A2"],["Regression gate","A release rule that blocks a change if a case that passed before now fails.","evals/chapters/02-eval-harnesses.html","evl","A3"],["Regression (quality)","A behaviour that used to be correct and is now wrong after a change.","evals/chapters/18-improvement-flywheel.html","evl",""],["Regression suite","A set of tests, often built from past failures, that fails if an old problem returns.","evals/chapters/00-start-here.html","evl",""],["Regression suite (model)","A fixed set of evaluations of capabilities to keep, run on every new version of a model to catch unintended losses.","llm-training/chapters/23-evaluating-models.html","llm",""],["Regret","The reward an agent would have earned by always choosing the best action, minus the reward it actually earned.","llm-training/chapters/06-bandits-mdps.html","llm",""],["Regret","The reward lost compared with always choosing the best option, summed over all the choices made.","open-ended/chapters/01-tree-search.html","oe","A2"],["Regularisation","Any change to a learning procedure that gives up a little training accuracy in return for better accuracy on unseen data.","deep-learning/chapters/04-deep-regularisation.html","dl",""],["REINFORCE","The basic policy-gradient algorithm: sample trajectories, score them, and move the policy along the log-probability gradient weighted by reward.","llm-training/chapters/07-policy-gradients.html","llm",""],["Relative position bias","A learned number per head and distance bucket added to the attention scores so they depend on how far apart two tokens are.","deep-learning/chapters/11-positions.html","dl",""],["Release gate","An automatic check, usually in continuous integration, that blocks a change when the suite shows it got worse by a rule fixed in advance.","evals/chapters/18-improvement-flywheel.html","evl",""],["Reliability diagram","A plot of stated confidence against observed accuracy in bins, where the diagonal means perfect calibration.","evals/chapters/11-grounding-abstention.html","evl",""],["ReLU","The activation max(0, z), which passes positive values unchanged and sets negative values to zero.","deep-learning/chapters/01-neurons-layers.html","dl",""],["Repeated k-fold","Running k-fold several times with different shuffles and pooling the scores to reduce the luck of one partition.","ml/chapters/13-cross-validation.html","ml",""],["Repetition loop","A degenerate output where the model repeats the same phrase indefinitely because repeated text makes more repetition likely.","deep-learning/chapters/15-decoding.html","dl",""],["Repetition penalty","A decoding adjustment that lowers the logits of tokens already generated, to reduce loops.","deep-learning/chapters/15-decoding.html","dl",""],["Replay","Sending an old valid message again in the hope that it is accepted as new.","control/chapters/03-attested-results.html","ctl","A3"],["Replay","Mixing a share of earlier training data into a new fine-tuning set to keep the old skills from degrading.","llm-training/chapters/10-sft.html","llm",""],["Replication","Testing the same finding with new data or a fresh implementation, which checks the finding rather than the reporting.","ml-foundations/chapters/16-reading-papers.html","mlf","A1"],["Repository map","A compact summary of a repository's files and key signatures, sent with requests so the model knows what exists before searching.","agents/chapters/18-coding-agents.html","agt","A2"],["Reproducible","Of a result, able to be regenerated from its record, exactly or within a stated tolerance.","ml-foundations/chapters/04-reproducible-experiments.html","mlf","A1"],["Reproduction","Rerunning the authors' own code and data to see whether you obtain their reported numbers.","ml-foundations/chapters/16-reading-papers.html","mlf","A1"],["Reproduction command","A single command that regenerates the headline figure from the stored records.","research-eng/chapters/06-write-up.html","re","A1"],["requestState","An opaque server-minted string that a client echoes on a retry; because it crosses an untrusted client it must be integrity-protected and bound to user, request and expiry.","agents/chapters/08-mcp-production.html","agt",""],["Request tap","A thin wrapper around the model interface that records each request exactly as it leaves your process, showing what a framework really sends.","agents/chapters/21-frameworks.html","agt",""],["Resampling (answers per question)","Answering each question K times and averaging, which shrinks answer-level noise by a factor of K but not the noise from choosing questions.","evals/chapters/04-eval-statistics.html","evl","A1 A2 A3"],["Research loop","A repeated cycle of proposing a change, measuring it and keeping or discarding it, run without a human between iterations.","research-eng/chapters/01-research-loop.html","re","A1"],["Residual","What is left of a vector after subtracting its projection; it is orthogonal to the direction projected onto.","ml-foundations/chapters/05-vectors-similarity.html","mlf",""],["Residual connection","A skip path that adds a layer's input to its output, y = x + F(x), giving gradients a direct route backwards.","deep-learning/chapters/03-training-dynamics.html","dl","A1"],["Residual stream","The running sum of a Transformer's block outputs, which every block reads from and writes to.","deep-learning/chapters/03-training-dynamics.html","dl","A1"],["Resource indicator","The resource parameter (RFC 8707) by which a client names the MCP server a token is for, so the token is bound to that audience.","agents/chapters/08-mcp-production.html","agt",""],["Resource limit","A cap on CPU time, memory or file size that the operating system enforces on a process.","ml-foundations/chapters/22-running-candidates.html","mlf","A1"],["Resource limit","A cap on CPU time, wall-clock time, memory, disk or processes that a sandbox enforces on running code.","open-ended/chapters/17-self-modification-safety.html","oe","A3"],["Response format argument","A tool parameter, such as a concise or detailed enum, that lets the agent choose how much detail a result contains.","agents/chapters/05-tool-design.html","agt","A2"],["Result (Rust)","A type that is either Ok with a value or Err with an error, so that failure is visible in the type.","research-eng/chapters/05-rust-runner.html","re","A1"],["results.tsv","The tab-separated log of the loop with one row per run: commit, val_bpb, memory, status and description.","research-eng/chapters/01-research-loop.html","re","A1"],["Retrieval-augmented generation (RAG)","Searching an index first and putting only the most relevant chunks into the prompt so the model answers from them.","agents/chapters/12-long-context.html","agt",""],["Return (reinforcement learning)","The sum of future rewards from a time step, each multiplied by the discount factor raised to its delay.","llm-training/chapters/06-bandits-mdps.html","llm",""],["Reverse-mode autodiff","Differentiation that propagates gradients from the output back to the inputs, giving the effect of all inputs on one output per pass.","ml-foundations/chapters/09-autodiff.html","mlf",""],["Reverse-mode automatic differentiation","Differentiating by one backward sweep over the graph, giving the gradient with respect to every input at a small multiple of the forward cost.","deep-learning/chapters/05-pytorch.html","dl",""],["Reward","A number the environment returns after an action, scoring how good it was; reinforcement learning tries to maximise its accumulated total.","llm-training/chapters/06-bandits-mdps.html","llm",""],["Reward hacking","Raising the measured reward without doing what the designer meant, which needs only a loose score and search pressure.","control/chapters/01-threat-model.html","ctl","A3"],["Reward hacking","A policy earning a high score from its reward signal by exploiting flaws in the signal, without doing what the signal was meant to measure.","llm-training/chapters/13-reward-models.html","llm","A3"],["Reward hacking","Raising a proxy reward in a way that lowers the true reward, usually by exploiting a flaw in how it is computed.","open-ended/chapters/15-evaluator-hacking.html","oe","A3"],["Reward hacking rate","The share of outputs that score well by exploiting the evaluator instead of doing the task.","rsi-measurement/chapters/04-reading-claims.html","rsi","A4"],["Reward model","A network that reads a prompt and a response and outputs one number predicting how much people would prefer it, trained on comparisons.","llm-training/chapters/12-preference-optimisation.html","llm",""],["Reward model ensemble","Several reward models trained separately whose disagreement or worst-case score is used to make optimisation more conservative.","llm-training/chapters/13-reward-models.html","llm","A3"],["Reward over-optimisation","The effect where pushing a policy to maximise a learned reward raises the reward score while true quality peaks and then declines.","llm-training/chapters/08-ppo.html","llm",""],["Reward-to-go","The sum of rewards from a given step onwards, used to weight that step's log-probability gradient because earlier rewards cannot depend on it.","llm-training/chapters/07-policy-gradients.html","llm",""],["Ridge point","The arithmetic intensity at which a chip's peak FLOP/s and peak memory bandwidth are equally limiting, about 295 FLOP per byte for an H100 in bf16.","llm-training/chapters/04-kernels.html","llm","A3"],["Ridge point","The arithmetic intensity at which the memory roof meets the compute roof, equal to peak FLOP/s divided by bandwidth.","ml-foundations/chapters/17-compute-costs.html","mlf","A1"],["Ridge regression","Least squares with an L2 penalty on the weights, equal to the MAP estimate under Gaussian noise and a Gaussian prior with lambda = sigma^2 / tau^2.","ml-foundations/chapters/13-likelihood-losses.html","mlf",""],["Right altitude (prompting)","Writing instructions specific enough to guide behaviour but flexible enough to give the model heuristics, avoiding both brittle if-then rules and vague guidance.","agents/chapters/10-context-engineering.html","agt","A2"],["Right to erasure","A person's right under the GDPR to have their personal data deleted, subject to exceptions such as legal claims.","evals/chapters/22-privacy-data.html","evl",""],["Risk-coverage curve","A plot of selective risk against coverage as the confidence threshold is lowered, showing the price of answering more questions.","evals/chapters/11-grounding-abstention.html","evl",""],["RLHF (reinforcement learning from human feedback)","A three-stage method that fine-tunes a model on demonstrations, trains a reward model on human comparisons, then optimises the model against that reward with a KL penalty.","llm-training/chapters/12-preference-optimisation.html","llm",""],["RLVR (reinforcement learning with verifiable rewards)","Reinforcement learning in which the reward is computed by a program that checks the answer, such as an answer match or unit tests, instead of by a learned reward model.","llm-training/chapters/14-rlvr-grpo.html","llm","A2 A4"],["RMSE","Root mean squared error, a regression metric in the units of the target whose best constant prediction is the mean.","ml/chapters/02-framing-metrics.html","ml",""],["RMSNorm","A cheaper normalisation that divides by the root mean square of the features and does not subtract the mean.","deep-learning/chapters/03-training-dynamics.html","dl","A1"],["ROC AUC","The probability that a random positive case scores higher than a random negative case, summarising ranking quality across all thresholds.","ml/chapters/02-framing-metrics.html","ml",""],["Rogan-Gladen correction","An estimate of the true pass rate from a judge's observed rate and its true positive and negative rates.","evals/chapters/03-llm-judges.html","evl","A2 A3"],["Role","The label on a message saying who spoke, normally user (everything coming in) or assistant (what the model said).","agents/chapters/01-model-apis.html","agt",""],["Rollback","Returning a run to a trusted checkpoint by appending a rollback entry, so the earlier entries stay as evidence.","control/chapters/05-incident-playbook.html","ctl","A3"],["Rolling buffer cache","A KV cache of fixed size W that overwrites slot position mod W, valid because tokens older than the window are never read again.","deep-learning/chapters/19-efficient-attention.html","dl","A3"],["Rollout","A fast simulation from a tree leaf to the end of the game, used to estimate how good the leaf is.","open-ended/chapters/01-tree-search.html","oe","A2"],["Roofline model","A plot of achievable FLOP/s against arithmetic intensity, bounded by a memory-bandwidth slope and a flat compute ceiling.","llm-training/chapters/04-kernels.html","llm","A3"],["Roofline model","A chart of attainable FLOP/s against arithmetic intensity, bounded by a sloped memory roof and a flat compute roof.","ml-foundations/chapters/17-compute-costs.html","mlf","A1"],["RoPE base","The constant (10,000 in the original paper) that sets the spread of rotation frequencies across dimension pairs and hence the longest wavelength.","deep-learning/chapters/11-positions.html","dl",""],["Rotary position embedding (RoPE)","A scheme that rotates each pair of query and key dimensions by an angle proportional to position, so that attention scores depend only on the distance between tokens.","deep-learning/chapters/11-positions.html","dl",""],["Router","The small linear layer that scores every expert for a token and selects the top k.","deep-learning/chapters/20-mixture-of-experts.html","dl",""],["Routing","Classifying an input and sending it down a specialised path, with its own prompt, tools or model, plus a fallback for low confidence.","agents/chapters/13-workflow-patterns.html","agt",""],["Routing collapse","A failure in which a few experts receive nearly all tokens and the rest are rarely trained or used.","deep-learning/chapters/20-mixture-of-experts.html","dl",""],["Row-major order","A memory layout in which the last axis varies fastest, so each row of a matrix is contiguous; also called C order.","ml-foundations/chapters/02-numpy-arrays.html","mlf",""],["Rubric","The written definition of a criterion, including what counts as PASS and FAIL, that a judge applies.","evals/chapters/03-llm-judges.html","evl","A2 A3"],["Rug pull","A tool server changing a tool's definition after the user approved it, so earlier approval no longer reflects what the model sees.","agents/chapters/19-agent-security.html","agt","A3"],["Rule of three","After zero successes in n independent trials, the 95% upper bound on the success rate is about 3 divided by n.","evals/chapters/16-red-teaming.html","evl","A3"],["Rules of engagement","The agreed limits of a red-team exercise: what is in scope, what is off limits and when to stop and report.","evals/chapters/16-red-teaming.html","evl","A3"],["Runner","The program that starts an experiment, enforces its deadline, reads its score and decides keep, discard or crash.","research-eng/chapters/05-rust-runner.html","re","A1"],["Run store","A table with one row per run holding its configuration, seed, code version, environment and results.","research-eng/chapters/04-ablations-tracking.html","re","A1"],["Runtime","The part of a framework that executes a loop or graph of steps and keeps its state, as opposed to only calling a model API.","agents/chapters/21-frameworks.html","agt",""],["Safeguard model","A language model fine-tuned to classify prompts and responses against a list of safety categories, such as Llama Guard.","evals/chapters/15-guardrails.html","evl",""],["Safety (AI control)","The probability that no attack succeeds over a whole run when the untrusted model plays the red team's best attack.","control/chapters/04-transcript-monitor.html","ctl","A3"],["Sample efficiency","How much improvement a search obtains per model call or evaluation spent, which depends on what is counted as a sample.","open-ended/chapters/10-evolution-frameworks.html","oe","A4"],["Sample ratio mismatch","A split of users between experiment arms that differs from the planned ratio by more than chance allows, signalling broken assignment or logging.","ml-foundations/chapters/15-statistics.html","mlf","A1"],["Sampling weight","The inverse of the probability that a trace was kept, used to compute unbiased rates from a non-uniform sample.","evals/chapters/17-observability.html","evl",""],["Sandbox","An enforced boundary, applied by the operating system, a hypervisor or a proxy, around running code that limits what it can reach.","agents/chapters/20-sandboxing.html","agt","A2"],["Saturation","The flat ends of an activation such as sigmoid or tanh, where the slope is near zero and gradients cannot pass.","deep-learning/chapters/01-neurons-layers.html","dl",""],["Saturation","The state in which the best systems score so close to a benchmark's ceiling that differences among them are smaller than its noise.","evals/chapters/07-contamination.html","evl","A2 A3"],["Scaffold (leaderboard context)","The prompts, tools, loop and limits wrapped around a model, which belong to the score of an agent benchmark as much as the model does.","evals/chapters/09-leaderboards.html","evl",""],["Scaled dot-product attention","The function softmax(QK^T / sqrt(d_k)) V, where the scaling keeps the score variance at one whatever the key width.","deep-learning/chapters/09-attention.html","dl",""],["Scaling law","An empirical power-law relationship between a model's loss and its parameters, training data or compute, which lets small runs predict larger ones.","deep-learning/chapters/18-scaling-laws.html","dl","A1"],["Scaling law","A fitted formula giving a model's loss as a function of its parameters and training tokens.","research-eng/chapters/03-scaling-mup.html","re","A1"],["Score function","The gradient of the log-probability of an action with respect to the policy parameters; for a softmax over logits it is the one-hot vector of the action minus the probabilities.","llm-training/chapters/07-policy-gradients.html","llm",""],["Score oracle","A scorer that can be queried freely, so that repeated queries leak information about the hidden cases.","harness-eng/chapters/03-splits-attestation.html","he","A3"],["Scorer","Code or a model that decides whether an attack attempt reached its goal, preferably by checking observable effects.","evals/chapters/16-red-teaming.html","evl","A3"],["Scratchpad","Text the model writes inside its own window, such as a plan or to-do list, to organise a long task; it disappears with the window.","agents/chapters/11-memory.html","agt","A2"],["Scripted model","A stand-in model that replays replies written in advance so that example code and lab checks run offline with identical output every time.","agents/chapters/00-start-here.html","agt",""],["Search-and-replace edit","An edit expressed as exact old text and new text, which fails loudly if the old text is missing or appears more than once.","agents/chapters/18-coding-agents.html","agt","A2"],["Search (as a method)","Finding a good answer by generating candidates, testing them and using the results to choose the next candidates, instead of computing the answer directly.","open-ended/chapters/00-start-here.html","oe",""],["Search policy","The rule that chooses which node to extend next; in AIDE it drafts, then debugs buggy leaves with some probability, otherwise improves the best node.","harness-eng/chapters/02-aide-tree-search.html","he","A2"],["Search set","The data a search loop scores candidates on to choose parents; its scores are optimistic for the survivors.","open-ended/chapters/16-held-out-evaluation.html","oe","A2 A3"],["Search set versus held-out test set","The data an optimiser is allowed to score candidates on, kept separate from the data used once at the end to report the final result, because search overfits its own score.","llm-training/chapters/16-model-merging.html","llm","A4"],["Search space (agent design)","The set of agents a method can represent at all, which limits the best possible result before any search begins.","open-ended/chapters/12-meta-agent-search.html","oe","A2 A4"],["Seatbelt and bubblewrap","The macOS and Linux operating-system facilities used to start a process with file-system and network restrictions it cannot lift.","agents/chapters/20-sandboxing.html","agt","A2"],["Sectioning","A parallelisation variant in which independent subtasks of one job run at the same time and their results are combined in code.","agents/chapters/13-workflow-patterns.html","agt",""],["Security policy (agent)","A rule written in code that allows, denies or asks a person about a tool call, given its arguments and their provenance.","evals/chapters/14-architectural-defences.html","evl",""],["Seed","The starting value of a pseudorandom number generator; the same seed gives the same sequence.","ml-foundations/chapters/04-reproducible-experiments.html","mlf","A1"],["Seed","An integer that fixes a program's pseudo-random draws, so that a run can be repeated exactly.","research-eng/chapters/02-proxies-noise.html","re","A1"],["Seed improver","The starting improver in STOP: it asks a language model for several candidate improvements and returns the one with the best utility.","open-ended/chapters/21-self-referential-improvers.html","oe","A4"],["Selection","The bias by which some individuals leave more offspring than others, so their traits become more common.","open-ended/chapters/19-evolution-for-builders.html","oe","A1"],["Selection bias","The optimism in the best of many noisy validation scores, caused by choosing the winner on the same rows used to score it.","ml/chapters/13-cross-validation.html","ml",""],["Selection bias (winner's curse)","The optimism that comes from reporting the best score among many noisy candidates on the same data.","ml/chapters/01-generalisation.html","ml",""],["Selection pressure","How strongly an evolutionary algorithm favours the fittest individuals when choosing parents.","open-ended/chapters/02-evolutionary-algorithms.html","oe","A1 A4"],["Selection set","Fresh data used to choose among a small shortlist of finalists.","open-ended/chapters/16-held-out-evaluation.html","oe","A2 A3"],["Selective disclosure","Testing many private variants and publishing only the best result, which inflates the published score without any dishonest measurement.","evals/chapters/09-leaderboards.html","evl",""],["Selective recomputation","Recomputing only the memory-heavy but cheap parts of a layer, such as attention scores, instead of the whole layer.","llm-training/chapters/02-gpu-memory.html","llm","A1"],["Selective risk","The error rate among only the questions a system answers, ignoring those it declines.","evals/chapters/11-grounding-abstention.html","evl",""],["Selectivity","Making a state-space layer's update depend on the current input, so it can choose what to write into its state and what to ignore.","deep-learning/chapters/22-beyond-attention.html","dl",""],["Self-adaptive model","A model that changes part of its own weights at inference time in response to the task it is given, without a new training run.","llm-training/chapters/17-adapters-on-demand.html","llm",""],["Self-attention","Attention in which the queries, keys and values are all computed from the same sequence.","deep-learning/chapters/09-attention.html","dl",""],["Self-consistency","Sampling several reasoning paths and returning the most common final answer.","open-ended/chapters/08-inference-time-search.html","oe","A2"],["Self-enhancement bias","A judge's tendency to prefer answers written by itself or by a model of its own family.","evals/chapters/03-llm-judges.html","evl","A2 A3"],["Self-improvement claim","A claim that a system improved its own ability to improve, which needs a successor that is a better improver.","rsi-measurement/chapters/04-reading-claims.html","rsi","A4"],["Self-modification","An agent editing its own code (tools, prompts, workflow) to produce a new version of itself, with the underlying model's weights left unchanged.","open-ended/chapters/13-self-improving-agents.html","oe","A4"],["Self-modifying system","A loop in which a candidate's output includes changes to code, prompts or settings that run in the next iteration.","open-ended/chapters/17-self-modification-safety.html","oe","A3"],["Self-referential improvement","A process whose improvement step is among the things it improves, such as a search that evolves its own mutation operators.","open-ended/chapters/11-evolving-prompts.html","oe","A2"],["Self-referential improver","An improver that is itself among the things it is allowed to change, and that raises a score of its own performance.","open-ended/chapters/21-self-referential-improvers.html","oe","A4"],["Self-reported figure","A number computed and published by the organisation it describes, without independent verification.","rsi-measurement/chapters/02-automation-levels.html","rsi","A4"],["Self-reported score","A benchmark result measured and published by the model's own developer, usually under settings chosen to suit that model.","evals/chapters/09-leaderboards.html","evl",""],["Self-Route","A hybrid that tries retrieval first and falls back to the long context only when the model judges the retrieved chunks insufficient.","agents/chapters/12-long-context.html","agt",""],["Self-Taught Optimizer (STOP)","A seed improver program that uses a language model to improve code, and is then run on its own code to produce a better improver.","harness-eng/chapters/01-harness-engineering.html","he","A2"],["Self-Taught Optimizer (STOP)","A method from Zelikman and colleagues in which a language-model-based improver rewrites its own code and is scored by its meta-utility on training tasks.","open-ended/chapters/21-self-referential-improvers.html","oe","A4"],["Self-verification","Having a separate model call (a critic) judge whether a task was completed and suggest fixes.","open-ended/chapters/07-lifelong-agents.html","oe","A4"],["Semantic cache","A cache keyed by an embedding of the question that returns an earlier answer to a similar question, with the risk of wrong or leaked answers.","evals/chapters/19-cost-latency-quality.html","evl",""],["Semantic conventions","Agreed names for common telemetry attributes, so that different tools describing the same thing use the same key.","evals/chapters/17-observability.html","evl",""],["Semantic entropy","The entropy of a model's sampled answers after grouping them by meaning, high when the model gives arbitrary, changing answers.","evals/chapters/11-grounding-abstention.html","evl",""],["Semantic memory","Facts that stay true until changed, such as a customer's preferred channel, stored with one current value per fact.","agents/chapters/11-memory.html","agt","A2"],["SentencePiece","A library that trains BPE or unigram tokenisers directly on raw text, treating the space as an ordinary symbol.","deep-learning/chapters/13-tokenisation.html","dl","A1"],["Sentinel value","A special number such as -999 used to mean 'missing' that parses as ordinary data unless it is found and converted.","ml-foundations/chapters/03-data-wrangling.html","mlf",""],["Sequence-level distillation","Distillation by sampling answers from the teacher and fine-tuning the student on that text, which needs no access to the teacher's probabilities.","llm-training/chapters/15-distillation.html","llm",""],["Sequence parallelism","Splitting activations along the sequence dimension in the parts of a layer that tensor parallelism leaves replicated, to save memory without extra traffic.","llm-training/chapters/03-parallelism.html","llm",""],["Serious incident (EU AI Act)","An incident or malfunction of a high-risk AI system that leads to defined kinds of serious harm, which providers must report to authorities within set deadlines.","evals/chapters/20-ai-incidents.html","evl",""],["server/discover","The MCP method, required of every server in the 2026-07-28 revision, that returns the supported protocol versions, capabilities and identity of a server.","agents/chapters/08-mcp-production.html","agt",""],["Server-sent events","A long-lived HTTP response in which the server writes named events as they happen, used to stream model output token by token.","agents/chapters/01-model-apis.html","agt",""],["Set-of-marks","Overlaying numbered marks on the interactive regions of a screenshot so the model answers with a mark number instead of estimating coordinates.","agents/chapters/17-computer-use.html","agt",""],["Shadow mode","Running a candidate on a copy of live traffic and scoring its answers without showing them to users.","evals/chapters/18-improvement-flywheel.html","evl",""],["Shape (array)","The tuple giving the number of elements along each axis of an array, written (rows, columns) for a matrix.","ml-foundations/chapters/02-numpy-arrays.html","mlf",""],["Shape contract","The rule that (m, n) @ (n, p) gives (m, p): the inner sizes must agree and vanish.","ml-foundations/chapters/06-matrices.html","mlf",""],["Sharded checkpoint","A checkpoint in which each rank writes only the part of the state it owns, in parallel, rather than gathering everything to one writer.","llm-training/chapters/05-long-runs.html","llm","A1"],["Shared expert","An expert that every token uses, holding common knowledge so the routed experts can specialise.","deep-learning/chapters/20-mixture-of-experts.html","dl",""],["Shingle","An overlapping run of n consecutive words (or characters) taken from a document so it can be treated as a set for similarity comparison.","llm-training/chapters/01-pretraining-data.html","llm",""],["ShinkaEvolve","An open-source framework that uses language models as mutation operators in evolutionary code search.","control/chapters/00-start-here.html","ctl","A3"],["ShinkaEvolve","Sakana AI's open-source program-evolution framework, built to find good programs with few model calls.","open-ended/chapters/10-evolution-frameworks.html","oe","A4"],["Shortlist","A small set of top candidates re-scored on fresh data before a winner is chosen.","open-ended/chapters/16-held-out-evaluation.html","oe","A2 A3"],["SigLIP","A CLIP variant that replaces the softmax over the batch by an independent sigmoid loss on every image-caption pair.","deep-learning/chapters/21-vision-language.html","dl",""],["Signature","A declaration of what a DSPy module takes in and returns, without the wording of the prompt.","open-ended/chapters/11-evolving-prompts.html","oe","A2"],["Sign-flip test","An exact test that asks how often random sign changes of the observed differences give a mean at least as extreme.","research-eng/chapters/02-proxies-noise.html","re","A1"],["SIGXCPU","The signal sent to a process that exceeds its CPU-time limit; its number is 24 on macOS and Linux.","control/chapters/02-egress-sandbox.html","ctl","A3"],["Silent data corruption","A hardware fault that makes a computation return a wrong value without raising any error.","llm-training/chapters/05-long-runs.html","llm","A1"],["SimpleQA","A short-form factuality benchmark whose answers are graded correct, incorrect or not attempted.","evals/chapters/10-hallucination.html","evl",""],["Simulated user","A model or script that plays the customer in an agent evaluation, following a hidden instruction and replying to the agent.","evals/chapters/08-agent-evals.html","evl","A3"],["Single-column scan","Scoring each feature alone by how well it ranks the target, to find columns that are suspiciously predictive.","ml/chapters/14-leakage.html","ml",""],["Singleton rate","The share of training mentions whose fact appears exactly once, which estimates how much probability lies on facts the model cannot tell from unseen ones.","evals/chapters/10-hallucination.html","evl",""],["Single writer","A design rule in which several agents may contribute research or review but only one agent edits the shared artefact, avoiding conflicting writes.","agents/chapters/14-multi-agent.html","agt",""],["Singular matrix","A square matrix with no inverse because it flattens space and loses information.","ml-foundations/chapters/06-matrices.html","mlf",""],["Singular value decomposition","The factorisation A = U Sigma V^T of any matrix into a rotation, an axis-aligned stretch and another rotation.","ml-foundations/chapters/07-decompositions.html","mlf",""],["Singular-value fine-tuning (SVF)","Adapting a weight matrix by learning one scale per singular value while keeping its singular vectors fixed, which needs far fewer parameters than LoRA.","llm-training/chapters/17-adapters-on-demand.html","llm",""],["Singular values","The non-negative diagonal entries of Sigma in the SVD, which measure how much the matrix stretches along each pair of singular vectors.","ml-foundations/chapters/07-decompositions.html","mlf",""],["Sinusoidal positional encoding","A fixed code made of sines and cosines at geometrically spaced frequencies, so that a shift in position is a rotation of the code.","deep-learning/chapters/11-positions.html","dl",""],["Skill","The ability to produce, debug and explain something without help, which is built by effort rather than by receiving an answer.","ml-foundations/chapters/19-ai-assistants.html","mlf",""],["Skill (A2A)","An entry in an agent card describing one capability of the agent, with an id, description, tags and examples.","agents/chapters/09-agent-to-agent.html","agt",""],["Skill library","A collection of reusable procedures, each described briefly, that an agent loads only when a task calls for them.","agents/chapters/11-memory.html","agt","A2"],["Skill library","A store of verified programs, each indexed by a description, that an agent retrieves and calls when solving new tasks.","open-ended/chapters/07-lifelong-agents.html","oe","A4"],["SKILL.md","The file at the core of an Agent Skill, with YAML front matter giving a name and description followed by the instructions the agent reads when it chooses the skill.","agents/chapters/11-memory.html","agt","A2"],["Skip-gram","The word2vec variant in which the centre word is used to predict each word in its context window.","deep-learning/chapters/06-embeddings.html","dl",""],["SLERP","Spherical linear interpolation: blending two weight tensors along the arc between them so that their norm is not shrunk in the middle.","llm-training/chapters/16-model-merging.html","llm","A4"],["Sliding window","A time-based split that trains on a fixed-length recent stretch of the past instead of all of it.","ml/chapters/13-cross-validation.html","ml",""],["Sliding-window attention","Causal attention in which each token reads only its previous W tokens, so scored pairs grow as T times W instead of T squared.","deep-learning/chapters/19-efficient-attention.html","dl","A3"],["Sliding-window evaluation","Scoring each token with as much context as the model allows by moving a fixed-length window forward in small strides and scoring only its last positions.","deep-learning/chapters/14-language-modelling.html","dl","A1"],["Smoke set","A small, fast subset of the most important test cases, run on every change.","evals/chapters/02-eval-harnesses.html","evl","A3"],["Smoothing","Adding pseudo-counts to observed counts so unseen events get non-zero probability; add-k smoothing is MAP under a Dirichlet prior.","ml-foundations/chapters/13-likelihood-losses.html","mlf",""],["Snapshot","A stored, folded copy of state together with the log position it covers, so recovery replays only the events after it.","agents/chapters/15-durable-execution.html","agt",""],["Softmax","The function that turns a vector of logits into probabilities by exponentiating each entry and dividing by the sum.","deep-learning/chapters/14-language-modelling.html","dl","A1"],["Softmax cross-entropy gradient","The gradient of the loss with respect to the logits, equal to the predicted probabilities minus the one-hot true label.","deep-learning/chapters/02-backpropagation.html","dl",""],["Soft targets","The teacher's full probability distribution over answers, used as a training target in place of a single hard label.","llm-training/chapters/15-distillation.html","llm",""],["Solution tree","The tree whose nodes are candidate scripts with their results and whose edges are attempts to fix or improve them.","harness-eng/chapters/02-aide-tree-search.html","he","A2"],["Solve rate","The share of systems or attempts that get an item right in a pilot run.","evals/chapters/06-building-benchmarks.html","evl","A2"],["Source triage","Deciding which search hits are worth opening by scoring snippets and discounting by source kind, because reading a page costs far more than reading a snippet.","agents/chapters/16-deep-research.html","agt",""],["Span","One timed operation within a trace, with a name, attributes, a parent and a status.","evals/chapters/17-observability.html","evl",""],["Sparse autoencoder","A network trained to rebuild a layer's activations from a wide, mostly zero code, whose decoder directions are candidate features.","deep-learning/chapters/23-interpretability-basics.html","dl","A2"],["Sparse reward","A reward that is zero for most steps and arrives only at the end of an episode, as when a whole response is scored once.","llm-training/chapters/06-bandits-mdps.html","llm",""],["Sparse reward","A reward signal that is zero almost everywhere, so an optimiser gets no feedback until it is already close to success.","open-ended/chapters/05-open-ended-algorithms.html","oe","A4"],["Special token","A reserved vocabulary entry, such as an end-of-text or end-of-turn marker, that carries control meaning rather than text.","deep-learning/chapters/13-tokenisation.html","dl","A1"],["Special tokens","Reserved vocabulary entries that mark structure, such as the start and end of a turn, rather than ordinary text.","llm-training/chapters/10-sft.html","llm",""],["Speciation","Grouping genomes by structural similarity and having them compete mostly within their group, to protect new structure while it is still weak.","open-ended/chapters/20-gp-neuroevolution-cmaes.html","oe",""],["Specification gaming","Behaviour that satisfies the literal specification of an objective without achieving the intended outcome.","open-ended/chapters/15-evaluator-hacking.html","oe","A3"],["Speed-of-light bound","The least possible run time, the larger of the time to do the arithmetic and the time to move the data at the hardware's peak rates.","harness-eng/chapters/04-kernels-for-agents.html","he","A3"],["Spotlighting","Marking untrusted text, for example with delimiters or encoding, so the model can tell which tokens are data.","agents/chapters/19-agent-security.html","agt","A3"],["Spotlighting","Transforming untrusted input so that it carries a signal of its origin, helping a model treat it as data rather than instructions.","evals/chapters/13-prompt-injection.html","evl",""],["Squared error","The loss (y - f)^2, which is the negative log-likelihood of Gaussian noise up to constants.","ml-foundations/chapters/13-likelihood-losses.html","mlf",""],["Stable softmax","Softmax computed after subtracting the largest logit, which gives the same probabilities but cannot overflow.","ml-foundations/chapters/11-numerics.html","mlf",""],["Staged evaluation","Testing a candidate on a few tasks first and spending a larger evaluation budget only on those that clear a bar.","open-ended/chapters/13-self-improving-agents.html","oe","A4"],["Standard error","A measure of how much an estimate, such as an eval score, would vary if the sampling of questions were repeated.","evals/chapters/04-eval-statistics.html","evl","A1 A2 A3"],["Standard error","The standard deviation of an estimate such as a sample mean, equal to sigma divided by the square root of n.","ml-foundations/chapters/12-probability.html","mlf",""],["Standard error","The standard deviation of an estimate such as a mean; it shrinks with the square root of the number of runs.","research-eng/chapters/02-proxies-noise.html","re","A1"],["Standard error over seeds","The spread of a score across repeated runs on the same tasks; it excludes variation from the choice of tasks.","harness-eng/chapters/05-research-benchmarks.html","he","A2"],["Stand-in (for a language model)","A deterministic, seeded function used in a teaching script in place of a language model, so the output is reproducible.","open-ended/chapters/21-self-referential-improvers.html","oe","A4"],["Stand-in model","A deterministic function used in place of a language model so that examples run offline and give the same output every time.","open-ended/chapters/00-start-here.html","oe",""],["State capacity","The limit on how many independent facts a fixed-size state can hold, roughly its number of entries.","deep-learning/chapters/22-beyond-attention.html","dl",""],["state_dict","A plain dictionary from parameter names to tensors, used to save and restore a model.","deep-learning/chapters/05-pytorch.html","dl",""],["State graph","A description of an agent's flow as nodes (steps) and edges (what follows), with a typed state object saved after each node so a run can pause, resume or replay.","agents/chapters/21-frameworks.html","agt",""],["Stateless API","An API that keeps nothing between calls, so a conversation exists only because the client re-sends the whole message list each time.","agents/chapters/01-model-apis.html","agt",""],["Stateless protocol (MCP 2026-07-28)","A design in which every request carries its protocol version and client capabilities, so any server replica can answer it without remembering earlier requests.","agents/chapters/08-mcp-production.html","agt",""],["State machine","A program described by the states it can be in and the events that move it between them.","research-eng/chapters/01-research-loop.html","re","A1"],["Statement of Applicability","A document listing which management-system controls apply to an organisation and why any others are excluded.","evals/chapters/21-governance.html","evl",""],["State space duality","The result that Mamba-style layers and a form of attention are two views of the same structured matrices.","deep-learning/chapters/22-beyond-attention.html","dl",""],["State-space model","A layer that keeps a hidden state updated linearly by each input and reads its output from that state, with constant work per token.","deep-learning/chapters/22-beyond-attention.html","dl",""],["Static embeddings","Word vectors with one fixed vector per word regardless of the sentence it appears in.","deep-learning/chapters/06-embeddings.html","dl",""],["Statistical power","The probability that an eval detects a real difference of a given size.","evals/chapters/04-eval-statistics.html","evl","A1 A2 A3"],["Statistical power","The probability that a test detects an effect of a given size when it is real; sample size scales with one over the effect squared.","ml-foundations/chapters/15-statistics.html","mlf","A1"],["Statistical reproducibility","Producing a rerun result that falls within the normal run-to-run variation, even if it is not identical.","ml-foundations/chapters/04-reproducible-experiments.html","mlf","A1"],["stdio transport","An MCP transport in which the client launches the server as a subprocess and exchanges newline-delimited JSON-RPC messages over its standard input and output.","agents/chapters/07-mcp.html","agt",""],["Stepping stone","An intermediate discovery that is valuable for what it leads to, even though it may score poorly on the final objective.","open-ended/chapters/03-novelty-search.html","oe",""],["Step-up authorisation","Re-authorising with a larger scope set after a server answers 403 insufficient_scope, keeping the scopes already granted.","agents/chapters/08-mcp-production.html","agt",""],["Stochastic gradient descent","Gradient descent that estimates the gradient from a small random minibatch instead of the whole dataset.","ml-foundations/chapters/10-optimisers.html","mlf",""],["Stop condition","A rule enforced by the harness that ends an agent loop, such as an iteration cap, token budget, timeout or repeated-call detection.","agents/chapters/02-tool-loop.html","agt","A2"],["Stop reason","The field in a model response that says why generation ended, such as end_turn, max_tokens, stop_sequence or tool_use.","agents/chapters/01-model-apis.html","agt",""],["Stop sequence","A string that ends generation as soon as the model produces it, useful for preventing the model from inventing text such as a tool result.","agents/chapters/01-model-apis.html","agt",""],["Storage limitation","The principle that personal data should be kept no longer than its purpose requires.","evals/chapters/22-privacy-data.html","evl",""],["Straggler","A working but slow GPU, host or link that sets the pace of a synchronous job because everyone waits for it.","llm-training/chapters/05-long-runs.html","llm","A1"],["Stratified k-fold","A k-fold split that deals each class out separately so every fold has nearly the same class proportions.","ml/chapters/13-cross-validation.html","ml",""],["Streamable HTTP","An MCP transport using a single HTTP endpoint where each client message is a POST and the server replies with JSON or a Server-Sent Events stream.","agents/chapters/07-mcp.html","agt",""],["Stream injection","A timing hack that runs the work on a separate CUDA stream so the timer does not see it.","harness-eng/chapters/04-kernels-for-agents.html","he","A3"],["Strict mode","A provider option that guarantees tool arguments conform to the declared schema, typically requiring closed objects and all fields listed as required.","agents/chapters/06-function-calling.html","agt",""],["Stride","The number of pixels a filter moves between positions, where larger strides give smaller outputs.","deep-learning/chapters/07-convolutions.html","dl",""],["Strides","The number of bytes to step in memory to move one position along each axis of an array.","ml-foundations/chapters/02-numpy-arrays.html","mlf",""],["Structured note-taking","Having the agent write notes such as decisions, open bugs and next steps to storage outside the window and read them back later.","agents/chapters/10-context-engineering.html","agt","A2"],["Structured output","Model output in a machine-readable shape such as JSON matching a schema, obtained by prompting and validating, by a forced tool or by constrained decoding.","agents/chapters/01-model-apis.html","agt",""],["Style control","A regression adjustment for answer length and formatting so that preference ratings reflect substance more than presentation.","evals/chapters/09-leaderboards.html","evl",""],["Sub-agent","An agent loop started by a lead agent for one part of a task, working in its own fresh context and returning a condensed result.","agents/chapters/14-multi-agent.html","agt",""],["Subgradient","A valid slope to use at a kink such as ReLU at zero, where the ordinary derivative does not exist.","ml-foundations/chapters/08-derivatives.html","mlf",""],["Subnormal number","A tiny float below the smallest normal value, stored without the hidden leading 1, giving gradual loss of precision before reaching zero.","ml-foundations/chapters/11-numerics.html","mlf",""],["Sub-question","One independently searchable piece of a research question, produced by the planner so that searches can run in parallel.","agents/chapters/16-deep-research.html","agt",""],["Subsampling","Randomly discarding very frequent words while reading a corpus, which speeds training and improves vectors for rarer words.","deep-learning/chapters/06-embeddings.html","dl",""],["Subspace","A direction, or a few directions, in a vector space; components can use separate subspaces of the residual stream as private channels.","deep-learning/chapters/23-interpretability-basics.html","dl","A2"],["Subtree crossover","Making a child by replacing a random subtree of one parent with a random subtree of another.","open-ended/chapters/20-gp-neuroevolution-cmaes.html","oe",""],["Success detector","A program, often written by a model, that decides whether an agent has completed a generated task.","open-ended/chapters/06-interestingness.html","oe",""],["Superficial alignment hypothesis","The claim, from the LIMA paper, that a model learns nearly all its knowledge in pretraining and that a small instruction set mainly teaches style and format.","llm-training/chapters/10-sft.html","llm",""],["Super-population","The hypothetical, unlimited set of questions from which an eval's questions are treated as a random sample.","evals/chapters/04-eval-statistics.html","evl","A1 A2 A3"],["Superposition","A network storing more sparse features than it has dimensions by packing them into overlapping directions.","deep-learning/chapters/23-interpretability-basics.html","dl","A2"],["Supervised fine-tuning (SFT)","Continuing training on examples of the desired behaviour, such as conversations, using the same next-token loss as pretraining.","llm-training/chapters/00-start-here.html","llm",""],["Supervised learning","Learning a mapping from features to a known label, as in classification and regression.","ml/chapters/00-start-here.html","ml",""],["Supervisor (process)","A program whose job is to start another program, watch it, limit it and report on it.","research-eng/chapters/05-rust-runner.html","re","A1"],["Surprisal","The negative log probability of a token that actually occurred, in bits or nats: how surprised the model was.","deep-learning/chapters/14-language-modelling.html","dl","A1"],["Surprise","The information content of an event, -log p, which is large for rare events and adds across independent ones.","ml-foundations/chapters/14-information-theory.html","mlf",""],["Surrogate objective","A stand-in objective, the ratio times the advantage, that can be optimised on data from an older policy and matches the policy gradient at the starting point.","llm-training/chapters/08-ppo.html","llm",""],["Swap test","Judging each pair in both orders and counting a win only when the verdict agrees across orders.","evals/chapters/03-llm-judges.html","evl","A2 A3"],["SWE-bench","A benchmark of 2,294 real GitHub issues from 12 Python repositories, graded by running the repository's tests on the agent's patch.","agents/chapters/18-coding-agents.html","agt","A2"],["SWE-bench","A benchmark that gives an agent a real GitHub repository and issue and checks whether its patch makes hidden tests pass.","open-ended/chapters/13-self-improving-agents.html","oe","A4"],["SWE-bench Verified","A subset of 500 SWE-bench instances that human developers screened for clear issue descriptions and fair tests.","agents/chapters/18-coding-agents.html","agt","A2"],["SwiGLU","A gated MLP using the SiLU nonlinearity as its gate, with hidden width about 8C/3 to match the parameters of a standard MLP.","deep-learning/chapters/10-transformer-block.html","dl",""],["Sycophancy","A model's tendency to tell users what they want to hear, such as agreeing with their stated opinion or abandoning a correct answer when challenged.","llm-training/chapters/13-reward-models.html","llm","A3"],["Symmetric matrix","A matrix equal to its transpose; it has real eigenvalues and perpendicular eigenvectors.","ml-foundations/chapters/07-decompositions.html","mlf",""],["Synchronous training","Training in which every rank must finish each step's communication before any rank continues, so one failed or slow rank stops or slows the whole job.","llm-training/chapters/05-long-runs.html","llm","A1"],["Syntax tree","The tree of nodes that Python builds from source text, in which each node is a small part of the program and children sit inside their parents.","ml-foundations/chapters/21-programs-as-data.html","mlf","A1"],["Synthetic data","Training data written or labelled by a model instead of a person, whose quality depends on the checks applied to it.","llm-training/chapters/15-distillation.html","llm",""],["System prompt","Standing instructions placed outside the turn-by-turn messages that set the role, rules and style for a whole conversation.","agents/chapters/01-model-apis.html","agt",""],["System prompt for an agent","Standing instructions for an agent loop that state its process, its limits, what to do on repeated failure and the style of its replies.","agents/chapters/04-prompting.html","agt","A2"],["Tail sampling","Deciding whether to keep a trace after it has finished, so rules can use errors, latency, scores and feedback.","evals/chapters/17-observability.html","evl",""],["Tamper-evident log","A log that does not prevent changes but makes them detectable, usually with a hash chain and an anchored head.","control/chapters/03-attested-results.html","ctl","A3"],["Target leakage","Leakage from a feature that is recorded after the outcome, caused by it, or is the label under another name.","ml/chapters/14-leakage.html","ml",""],["Task archive","A store of every task tried, with its description, code and whether it was learned or failed, used to propose and filter new tasks.","open-ended/chapters/06-interestingness.html","oe",""],["Task arithmetic","Adding or subtracting scaled task vectors from a base model to add, combine or remove behaviours.","llm-training/chapters/16-model-merging.html","llm","A4"],["Task inventory","A list of the distinct tasks of a job, rated one by one before any overall share is computed.","rsi-measurement/chapters/02-automation-levels.html","rsi","A4"],["Task specification","A short document defining what a benchmark measures: the input, output, scoring rule, scope and the decision the score feeds.","evals/chapters/06-building-benchmarks.html","evl","A2"],["Task state","The lifecycle position of an A2A task: submitted, working, input-required or auth-required while active, and completed, failed, canceled or rejected once finished.","agents/chapters/09-agent-to-agent.html","agt",""],["Task vector","The difference between a fine-tuned model's weights and the weights of the base it started from, describing everything that fine-tuning changed.","llm-training/chapters/16-model-merging.html","llm","A4"],["tau-bench","A benchmark that grades agents in simulated customer conversations by the database state they leave and reports reliability as pass^k.","evals/chapters/08-agent-evals.html","evl","A3"],["TD error","The critic's surprise at one step: reward plus discounted next value minus the current value, used both to train the critic and as a one-step advantage.","llm-training/chapters/09-value-functions.html","llm",""],["Teacher and student","In distillation, the teacher is the large trained model being imitated and the student is the smaller model being trained.","llm-training/chapters/15-distillation.html","llm",""],["Teacher forcing","Training with the true previous tokens as input at every position, rather than the model's own earlier predictions.","deep-learning/chapters/14-language-modelling.html","dl","A1"],["Technical report","A lab's description of a model or system, usually with less detail about what was tried and discarded than a research paper.","ml-foundations/chapters/16-reading-papers.html","mlf","A1"],["Temperature","A sampling setting that divides the logits before the softmax, so low values concentrate probability on the top token and high values spread it out.","agents/chapters/01-model-apis.html","agt",""],["Temperature","A number that divides the logits before the softmax: below one it sharpens the distribution and above one it flattens it.","deep-learning/chapters/15-decoding.html","dl",""],["Temperature","A divisor applied to logits before the softmax: below 1 sharpens the distribution toward the largest logit, above 1 flattens it.","ml-foundations/chapters/12-probability.html","mlf",""],["Temperature (distillation)","A divisor applied to logits before the softmax; values above 1 flatten the distribution so small probabilities of wrong answers become visible to the loss.","llm-training/chapters/15-distillation.html","llm",""],["Temperature sampling","Choosing each source with probability proportional to its size raised to a power below one, so that small sources are upsampled.","llm-training/chapters/01-pretraining-data.html","llm",""],["Temporal leakage","Leakage from using information dated after the prediction time, for example a rolling window that extends into the future.","ml/chapters/14-leakage.html","ml",""],["Temporal split","Training on data before a date and testing on data after it, to mimic facing the future.","llm-training/chapters/23-evaluating-models.html","llm",""],["Tensor","An n-dimensional array with a shape, a number format (dtype) and a device, which can also record the operations applied to it.","deep-learning/chapters/05-pytorch.html","dl",""],["Tensor core","A GPU unit that multiplies small matrix tiles in one step at low precision, which is why peak throughput is quoted per number format.","ml-foundations/chapters/17-compute-costs.html","mlf","A1"],["Tensor parallelism","Splitting each layer's weight matrices across GPUs so that they compute one layer together, at the cost of all-reduces inside every layer.","llm-training/chapters/03-parallelism.html","llm",""],["Terminal set","The leaves a genetic programming tree may use: the program's inputs and its constants.","open-ended/chapters/20-gp-neuroevolution-cmaes.html","oe",""],["Terminal state","A task state (completed, failed, canceled or rejected) from which an A2A task cannot be restarted; changes are made in a new task in the same context.","agents/chapters/09-agent-to-agent.html","agt",""],["Test case","One input together with the checks or reference answer that define correct behaviour for it.","evals/chapters/02-eval-harnesses.html","evl","A3"],["Test set","Held-out data used once, after all choices are made, to report an honest estimate of generalisation error.","ml/chapters/01-generalisation.html","ml",""],["Test set","Data touched once, after all decisions, to report an unbiased final score.","open-ended/chapters/16-held-out-evaluation.html","oe","A2 A3"],["Test set (versus development set)","The test set is scored rarely and never used to make choices, while the development set is used repeatedly to select checkpoints and settings.","llm-training/chapters/23-evaluating-models.html","llm",""],["Test-time compute","The computation spent when a model answers a query, as opposed to the computation spent training it.","open-ended/chapters/08-inference-time-search.html","oe","A2"],["Text extraction","Pulling the main prose out of a web page's HTML while discarding navigation, adverts and other boilerplate.","llm-training/chapters/01-pretraining-data.html","llm",""],["Text-to-LoRA","A hypernetwork that generates LoRA matrices for a base model in one forward pass from a natural-language description of the task.","llm-training/chapters/17-adapters-on-demand.html","llm",""],["The AI Scientist","A pipeline from Sakana AI and collaborators that proposes machine-learning research ideas, runs the experiments, writes a paper and reviews it automatically.","open-ended/chapters/14-automated-science.html","oe","A4"],["Theoretical saturation","The point at which new traces stop revealing new failure kinds or changing existing categories.","evals/chapters/01-error-analysis.html","evl",""],["Thinking budget","A cap on how many tokens a model may spend reasoning before it answers, trading answer quality against cost and latency.","agents/chapters/03-reasoning-planning.html","agt",""],["Thompson sampling","A bandit strategy that samples a plausible value for each action from its posterior distribution and picks the action with the highest sample.","llm-training/chapters/06-bandits-mdps.html","llm",""],["Thompson sampling","A bandit strategy that samples a plausible payout rate for each option from its posterior belief and picks the highest sample.","open-ended/chapters/01-tree-search.html","oe","A2"],["Threat model","A written account of assets, principals, boundaries, capabilities, attack paths, controls and residual risk.","control/chapters/01-threat-model.html","ctl","A3"],["Three-pass method","Keshav's way of reading a paper in up to three passes (scan, grasp, re-create), stopping as soon as your question is answered.","ml-foundations/chapters/16-reading-papers.html","mlf","A1"],["Throughput (serving)","The total number of tokens a system generates per second across all concurrent requests.","llm-training/chapters/22-token-economics.html","llm","A1"],["Tidy data","A table layout with one variable per column, one observation per row and one table per type of observational unit.","ml-foundations/chapters/03-data-wrangling.html","mlf",""],["TIES-Merging","A merge method that trims small task-vector entries, elects a sign for each weight and averages only the entries that agree with it.","llm-training/chapters/16-model-merging.html","llm","A4"],["Timeout","A limit on how long a parent waits for a child before it gives up and kills it.","ml-foundations/chapters/22-running-candidates.html","mlf","A1"],["Time to first token","The delay between sending a request and receiving the first token of the reply, dominated by reading the prompt.","evals/chapters/19-cost-latency-quality.html","evl",""],["Tokeniser","A fixed program that converts text into a list of integer ids for the model and converts ids back into text.","deep-learning/chapters/13-tokenisation.html","dl","A1"],["Token-mean loss","A batch loss averaged over every unmasked token, so long responses carry more total weight than short ones.","llm-training/chapters/10-sft.html","llm",""],["Tokens per parameter","The ratio of training tokens to parameters, about 20 at the compute-optimal point in the Chinchilla analysis and far higher in models built for cheap serving.","deep-learning/chapters/18-scaling-laws.html","dl","A1"],["Tool","A function the surrounding program offers to a model, which the model can request but never runs itself.","agents/chapters/00-start-here.html","agt",""],["tool_choice","A request setting that lets the model decide on tools (auto), requires some tool, requires a named tool, or forbids tools for a turn.","agents/chapters/06-function-calling.html","agt",""],["Tool definition","The name, plain-language description and JSON Schema of a function that a model may request; the model sees this and never the function's code.","agents/chapters/02-tool-loop.html","agt","A2"],["Tool description","The prose in a tool definition that tells the model what the tool does, when to use it, what its arguments mean and what it does not return.","agents/chapters/05-tool-design.html","agt","A2"],["Tool linter","A script that checks tool definitions for known weaknesses such as thin descriptions, generic argument names and overlapping tools.","agents/chapters/05-tool-design.html","agt","A2"],["Tool poisoning","Hiding malicious instructions in a tool description or result so that the model follows them.","agents/chapters/07-mcp.html","agt",""],["tool_result block","A content block in a user message that answers one tool_use request, matched by tool_use_id and flagged with is_error when the tool failed.","agents/chapters/02-tool-loop.html","agt","A2"],["Tool-result clearing","Replacing old tool outputs in the history with short placeholders while keeping the calls and the model's own messages.","agents/chapters/10-context-engineering.html","agt","A2"],["Tool shadowing","A malicious tool's description altering how the agent uses a different, trusted tool.","agents/chapters/19-agent-security.html","agt","A3"],["tool_use block","A content block in an assistant message in which the model requests a tool by name, with an id and an input object.","agents/chapters/02-tool-loop.html","agt","A2"],["Top-k sampling","Sampling only from the k most probable tokens after renormalising.","deep-learning/chapters/15-decoding.html","dl",""],["Top-p sampling","Sampling only from the smallest set of top tokens whose probabilities add up to p, after renormalising them.","agents/chapters/01-model-apis.html","agt",""],["Top-p sampling","Also called nucleus sampling: sampling only from the smallest set of tokens whose probabilities sum to at least p.","deep-learning/chapters/15-decoding.html","dl",""],["torch.compile","PyTorch 2's compiler entry point, which captures a model as a graph and generates fused kernels, using Triton on GPUs.","llm-training/chapters/04-kernels.html","llm","A3"],["Total evaluator","An evaluation function that returns a score for every input and never raises, turning each crash or invalid candidate into a penalty score.","ml-foundations/chapters/20-functions-objects.html","mlf","A1"],["Total parameters","Every weight in a mixture-of-experts model, counting all experts; this sets the memory needed.","deep-learning/chapters/20-mixture-of-experts.html","dl",""],["Tournament selection","Choosing a parent by drawing k individuals at random and taking the fittest of them.","open-ended/chapters/02-evolutionary-algorithms.html","oe","A1 A4"],["Trace","The full record of one request: input, prompts, model and tool calls, retrieved documents and final output, in order.","evals/chapters/00-start-here.html","evl",""],["Tracer (sys.settrace)","A function the interpreter calls on events such as each new line, which can be used to count the work a program does.","ml-foundations/chapters/21-programs-as-data.html","mlf","A1"],["Training","The step in which an algorithm adjusts a model's parameters to fit the training examples; also called fitting.","ml/chapters/00-start-here.html","ml",""],["Training set","The part of the labelled data used to fit a model's parameters.","ml/chapters/01-generalisation.html","ml",""],["Training window","A run of T consecutive tokens used as input, paired with the same run shifted by one token as the targets, so it supplies T prediction problems at once.","deep-learning/chapters/12-building-gpt.html","dl","A1"],["Train/serve skew","A difference between how a feature is computed in training and how it is computed in production.","ml/chapters/14-leakage.html","ml",""],["Train-test contamination","Leakage caused by the same or near-identical examples appearing in both the training and the evaluation data.","ml/chapters/14-leakage.html","ml",""],["Trajectory","One complete sequence of states and actions from a start to an end, such as a prompt and the response sampled for it.","llm-training/chapters/07-policy-gradients.html","llm",""],["Trajectory metrics","Cheap automatic measures of a run, such as steps, tool errors, repeated calls and cap hits, used to find trials worth reading.","evals/chapters/08-agent-evals.html","evl","A3"],["Transcript (agent evaluation)","The complete record of a trial: messages, tool calls, results and reasoning, also called a trace or trajectory.","evals/chapters/08-agent-evals.html","evl","A3"],["Transcript monitor","A reader of the record of what an agent did, which rates how suspicious each part looks and sends the worst to a person.","control/chapters/04-transcript-monitor.html","ctl","A3"],["μTransfer","Tuning hyperparameters on a small model parametrised in μP and copying them to a large one without tuning it directly.","research-eng/chapters/03-scaling-mup.html","re","A1"],["Transfer (POET)","Testing an agent from one environment on another and adopting it if it scores higher there, so skills spread between challenges.","open-ended/chapters/05-open-ended-algorithms.html","oe","A4"],["Transformer","A neural network architecture, introduced in 2017, in which every position in a sequence attends directly to every other and all positions are processed in parallel.","deep-learning/chapters/00-start-here.html","dl",""],["Transformer (ast.NodeTransformer)","A visitor whose methods return replacement nodes, so that it can rewrite a syntax tree.","ml-foundations/chapters/21-programs-as-data.html","mlf","A1"],["Transformer block","The repeating unit of a Transformer: an attention sublayer and an MLP sublayer, each with a normalisation and a residual connection.","deep-learning/chapters/10-transformer-block.html","dl",""],["Translation equivariance","The property that shifting the input shifts the output feature map by the same amount.","deep-learning/chapters/07-convolutions.html","dl",""],["Transpose","The matrix with rows and columns swapped; it reverses the order of products, (AB)^T = B^T A^T.","ml-foundations/chapters/06-matrices.html","mlf",""],["Trap function","A small deceptive test problem whose score rises toward a poor optimum and hides a single better optimum at the far end.","open-ended/chapters/03-novelty-search.html","oe",""],["Tree of Thoughts","A prompting and search method in which the model proposes and evaluates partial reasoning steps while a search procedure decides which to extend.","open-ended/chapters/08-inference-time-search.html","oe","A2"],["Trial","One attempt by an agent at a task; agent evals run several trials per task because outputs vary.","evals/chapters/08-agent-evals.html","evl","A3"],["Triton","A Python-embedded language for GPU kernels in which each program handles a block of data and the compiler maps it to threads.","harness-eng/chapters/04-kernels-for-agents.html","he","A3"],["Triton","A Python-syntax language and compiler for writing GPU kernels in terms of blocks of values, with the compiler handling threads and shared memory.","llm-training/chapters/04-kernels.html","llm","A3"],["True negative rate","Of the outputs humans label FAIL, the fraction the judge also fails.","evals/chapters/03-llm-judges.html","evl","A2 A3"],["True positive rate","Of the outputs humans label PASS, the fraction the judge also passes.","evals/chapters/03-llm-judges.html","evl","A2 A3"],["Truncated BPTT","Backpropagation through time over chunks of a long sequence, passing the state between chunks but stopping gradients at their boundaries.","deep-learning/chapters/08-sequences-rnns.html","dl",""],["Truncated SVD","The sum of the first k terms of the SVD, which is the best rank-k approximation of a matrix.","ml-foundations/chapters/07-decompositions.html","mlf",""],["Truncation (sampling)","Removing the unlikely tail of the next-token distribution before drawing, using top-k, top-p or min-p.","deep-learning/chapters/15-decoding.html","dl",""],["Truncation with guidance","Cutting an oversized tool result and telling the model that it was cut and how to narrow the next request.","agents/chapters/05-tool-design.html","agt","A2"],["Trusted computing base","The minimum code that must be correct for a security argument to hold, kept small and out of reach.","harness-eng/chapters/03-splits-attestation.html","he","A3"],["Trusted core","The evaluator, selection rule, limits, lineage writer and guard, kept outside the loop's reach.","open-ended/chapters/17-self-modification-safety.html","oe","A3"],["Trusted editing","A control protocol in which a trusted model edits suspicious output to remove anything that looks like a backdoor.","control/chapters/04-transcript-monitor.html","ctl","A3"],["Trusted monitoring","A control protocol in which a weaker model that is trusted rates how suspicious the untrusted model's output looks.","control/chapters/04-transcript-monitor.html","ctl","A3"],["Trust region","The neighbourhood of the current policy, usually defined by a KL limit, within which a local approximation of the objective is trusted.","llm-training/chapters/08-ppo.html","llm",""],["Trust-then-verify gap","The failure of accepting a plausible-looking implementation that has not been checked against edge cases or the real requirement.","agents/chapters/22-ai-coding-tools.html","agt",""],["Two-pass inference","A scheme in which a first pass identifies the task and chooses a blend of expert vectors, and a second pass generates the answer with the adapted weights.","llm-training/chapters/17-adapters-on-demand.html","llm",""],["Typed envelope","A result record with a fixed set of typed fields, so the keeper can reject malformed input and compare numbers instead of sentences.","control/chapters/03-attested-results.html","ctl","A3"],["Typed result","A result with a fixed schema, so that free text cannot be mistaken for a number.","harness-eng/chapters/03-splits-attestation.html","he","A3"],["Type hint","An annotation such as list[int] or Callable[[int], float] that documents intended types for readers and checkers but is not enforced at run time.","ml-foundations/chapters/20-functions-objects.html","mlf","A1"],["Type I and Type II errors","A Type I error is a false positive (rejecting a true null); a Type II error is a false negative (missing a real effect).","ml-foundations/chapters/15-statistics.html","mlf","A1"],["Type promotion","The rules that decide the dtype of a result when operands have different dtypes.","ml-foundations/chapters/02-numpy-arrays.html","mlf",""],["UCB1","A bandit rule that picks the option with the highest average reward plus an optimism bonus that is larger for rarely tried options.","open-ended/chapters/01-tree-search.html","oe","A2"],["UCT","Upper confidence bounds applied to trees: choosing the move at every tree node with the UCB1 rule.","open-ended/chapters/01-tree-search.html","oe","A2"],["Unanswerable question","A test question whose answer is not in the supplied material, used to check that a system abstains instead of guessing.","evals/chapters/11-grounding-abstention.html","evl",""],["Underfitting","Using a model too rigid to capture the real pattern, so error is high on both training and new data.","ml/chapters/01-generalisation.html","ml",""],["Underflow","A result smaller than the format's smallest representable value, which becomes zero.","ml-foundations/chapters/11-numerics.html","mlf",""],["Unigram language model tokeniser","A subword method that starts from a large candidate vocabulary and prunes the pieces whose removal costs least, allowing several segmentations of one word.","deep-learning/chapters/13-tokenisation.html","dl","A1"],["Unit vector","A vector of length 1, obtained by dividing a vector by its norm so that only its direction remains.","ml-foundations/chapters/05-vectors-similarity.html","mlf",""],["Universal approximation theorem","The result that a network with one hidden non-linear layer and enough units can approximate any reasonable continuous function on a bounded region.","deep-learning/chapters/01-neurons-layers.html","dl",""],["Unknown token","A placeholder used by word-level vocabularies for any word they have never seen, which loses the word's identity.","deep-learning/chapters/13-tokenisation.html","dl","A1"],["Unsupervised learning","Looking for structure in data without labels, as in clustering and dimensionality reduction.","ml/chapters/00-start-here.html","ml",""],["Untrusted code","Code that nobody has read or vouched for, such as a randomly mutated or model-written program, which must be checked before it runs.","ml-foundations/chapters/21-programs-as-data.html","mlf","A1"],["Untrusted monitoring","A control protocol in which a second copy of the untrusted model rates the output, with steps to prevent collusion.","control/chapters/04-transcript-monitor.html","ctl","A3"],["Upper confidence bound","A bandit strategy that adds to each action's average an optimism bonus that shrinks as the action is tried more often.","llm-training/chapters/06-bandits-mdps.html","llm",""],["Upstream gradient","The gradient of the loss with respect to a layer's output, handed backwards to that layer by the one above it.","deep-learning/chapters/02-backpropagation.html","dl",""],["Uptraining","Converting an existing multi-head checkpoint to grouped-query attention with a small fraction of the original training compute.","deep-learning/chapters/19-efficient-attention.html","dl","A3"],["Usefulness (AI control)","How much correct work a protocol gets when the untrusted model is honest, scaled so the trusted model alone scores 0 and the untrusted model alone scores 1.","control/chapters/04-transcript-monitor.html","ctl","A3"],["UTF-8","The encoding that turns any Unicode text into a sequence of one to four bytes per character.","deep-learning/chapters/13-tokenisation.html","dl","A1"],["Utilisation","The share of time a GPU is doing useful work; idle time is billed but produces no tokens.","llm-training/chapters/22-token-economics.html","llm","A1"],["Utility","A function that turns a solution into a number so that two solutions can be compared.","open-ended/chapters/21-self-referential-improvers.html","oe","A4"],["Vacuous truth","A statement about an empty set that holds automatically, such as 'no tests failed' when the test list has been emptied.","open-ended/chapters/15-evaluator-hacking.html","oe","A3"],["val_bpb","Validation bits per byte: the model's cross-entropy on held-out text converted to bits and divided by bytes, so that models with different tokenisers can be compared.","research-eng/chapters/01-research-loop.html","re","A1"],["Validation loss","The loss on held-out text the model never trains on, used to judge whether it has learned something general.","deep-learning/chapters/12-building-gpt.html","dl","A1"],["Validation set","The held-out part of the labelled data used to compare candidates and choose hyperparameters.","ml/chapters/01-generalisation.html","ml",""],["Value (attention)","The vector attached to each position that is passed on, in proportion to its attention weight, when the position is read.","deep-learning/chapters/09-attention.html","dl",""],["Value function","The expected return from a state (or state and action) when following a given policy.","llm-training/chapters/06-bandits-mdps.html","llm",""],["Value head","A linear layer on a language model's hidden states that outputs one predicted return per token position instead of vocabulary logits.","llm-training/chapters/09-value-functions.html","llm",""],["Value target","The regression target for the critic in PPO, equal to the GAE advantage plus the value predicted when the data was collected.","llm-training/chapters/09-value-functions.html","llm",""],["Vanishing gradient","The shrinking of gradients towards zero as they are multiplied through many steps, so early inputs get almost no learning signal.","deep-learning/chapters/08-sequences-rnns.html","dl",""],["Vanishing gradient","The collapse of a gradient towards zero when it passes back through many layers whose local derivatives are below one.","ml-foundations/chapters/08-derivatives.html","mlf",""],["Vanishing gradients","Gradients that shrink exponentially towards the early layers of a deep network until they carry no usable signal.","deep-learning/chapters/03-training-dynamics.html","dl","A1"],["Variance","The expected squared distance from the mean, measuring spread; it adds for independent variables.","ml-foundations/chapters/12-probability.html","mlf",""],["Variation","The differences between individuals in a population, which give selection something to choose between.","open-ended/chapters/19-evolution-for-builders.html","oe","A1"],["Vector","An ordered list of numbers that can also be drawn as an arrow from the origin; the basic object of linear algebra.","ml-foundations/chapters/05-vectors-similarity.html","mlf",""],["Vectorising","Rewriting a per-element loop as one operation on a whole array so that compiled code runs the loop.","ml-foundations/chapters/01-python-numerics.html","mlf",""],["Vector-Jacobian product","The product of an incoming gradient with a layer's Jacobian, which backpropagation computes without ever forming the Jacobian.","deep-learning/chapters/02-backpropagation.html","dl",""],["Vector-Jacobian product","The backward rule of a tensor operation: from the gradient at its output, compute the gradient at its inputs without building the Jacobian.","ml-foundations/chapters/09-autodiff.html","mlf",""],["VeLO","A large learned optimiser from Metz et al. (2022), meta-trained on many tasks and released with code and a benchmark.","deep-learning/chapters/24-learned-optimisers.html","dl","A2 A4"],["Verbosity bias","A judge's tendency to prefer longer answers even when the extra length adds nothing.","evals/chapters/03-llm-judges.html","evl","A2 A3"],["Verifiable reward","A reward obtained by running a checker against ground truth, such as comparing a final answer or running tests, so it cannot be flattered the way a learned model can.","llm-training/chapters/14-rlvr-grpo.html","llm","A2 A4"],["Verification loop","A cycle in which an agent edits, runs a check such as tests or a build, reads the result and iterates until the check passes, instead of stopping when its work looks done.","agents/chapters/22-ai-coding-tools.html","agt",""],["Verifier","A checker, exact or learned, that decides whether a candidate answer is correct or how good it is.","open-ended/chapters/08-inference-time-search.html","oe","A2"],["View (array)","An array that describes the same memory as another array, so writing through one changes the other.","ml-foundations/chapters/02-numpy-arrays.html","mlf",""],["Virtual environment","A directory with its own Python interpreter link and installed packages, keeping one project's dependencies separate from others.","ml-foundations/chapters/04-reproducible-experiments.html","mlf","A1"],["Virtual loss","A temporary pessimistic visit added to a node so that parallel search workers spread out instead of choosing the same leaf.","open-ended/chapters/01-tree-search.html","oe","A2"],["Vision-language model","A model that takes images and text together and produces text, usually a language model that reads image tokens placed in its context.","deep-learning/chapters/21-vision-language.html","dl",""],["Vision Transformer","A Transformer that treats the patches of an image as its input sequence, with bidirectional attention.","deep-learning/chapters/21-vision-language.html","dl",""],["Visitor (ast.NodeVisitor)","A class with one method per node type that walks a syntax tree and keeps notes without changing it.","ml-foundations/chapters/21-programs-as-data.html","mlf","A1"],["Visual instruction tuning","Fine-tuning a vision-language model on conversations about images, with the loss on the answer tokens only.","deep-learning/chapters/21-vision-language.html","dl",""],["Vocabulary mismatch","The failure of a word-matching search when a document uses different words from the query, such as spent against spending.","agents/chapters/16-deep-research.html","agt",""],["Voting","A parallelisation variant in which the same task runs several times and the answers are combined, usually by majority, to raise confidence.","agents/chapters/13-workflow-patterns.html","agt",""],["Voyager","A Minecraft agent that uses a language model to set its own tasks, write code for them, verify the code, and store working programs in a skill library.","open-ended/chapters/07-lifelong-agents.html","oe","A4"],["Wall-clock budget","A limit on elapsed real time for a run, rather than on steps or tokens.","research-eng/chapters/01-research-loop.html","re","A1"],["Wall-clock timeout","A limit on elapsed time held by the parent process, which stops an idle process that uses no CPU time.","control/chapters/02-egress-sandbox.html","ctl","A3"],["Warmup","A short initial phase in which the learning rate rises from near zero to its peak so early steps are not destabilising.","ml-foundations/chapters/10-optimisers.html","mlf",""],["Weight","A learned number that scales one input of a neuron, setting how much and in which direction it matters.","deep-learning/chapters/01-neurons-layers.html","dl",""],["Weight decay","Multiplying the weights by a factor slightly below one at every step, so that only weights the data keeps pushing stay large.","deep-learning/chapters/04-deep-regularisation.html","dl",""],["Weight decay","Shrinking every weight by a small fraction at each step to discourage large weights.","ml-foundations/chapters/10-optimisers.html","mlf",""],["Weight sharing","Reusing the same weights at every position of the input, so the parameter count does not grow with the input size.","deep-learning/chapters/07-convolutions.html","dl",""],["Weight tying","Reusing the input embedding matrix, transposed, as the output layer of a language model to save parameters.","deep-learning/chapters/06-embeddings.html","dl",""],["Whitelist","A list of the only things allowed, such as the node types a candidate program may contain, so that anything not listed is refused.","ml-foundations/chapters/21-programs-as-data.html","mlf","A1"],["Wide and long format","Two layouts of the same data: wide has one column per value of a variable (such as month), long has one row per observation.","ml-foundations/chapters/03-data-wrangling.html","mlf",""],["Wilson interval","A confidence interval for a proportion that behaves sensibly for small samples and scores near 0 or 100 percent.","evals/chapters/04-eval-statistics.html","evl","A1 A2 A3"],["Wilson interval","A confidence interval for a proportion that behaves well at small counts and near 0 or 1.","harness-eng/chapters/05-research-benchmarks.html","he","A2"],["Wilson interval","A confidence interval for a proportion that stays inside 0 and 1 and covers near the stated rate even for small samples and extreme rates.","ml-foundations/chapters/15-statistics.html","mlf","A1"],["Windowed file viewer","A file-reading tool that shows a fixed number of numbered lines at a time, keeping each observation small.","agents/chapters/18-coding-agents.html","agt","A2"],["Window function","A SQL function that computes a value over a set of related rows without collapsing them into one row.","ml-foundations/chapters/03-data-wrangling.html","mlf",""],["Winner's curse","The upward bias in the best of several noisy measurements, because luck as well as quality put it on top.","evals/chapters/09-leaderboards.html","evl",""],["Winner's curse","The exaggeration of effect sizes among results that pass a significance filter in underpowered experiments.","ml-foundations/chapters/15-statistics.html","mlf","A1"],["Winner's curse","The upward bias in the score of the best of many noisy measurements, which grows with the number of candidates and shrinks with the size of the evaluation set.","open-ended/chapters/12-meta-agent-search.html","oe","A2 A4"],["Winner's curse","The upward bias in the best of many noisy measurements, which makes a selected result look better than it is.","research-eng/chapters/02-proxies-noise.html","re","A1"],["Winner's curse","The tendency of a candidate chosen for a high noisy score to look better than it really is, because the selection kept the lucky noise.","rsi-measurement/chapters/01-level-one.html","rsi","A4"],["word2vec","A family of small models that learn word vectors by predicting words from their neighbours or neighbours from words.","deep-learning/chapters/06-embeddings.html","dl",""],["WordPiece","A subword method used by BERT that grows its vocabulary by merges chosen to raise the likelihood of the training text and marks word-internal pieces with a prefix.","deep-learning/chapters/13-tokenisation.html","dl","A1"],["Worker pool","A fixed set of workers that take jobs from a queue, so many tasks can run at once without starting a worker for each.","ml-foundations/chapters/22-running-candidates.html","mlf","A1"],["Workflow","A system in which the programmer fixes the sequence of steps in code, and the model only fills in individual steps such as writing a summary.","agents/chapters/00-start-here.html","agt",""],["Working memory","The context window itself: the current task, recent messages and tool results, fast and exact but lost when the run ends or the window is cleared.","agents/chapters/11-memory.html","agt","A2"],["Write boundary","The line between what a principal can change and what it cannot; anything a decision relies on belongs outside the proposer's.","control/chapters/01-threat-model.html","ctl","A3"],["Write boundary","The set of files and processes a proposer may change; the scorer and verifier should lie outside it.","harness-eng/chapters/01-harness-engineering.html","he","A2"],["Write boundary","The set of files and resources a proposer is allowed to change; the evaluator should sit outside it.","research-eng/chapters/01-research-loop.html","re","A1"],["Writer and reviewer pattern","Using one session to implement a change and a separate fresh-context session to review it, so the reviewer is not anchored on the author's reasoning.","agents/chapters/22-ai-coding-tools.html","agt",""],["Write-up template","The six-part report shape: claim, replication, extension, negative results, integrity details and reproduction.","research-eng/chapters/06-write-up.html","re","A1"],["Write-up template","The fixed two-to-six-page shape every artifact ships in: claim, replication, extension, negative results, hacking rate and costs, and a one-command reproduction.","rsi-measurement/chapters/00-start-here.html","rsi","A4"],["Xavier initialisation","Drawing weights with variance 2 divided by fan-in plus fan-out, chosen to keep signal scale constant for tanh-like activations.","deep-learning/chapters/03-training-dynamics.html","dl","A1"],["YaRN","A context-extension method that scales rotary frequencies unevenly across dimensions and adds a temperature correction to attention.","deep-learning/chapters/11-positions.html","dl",""],["Young-Daly interval","The checkpoint interval that minimises wasted time, approximately the square root of twice the checkpoint cost times the mean time between failures.","llm-training/chapters/05-long-runs.html","llm","A1"],["ZeRO","The Zero Redundancy Optimizer: data parallelism that shards optimiser state, then gradients, then weights across GPUs instead of replicating them.","llm-training/chapters/03-parallelism.html","llm",""],["Zero-shot adapter generation","Producing an adapter for a task the generator was not trained on, from its description alone and without task data.","llm-training/chapters/17-adapters-on-demand.html","llm",""],["Zero-shot generalisation","Solving tasks in a new environment without further training, here by reusing a skill library built elsewhere.","open-ended/chapters/07-lifelong-agents.html","oe","A4"],["Zero-shot prompting","Asking a model to do a task with instructions alone and no worked examples.","agents/chapters/04-prompting.html","agt","A2"],["z-loss","An auxiliary loss on the log of the softmax denominator that keeps the output logits close to log-probabilities and helps stability.","deep-learning/chapters/17-training-stability.html","dl","A1"],["Zombie process","A process that has ended but whose exit status has not yet been collected by its parent.","research-eng/chapters/05-rust-runner.html","re","A1"]];
